insert into public.peliculas (tmdb_id, media_type, titulo, titulo_tmdb, titulo_original, anio, direccion, sinopsis, poster_path, backdrop_path, vote_average, trailer_youtube, listas, pagina_libro, donde_ver, cruce, candidatos) values
(35987, 'movie', 'Lola Montes', 'Lola Montes', 'Lola Montès', 1955, 'Max Ophüls', 'Lola Montes (Martine Carol), cortesana y bailarina famosa en toda Europa, fue la amante de grandes hombres como el músico húngaro Franz Liszt o Luis II de Baviera. Ya en el ocaso de su carrera, trabajó en un circo de Nueva Orleáns (Luisiana), donde realizaba un número acrobático mientras un maestro de ceremonias (Peter Ustinov) narraba al público su escandalosa vida.', '/woP4EwZg5LE42ypEOG1FfGlUtBM.jpg', '/d0v44yJkq95FZZFCVlzaHKwcZvU.jpg', 6.9, 'KuLb53N-XCY', array['1001']::text[], 326, null, 'segura', null),
(830, 'movie', 'Planeta prohibido', 'Planeta prohibido', 'Forbidden Planet', 1956, 'Fred M. Wilcox', 'En el siglo XXII, la nave del capitán Adams viaja al remoto planeta Altair IV para rescatar a una expedición perdida. Al llegar, solo encuentran a dos supervivientes: el misterioso doctor Morbius y su hija Altaira, quienes viven aislados junto al icónico Robby, el Robot. Morbius les advierte de que una fuerza invisible y letal habita el planeta, la cual destruyó al resto de su tripulación y ahora amenaza a los recién llegados. El misterio se complica al descubrir que el subsuelo alberga la inmensa tecnología de los Krell, una avanzada raza alienígena extinta. Dato clave: La película es una brillante transposición al espacio de La Tempestad de William Shakespeare, donde Morbius representa al mago Próspero, su hija a Miranda, y el monstruo invisible encarna los peligros del subconsciente humano.', '/nrmkVoVF8MaIKwBRjzmJjgR7zXA.jpg', '/o2Vx6xE0IHizkYMFqXau2YKLfQp.jpg', 7.3, '_jnHydCeYcc', array['1001']::text[], 326, null, 'segura', null),
(33319, 'movie', 'El arpa birmana', 'El arpa Birmana', 'ビルマの竪琴', 1956, '市川崑', 'Año 1945; los japoneses están a punto de firmar la paz en Birmania. Un soldado, admirado por sus compañeros porque toca el arpa, es nombrado mediador japonés.', '/bQAgUqRPrVFhC6DfPIjsCQ7SWn4.jpg', '/oUX2SiqoXorKUjd82Ax7mMjKI2R.jpg', 7.9, 'LA6xYjEw5Uk', array['1001']::text[], 327, null, 'segura', null),
(3114, 'movie', 'Centauros del desierto', 'Centauros del desierto', 'The Searchers', 1956, 'John Ford', 'Texas. En 1868, tres años después de la guerra de Secesión, Ethan Edwards, un hombre solitario, vuelve derrotado a su hogar. La persecución de los comanches que han raptado a una de sus sobrinas se convertirá en un modo de vida para él y para Martin, un muchacho mestizo adoptado por su familia.', '/dmnGvL8GRP0hEG7Uph0FxXS9aiK.jpg', '/gQpNejv8i1MUasARDIHAJ7wdBMu.jpg', 7.7, 'pJXgjw_5erE', array['1001']::text[], 328, null, 'segura', null),
(69605, 'movie', 'Escrito sobre el viento', 'Escrito sobre el viento', 'Written on the Wind', 1956, 'Douglas Sirk', 'Kile Hadley, un magnate del petróleo, y Mitch Wayne, su mejor amigo y empleado, se enamoran de la misma mujer: la secretaria Lucy Moore. Kile, que es un alcohólico irresponsable, se casa con ella, aunque Mitch está convencido de que con esta boda Lucy comete un gran error. Al cabo de un año, contra todo pronóstico, Kyle parece un hombre nuevo: ha dejado de beber y presta más atención a sus negocios.', '/qzB7MYXyTtajtYuEgIbo8KWoKzm.jpg', '/gb7CnfONI8mWuUsxuqkafWEO71N.jpg', 7.0, 'WHdworuKmwQ', array['1001']::text[], 330, null, 'segura', null),
(15244, 'movie', 'Un condenado a muerte se ha escapado', 'Un condenado a muerte se ha escapado', 'Un condamné à mort s''est échappé', 1956, 'Robert Bresson', 'Abril de 1943, en plena Segunda Guerra Mundial. Fontaine, un joven de 27 años miembro de la Resistencia francesa, que lucha contra la ocupación nazi, es arrestado por la Gestapo para ser interrogado.', '/dly2pAkej6rFRwBElN3XutPgLR4.jpg', '/lNe2z2qQf0G5gzM51ZyJD0zCDVk.jpg', 8.0, 'o6nHFpKK6Lc', array['1001']::text[], 330, null, 'segura', null),
(574, 'movie', 'El hombre que sabía demasiado', 'El hombre que sabía demasiado', 'The Man Who Knew Too Much', 1956, 'Alfred Hitchcock', 'Una familia americana, compuesta por el doctor Ben MacKenna, su mujer y su hijo Hank, está pasando unas vacaciones en Marruecos. Tras la muerte de un espía en brazos de Ben, mientras visitaban el mercado de Marrakech, el matrimonio descubre que su hijo ha sido secuestrado. Sin saber en quién confiar, los MacKenna se ven envueltos en una angustiosa pesadilla que tiene que ver con una operación de espionaje internacional.', '/spS9xPGJSSpNjsPCarL8kM3Upx.jpg', '/bXPKTWAuRO8Mu5rLCORFagX0YZ1.jpg', 7.4, 'YP8brOVQnKA', array['1001']::text[], 331, null, 'segura', null),
(1712, 'movie', 'Gigante', 'Gigante', 'Giant', 1956, 'George Stevens', 'Jordan "Bick" Benedict, un joven terrateniente, llega a su inmenso rancho de Texas con su flamante esposa Leslie Benedict, una rica y bella muchacha del Este. No tardan mucho en descubrir que pertenecen a mundos radicalmente opuestos y que los separa un abismo. Jett Rink es un arrogante y joven empleado de los Benedict que tiene la suerte de encontrar petróleo en unas tierras que le ha dejado en su testamento Luz, la hermana de Jordan; pero, a pesar de su inmensa fortuna, no consigue lo que realmente le importa: Leslie.', '/oruoMYVned5WVdd5uRBXIuRcE1B.jpg', '/sm3ErHMXQLaNdo74vbIa1JRXIXS.jpg', 7.6, 'SZZTWO4_wto', array['1001']::text[], 331, null, 'segura', null),
(43316, 'movie', 'Solo el cielo lo sabe', 'Sólo el cielo lo sabe', 'All That Heaven Allows', 1955, 'Douglas Sirk', 'Una viuda de buena familia inicia un romance con su apuesto jardinero. A pesar de pertenecer a dos mundos completamente diferentes deciden casarse, pero su amor tropieza con el rechazo de los hijos de la mujer y de su círculo social.', '/5mycJKgG5fjkyYqtJXjkpnqZG2M.jpg', '/iQQ4jjYV8fgdEHDgkgSrc4mWgUx.jpg', 7.3, '3H8yXanHW1I', array['1001']::text[], 332, null, 'segura', null),
(11549, 'movie', 'La invasión de los ladrones de cuerpos', 'La invasión de los ladrones de cuerpos', 'Invasion of the Body Snatchers', 1956, 'Don Siegel', 'En una pequeña ciudad de California empiezan a suceder cosas muy extrañas: el comportamiento de algunas personas cambia de tal manera que causa estupor e incluso miedo entre sus parientes y amigos.', '/zuQRECfEODUkXc7cD04BDI8HC7a.jpg', '/qcLHMO01oECjbL8MUPRXsLOMFhx.jpg', 7.5, '9SqN8wHry2M', array['1001']::text[], 334, null, 'segura', null),
(26036, 'movie', 'Delirio de locura', 'Más poderoso que la vida', 'Bigger Than Life', 1956, 'Nicholas Ray', 'Debido a una rara enfermedad, Ed Avery debe tomar una droga en experimentación que le provoca alteraciones mentales que repercutirán en su trabajo como profesor y en sus relaciones familiares.', '/7syp6kzxGDFoR7LPyTCnvGzn5Qq.jpg', '/gZmP6u7Gy4EUrDBIgpyOOwcq7Wj.jpg', 7.2, '5NvuvQ6pQIQ', array['1001']::text[], 335, null, 'probable', null),
(22527, 'movie', 'Falso culpable', 'Falso culpable', 'The Wrong Man', 1956, 'Alfred Hitchcock', 'Manny es un músico de jazz que vive apaciblemente en Nueva York con su esposa Rose y sus dos hijos pequeños. En una aseguradora, una empleada lo confunde con un ladrón que había robado allí unos días antes y lo denuncia a la policía. Comienza entonces para él una angustiosa pesadilla: es detenido y acusado de una serie de hurtos perpetrados en el barrio. Lo terrible es que todos los testigos y las pruebas caligráficas corroboran su culpabilidad. Tras salir bajo fianza, intentará demostrar su inocencia. Mientras tanto, su esposa sufre una aguda crisis nerviosa y es internada en un psiquiátrico.', '/6cOkJ4wuwKGnpfjuswPdxinNObV.jpg', '/e0tZ5Kjg5mukFGcxEddCZymAxH4.jpg', 7.1, '5NQ_9OYmovo', array['1001']::text[], 335, null, 'segura', null),
(11424, 'movie', 'Alta sociedad', 'Alta sociedad', 'High Society', 1956, 'Charles Walters', 'Tracy va a contraer matrimonio por segunda vez. Sin embargo, su primer marido se da cuenta de que sigue locamente enamorado de ella e intenta conseguir que vuelva a su lado.  Remake de la mítica ''Historias de Filadelfia'', adornada con un espléndido reparto y las canciones de Bing Crosby', '/tDuUITgUqm4tZpV7uAnLBqBdgJB.jpg', '/oV3FcC9A8gQCphOt40IcCwujNx0.jpg', 6.8, 'bYIFS2jxwbk', array['1001']::text[], 336, null, 'segura', null),
(6844, 'movie', 'Los diez mandamientos', 'Los Diez Mandamientos', 'The Ten Commandments', 1956, 'Cecil B. DeMille', 'Drama bíblico ambientado en el Antiguo Egipto que narra la historia de Moisés, favorito de la familia del faraón, el cual decide renunciar a su vida de privilegios para conducir a su pueblo, los hebreos esclavizados en Egipto, hacia la libertad.', '/kUfNxdftpiADE92Ch2Z0IRZjwwm.jpg', '/3e3dVaVrla2GH6CWKbNRjTvk3s8.jpg', 7.8, 'wRBV8OHLC4Q', array['1001']::text[], 336, null, 'segura', null),
(389, 'movie', 'Doce hombres en pugna', 'Doce hombres sin piedad', '12 Angry Men', 1957, 'Sidney Lumet', 'Doce jurados deben decidir si un joven es culpable de asesinato. Once votan que sí; uno tiene dudas y empieza a discutir.', '/t88XfoxO5cX3f0qaSxWsBS0Lc3.jpg', '/qqHQsStV6exghCM7zbObuYBiYxw.jpg', 8.6, 'TEN-2uTi2c0', array['1001','clasicos']::text[], 337, null, 'segura', null),
(490, 'movie', 'El séptimo sello', 'El séptimo sello', 'Det sjunde inseglet', 1957, 'Ingmar Bergman', 'Un caballero que vuelve de las Cruzadas encuentra a la Muerte y la desafía a una partida de ajedrez para ganar tiempo.', '/qo3JypyrkPvH8Na3Ir0IpjCwOCS.jpg', '/6s2BqtDvp1BMiP70zCDU5OW6hMy.jpg', 8.1, 'vZucwtdSvJ8', array['1001','clasicos']::text[], 338, null, 'segura', null),
(8356, 'movie', 'Tú y yo', 'Tú y yo', 'An Affair to Remember', 1957, 'Leo McCarey', 'Un elegante playboy y una bella cantante de un club nocturno se conocen a bordo de un lujoso transatlántico y surge entre ellos un apasionado romance. Aunque ambos están comprometidos (ella es la amante de un magnate y él se va a casar con una rica heredera), establecen un pacto antes de abandonar el barco: encontrarse en el Empire State Building en un plazo de seis meses si siguen sintiendo lo mismo el uno por el otro.', '/mNnUtqK6O4jyLX91RKUE8TfsnSG.jpg', '/coEqWrercSh1vwbuLGgxHD0kgWo.jpg', 7.4, '1qFSl4DiKXA', array['1001']::text[], 340, null, 'segura', null),
(614, 'movie', 'Fresas salvajes', 'Fresas salvajes', 'Smultronstället', 1957, 'Ingmar Bergman', 'El profesor Borg, un eminente físico, debe ir a Estocolmo para recibir un homenaje de su universidad. Sobrecogido, tras un sueño en el que contempla su propio cadáver, decide emprender el viaje en coche con su nuera, que acaba de abandonar su casa, tras una discusión con su marido, que se niega a tener hijos. Durante el viaje se detiene en la casa donde pasaba las vacaciones cuando era niño, un lugar donde crecen las fresas salvajes y donde vivió su primer amor.', '/k4f0IpHOJqAK9Cvy3FLH9w90qWX.jpg', '/BBVAUchYvkmPThVIqipgAfabfl.jpg', 8.1, 'EwMgTyVbCS0', array['1001']::text[], 341, null, 'segura', null),
(19426, 'movie', 'Las noches de Cabiria', 'Las noches de Cabiria', 'Le notti di Cabiria', 1957, 'Federico Fellini', 'Cabiria es una prostituta que ejerce como tal en uno de los barrios más pobres de Roma. Sueña, sin embargo, con encontrar el amor verdadero, un hombre que la aparte de la calle y a quien pueda entregarse en cuerpo y alma. Su bondad y su ingenuidad la convierten en víctima propicia de sucesivos vividores que se aprovechan de ella, le roban y la golpean. A pesar de sus fracasos, recobra la esperanza una y otra vez. Todo parece cambiar cuando abre su corazón a un tímido contable que le propone matrimonio.', '/3SeL03QzrnOHkybPOTI9Jpzhu2F.jpg', '/9yepEBnQNcKzWWyHdUiX8Mnqc6U.jpg', 8.0, 'nG91owD7UjM', array['1001']::text[], 342, null, 'segura', null),
(31682, 'movie', 'El increíble hombre menguante', 'El increíble hombre menguante', 'The Incredible Shrinking Man', 1957, 'Jack Arnold', 'Cuando Scott Carey se ve expuesto a una combinación de radiación e insecticida, empieza a menguar sin que la medicina sea capaz de encontrar solución a su mal.', '/xWRyvVVlhSblpeP3iDHa7AXFLoO.jpg', '/bd9lxQ4SgnNb6NPIph4pz5HGLpY.jpg', 7.5, 'e5RsQ6qsaZU', array['1001']::text[], 343, null, 'segura', null),
(3777, 'movie', 'Trono de sangre', 'Trono de sangre', '蜘蛛巣城', 1957, 'Akira Kurosawa', 'Japón feudal, siglo XVI. Adaptación del "Macbeth" de William Shakespeare. Cuando los generales Taketori Washizu y Yoshaki Miki regresan de una victoriosa batalla, se encuentran en el camino con una extraña anciana, que profetiza que Washizu llegará a ser el señor del Castillo del Norte. A partir de ese momento, su esposa lo instigará hasta convencerlo de que debe cumplir su destino.', '/4qggbvXbBZjvEALqEjyAQdaMTfM.jpg', '/rohRr9XqTRF8YwLMGAnTprg3GnL.jpg', 7.9, 'oa0CcrHB4rc', array['1001']::text[], 343, null, 'segura', null),
(897, 'movie', 'Aparajito (El invencible)', 'El invencible', 'অপরাজিত', 1956, 'Satyajit Ray', 'Relata la juventud de Apu en Benarés, su deseo de independizarse y estudiar en Calcuta para poder llevar una vida diferente a la que han conocido sus padres.', '/f94STIuH4S7tqs7nKFbT9SJojqi.jpg', '/qDEZmaaAGhEso6kvB5kk1CROPwG.jpg', 7.8, 'mgv68E_o6VM', array['1001']::text[], 344, null, 'segura', null),
(22201, 'movie', 'Duelo de titanes', 'Duelo de titanes', 'Gunfight at the O.K. Corral', 1957, 'John Sturges', 'Wyatt Earp, el sheriff de Dodge City, se encuentra de nuevo con John "Doc" Holliday, un jugador borracho y tuberculoso a quien salvó la vida en una ocasión. Juntos tendrán que enfrentarse a la banda de los Clanton, una poderosa familia que tiene atemorizado a todo el pueblo.', '/6ntO2RkW9yeMhPhhtVeWYXN6J8D.jpg', '/n4Ec7koHqqFKz0fC7vIitNxxqwi.jpg', 7.0, 'xhvD9zcPXU4', array['1001']::text[], 345, null, 'segura', null),
(826, 'movie', 'El puente sobre el río Kwai', 'El puente sobre el río Kwai', 'The Bridge on the River Kwai', 1957, 'David Lean', 'Durante la Segunda Guerra Mundial (1939-1945), un grupo de prisioneros británicos son obligados por los japoneses a construir un puente. Los oficiales, capitaneados por su flemático coronel, se opondrán a toda orden que viole la Convención de Ginebra sobre los derechos y las condiciones de vida de los prisioneros de guerra.', '/z5uKyonXIGiVub5RtJKaPgGevlI.jpg', '/cGi9obHiooPoNR4JX72L9RooeOY.jpg', 7.8, 'k17_5rt8dIQ', array['1001']::text[], 345, null, 'segura', null),
(917, 'movie', 'Madre India (Bharat Mata)', 'Madre India', 'मदर इण्डिया', 1957, 'Mehboob Khan', 'Radha (Nargis), ahora una anciana mujer, recuerda su pasado y su vida de casada. Su familia tiene que trabajar muy duro para pagar a un prestamista. El marido de Radha (Raj Kumar) pierde sus brazos en un accidente y desatiende a la familia; y ella tiene que criar sola a sus niños. (FILMAFFINITY)', '/m6zRH8SPypN5jouG5PU2EOMoZXl.jpg', '/bkzPygcInZMOKpnNhSHlbqVNinJ.jpg', 7.0, 'OFWHKtISBrY', array['1001']::text[], 346, null, 'segura', null),
(38360, 'movie', 'Cuando migran las grullas', 'Cuando pasan las cigüeñas', 'Летят журавли', 1957, 'Mijaíl Kalatózov', 'Veronika y Boris se juntan en Moscú poco antes de la Segunda Guerra Mundial. Caminando a lo largo del río, ven las cigüeñas volar sobre sus cabezas y prometen encontrarse antes de que Boris se vaya a luchar. Boris se pierde la reunión y se dirige al frente, mientras Veronika espera pacientemente, enviando cartas fielmente. Después de que su casa es bombardeada, Veronika se muda con la familia de Boris, en compañía de un primo con sus propias intenciones.', '/ijPJ98012j35WFW6fVjnOPuTlCm.jpg', '/r6bIGLFJ2ml9L970RNpuwDyb4Af.jpg', 7.9, 'IkINuHcP6us', array['1001']::text[], 347, null, 'probable', null),
(976, 'movie', 'Chantaje en Broadway', 'Chantaje en Broadway', 'Sweet Smell of Success', 1957, 'Alexander Mackendrick', 'Burt Lancaster y Tony Curtis se adentran en el misterioso mundo de la fauna nocturna que puebla el centro de Manhattan, en un juego siniestro de poder y en un universo de supervivencia. Con uno de los diálogos más corrosivos del cine de todos los tiempos esta película es uno de los títulos más grandes que Hollywood ha creado. Burt Lancaster, encarna a un poderoso, famoso y ambicioso columnista que domina toda una ciudad a través de la información que habitualmente consumen sus más de 60 millones de lectores. Pero como todo el mundo tiene un punto débil: su hermana pequeña. Todo cambiará cuando ésta se enamora apasionadamente de un guitarrista de jazz y los instintos más básicos del periodista salgan a relucir.', '/aqjd1fUiVTdGAVTxyL0ebKra5DL.jpg', '/6L1Co3uRWuoaqDxpWvGDvgXms7T.jpg', 7.6, 'gBbPlyHxj8c', array['1001']::text[], 348, null, 'segura', null),
(975, 'movie', 'Senderos de gloria', 'Senderos de gloria', 'Paths of Glory', 1957, 'Stanley Kubrick', 'Primera Guerra Mundial (1914-1918). En 1916, en Francia, el general Boulard ordena la conquista de una inexpugnable posición alemana y encarga esa misión al ambicioso general Mireau. El encargado de dirigir el ataque será el coronel Dax. La toma de la colina resulta un infierno, y el regimiento emprende la retirada hacia las trincheras. El alto mando militar, irritado por la derrota, decide imponer al regimiento un terrible castigo que sirva de ejemplo a los demás soldados.', '/vz8J8nTbF5JP7PQK4VNVsO8rzCy.jpg', '/nbMY2UcNnaAr3jrrowzN0NaxQyr.jpg', 8.3, 'FESvZ0HG2p4', array['1001']::text[], 348, null, 'segura', null),
(14674, 'movie', 'El hombre del oeste', 'El hombre del oeste', 'Man of the West', 1958, 'Anthony Mann', 'Arizona, 1874. Link Jones, un antiguo pistolero dedicado al bandidaje, se ha redimido y es un hombre regenerado y respetado por sus vecinos. Tanto es así, que, depositando toda su confianza en él, le han entregado seiscientos dólares destinados a contratar a una maestra para la escuela que piensan inaugurar. Con esta misión Link emprende un viaje en tren, pero inesperadamente el destino lo devuelve a su pasado, poniendo en peligro su reputación.', '/ur13lJvGGxznFjp8U2W9GYCGYwn.jpg', '/lVwjw1NxGvk47meU6R7vVnQD4CM.jpg', 6.6, '7b1QuCRs7PQ', array['1001']::text[], 349, null, 'segura', null),
(1480, 'movie', 'Sed de mal', 'Sed de mal', 'Touch of Evil', 1958, 'Orson Welles', 'Un agente de la policía de narcóticos (Heston) llega a la frontera mexicana con su esposa justo en el momento en que explota una bomba. Inmediatamente se hace cargo de la investigación contando con la colaboración de Quinlan (Welles), el jefe de la policía local, muy conocido en la zona por sus métodos expeditivos y poco ortodoxos. Una lucha feroz se desata entre los dos hombres, pues cada uno de ellos tiene pruebas contra el otro.', '/vTJXbaDIsJVO2L2IyHLqalRogwu.jpg', '/4VoHeMD5EugrxmEfeUgxXpXyzuR.jpg', 7.7, 'wuSCUVqaDZw', array['1001']::text[], 350, null, 'segura', null),
(47324, 'movie', 'Estación Central (Bab El Hadid)', 'Estación central', 'باب الحديد', 1958, 'Youssef Chahine', 'En la estación principal de El Cairo, las personas se cruzan durante unos instantes, mientras las vidas de los porteadores, vendedores ambulantes y demás trabajadores se mezclan. Otros seres invisibles ocupan los vagones vacíos durante la noche y desaparecen entre la multitud de día, aportando vida y alma a la estación. Entre ellos se encuentra el lisiado Kinawi, perdidamente enamorado de la guapa Hanuma, que va a casarse con Abu Sri, el viril y musculoso jefe de los porteadores.', '/rXkIpskDfSI02BDU1n10A33uxmk.jpg', '/bYyHPVFXNFAApU6erUCVwARH7rA.jpg', 7.4, 'bOJpiUZphTE', array['1001']::text[], 352, null, 'segura', null),
(11414, 'movie', 'Fugitivos', 'Fugitivos', 'The Defiant Ones', 1958, 'Stanley Kramer', 'Odisea de dos fugitivos encadenados y condenados a huir juntos. Ambos desean lo mismo, alcanzar la libertad, pero aun así las tensiones raciales no tardarán en enfrentarlos.', '/7DykAW1ILpHzVR7oXmxFpY5qTSV.jpg', '/jhIdEe9oCZjxLt2Cq1KR8IbnJvj.jpg', 7.2, 'wRWvcpX4xag', array['1001']::text[], 353, null, 'segura', null),
(17281, 'movie', 'Gigi', 'Gigi', 'Gigi', 1958, 'Vincente Minnelli', 'París, 1900. Gaston es un joven millonario que se aburre, a pesar de ser el soltero más perseguido de toda la ciudad. Gigi es casi una niña, no tiene todavía edad para bailes y amoríos. Pero Gaston es amigo de su familia y la visita con frecuencia. La abuela de Gigi sueña con una boda entre Gastón y su nieta. Pero los planes de Gaston con respecto a Gigi no tienen nada que ver con el matrimonio.', '/3GSuecnDr4N5ZaqTrwElSzt6eC2.jpg', '/6aIpiwQB2qvVHSlhsXYZD3lmmSV.jpg', 6.3, '9UV5PzHMOtE', array['1001']::text[], 353, null, 'segura', null),
(426, 'movie', 'Vértigo', 'Vértigo', 'Vertigo', 1958, 'Alfred Hitchcock', 'Un ex detective con miedo a las alturas es contratado para seguir a la mujer de un amigo, que parece poseída por el pasado. La obsesión lo atrapa.', '/t4kvoLhrVHW5w5Ku7AQBniVExjN.jpg', '/rtVwkTqllcmyY4TVOycgVBHppWf.jpg', 8.1, 'UHhsEYDg8GI', array['1001','clasicos']::text[], 354, null, 'segura', null),
(5055, 'movie', 'Cenizas y diamantes', 'Cenizas y diamantes', 'Popiół i diament', 1958, 'Andrzej Wajda', 'En Polonia, concluida la Segunda Guerra Mundial, la situación política y social es caótica. El idealismo cede el paso a diversas formas de anarquía y extremismo. El protagonista, un joven que milita en un grupo ultranacionalista, recibe el encargo de asesinar a un importante comunista; pero, cuando el joven encuentra el amor, en pocas horas sus certezas comienzan a convertirse en dudas.', '/p3USyL8Tc8Lqs2k31Aib1TLBisF.jpg', '/1QlZ3Kge4bCH01V3VibxckeVIiu.jpg', 7.4, 'O6kcDS5QM6I', array['1001']::text[], 356, null, 'segura', null),
(11868, 'movie', 'Drácula (1958)', 'Drácula', 'Dracula', 1958, 'Terence Fisher', 'El conde Drácula decide abandonar su castillo de los Cárpatos y establecerse en Occidente. Pronto conoce a una joven de quien se enamora y a la que visita por las noches. Esta alarmante situación hace que la familia de la chica busque la ayuda del doctor Van Helsing.', '/uSsOogzEaIC0V4fY4aVzIzAO0X2.jpg', '/ijbBzlKSKwWNRpebLUGfmXhBrvg.jpg', 7.2, '1TaWGqgxmSU', array['1001']::text[], 357, null, 'segura', null),
(427, 'movie', 'Mi tío', 'Mi tío', 'Mon oncle', 1958, 'Jacques Tati', 'En un barrio moderno y anodino, donde todo está excesivamente organizado, viven monsieur Arpel, su esposa y su hijo Gérard, que se aburre soberanamente. La llegada de su tío, monsieur Hulot, un personaje soñador y lleno de fantasía, alterará ese mundo tan aséptico, sobre todo porque no tarda en convertirse en el mejor amigo de su sobrino.', '/jykJCrsJcv7G76o2Nd5L4kImv12.jpg', '/3yYNJeR6JynSE3Y1AfVIJQ6g3UX.jpg', 7.4, 'vqVpQ6S0BDA', array['1001']::text[], 357, null, 'segura', null),
(822, 'movie', 'Jalsaghar (El salón de música)', 'El salón de música', 'জলসাঘর', 1958, 'Satyajit Ray', 'Principios del siglo XX. En un palacio de Bengala, un terrateniente, al oír la música de la fiesta que celebra su arrogante vecino con motivo de la iniciación de su hijo, recuerda el gran recital que organizó con motivo de la de su propio hijo, así como los importantes acontecimientos que sucedieron después en su vida.', '/tbcOKg8wGA3zCSiCFdeL2xDbd7v.jpg', '/mh4WEd1A3iYtu6uPgsiGboCkRFb.jpg', 7.5, 'woMURYCtTtQ', array['1001']::text[], 358, null, 'segura', null),
(147, 'movie', 'Los 400 golpes', 'Los cuatrocientos golpes', 'Les Quatre Cents Coups', 1959, 'François Truffaut', 'Antoine, un chico parisino incomprendido en la escuela y en su casa, empieza a faltar a clases y a meterse en problemas.', '/1uqxcqhTNXZLyZoNKeqVkMVzuU4.jpg', '/cy7ymUaMEWRoig7LWXpfzaaw2vv.jpg', 8.0, '1L0smVZDBUg', array['1001','clasicos']::text[], 360, null, 'probable', '[{"tmdb_id": 147, "titulo": "The 400 Blows", "original": "Les Quatre Cents Coups", "anio": 1959, "votos": 2418, "poster_path": "/12PuU23kkDLvTd0nb8hMlE3oShB.jpg", "sim": 0.632}]'::jsonb),
(213, 'movie', 'Con la muerte en los talones', 'Con la muerte en los talones', 'North by Northwest', 1959, 'Alfred Hitchcock', 'Debido a un malentendido, a Roger O. Thornhill, un ejecutivo del mundo de la publicidad, unos espías lo confunden con un agente del gobierno llamado George Kaplan. Secuestrado por tres individuos y llevado a una mansión en la que es interrogado, consigue huir antes de que lo maten. Cuando al día siguiente regresa a la casa acompañado de la policía, no hay rastro de las personas que había descrito.', '/rzOQHh5Utbr3x0UvKIbIU5pVA0f.jpg', '/OR8oloCZ3klJtB7Y0i8pSqWw5a.jpg', 8.0, 'cPNiwc3ogIo', array['1001']::text[], 361, null, 'segura', null),
(239, 'movie', 'Una Eva y dos Adanes', 'Con faldas y a lo loco', 'Some Like It Hot', 1959, 'Billy Wilder', 'Dos músicos que presenciaron un ajuste de cuentas mafioso se disfrazan de mujeres y se suman a una orquesta femenina para escapar.', '/y2DPBWFMiwVJeBq0vBX9Um8AqOE.jpg', '/sv2VnbZmgy2rkrtkA2nz7rzH0VK.jpg', 8.1, '97TYs2YXbJw', array['1001','clasicos']::text[], 362, null, 'probable', '[{"tmdb_id": 239, "titulo": "Con faldas y a lo loco", "original": "Some Like It Hot", "anio": 1959, "votos": 4041, "poster_path": "/y2DPBWFMiwVJeBq0vBX9Um8AqOE.jpg", "sim": 0.316}]'::jsonb),
(93, 'movie', 'Anatomía de un asesinato', 'Anatomía de un asesinato', 'Anatomy of a Murder', 1959, 'Otto Preminger', 'Frederick Manion, un teniente del ejército, asesina fríamente al presunto violador de su mujer Laura. Tras su detención, se celebra el juicio. Su mujer contrata como abogado defensor a Paul Biegler, un honrado hombre de leyes. Durante el juicio se reflejarán todo tipo de emociones y pasiones, desde los celos a la rabia.', '/2lHWDt5kQcd4yZ5yBPUuiEFYEXD.jpg', '/xfEU7DOlQPwz8Y0TBhKmpETuNIc.jpg', 7.8, 'LwX8NiXv9Hw', array['1001']::text[], 364, null, 'segura', null),
(31417, 'movie', 'Ojos sin rostro', 'Los ojos sin rostro', 'Les Yeux sans visage', 1960, 'Georges Franju', 'En París, un brillante y desquiciado cirujano rapta chicas con el fin de utilizar su piel para reconstruir la belleza de su hija, destrozada por un trágico accidente del que él se siente culpable.', '/uV1rTX8m0tzbiO4WtcEJnwf02Oc.jpg', '/wlqwUNYHMuswEdGo3nSZ9i0LIlc.jpg', 7.6, 'CEjrg-L8lvs', array['1001']::text[], 365, null, 'segura', null),
(27644, 'movie', 'Cabalgar en solitario', 'Cabalgar en solitario', 'Ride Lonesome', 1959, 'Budd Boetticher', 'Un cazador de recompensas (Randolph Scott) detiene a un joven (James Best) acusado de asesinato. Durante el viaje a la ciudad donde debe ser juzgado, se les une una pareja de pistoleros (Pernell Roberts y James Coburn) y una bella mujer (Karen Steele). Por el camino serán perseguidos no sólo por los indios, sino también por el hermano del detenido (Van Cleef), que trata de liberarlo', '/6w4VMo8O3BGzgDrj17WQpchE4Y0.jpg', '/5UiC1NvHMH4YVCc88hSwrfZRSSl.jpg', 6.7, 'BsIaOss2olo', array['1001']::text[], 366, null, 'segura', null),
(40423, 'movie', 'Orfeo negro', 'Orfeo negro', 'Orfeu Negro', 1959, 'Marcel Camus', 'Ambientación del mito griego en el carnaval de Río de Janeiro. La bella Eurídice visita la ciudad brasileña en vísperas de su famoso carnaval, invitada por una prima que vive en los arrabales. Hasta allí llega en un tranvía cuyo conductor, un guitarrista llamado Orfeo, queda prendado de sus encantos. Sin embargo su relación se verá empañada por las sospechas de su celosa novia.', '/bfC0jOEYRFED8yttS6PFKD4JUJB.jpg', '/mXHZJu6wmmNIhbidSMp24PQ3WNw.jpg', 7.0, 'kKtUEpopu6A', array['1001']::text[], 366, null, 'segura', null),
(15484, 'movie', 'Shadows', 'Sombras', 'Shadows', 1960, 'John Cassavetes', 'Años 60 en la ciudad de Nueva York. Lelia y Tony son una feliz pareja. Un día conoce al hermano de su novia y descubre que ambos son de raza negra, aunque ella no lo parezca.  Película fundamental dentro de la evolución del cine, al ser considerada el origen del cine independiente estadounidense. "Sombras" fue el debut como director del hasta entonces actor John Cassavetes. La película fue filmada en la calle, con actores desconocidos, una cámara de 16 milímetros en mano y una escasa subvención pública de 40.000 dólares. "Sombras" está rodada con asfixiantes primeros planos de unos actores que resultan desgarradores por su naturalidad, ya que, además, hacen de ellos mismos. Cassavetes fue uno de los primeros directores en mostrar los ambientes intelectuales y bohemios de Nueva York a través de un tema, las relaciones interraciales, muy poco habitual en el cine de finales de los 50.', '/chslxRpPYIvdQN5SrI7K2G5pMCE.jpg', '/vBywNMAiQTNn3PxlOWslgYcwcpN.jpg', 6.9, '_4Fjpx5kxzs', array['1001']::text[], 367, null, 'segura', null),
(896, 'movie', 'Apur Sansar (El mundo de Apu)', 'Apur Sansar (El mundo de Apu)', 'অপুর সংসার', 1959, 'Satyajit Ray', 'Apu, que ha logrado trágicamente su ansiada independencia, siente reforzada su ansia de conocimiento. Sus deseos de escribir, soñar y amar parecen cumplirse cuando conoce a Aparna y se casa con ella. Tercera y última parte de la "trilogía de Apu".', '/32Jbhom0jcEwGyp1u6Zpf3j8gGe.jpg', '/d3RW7jRsBCHfC9QZaUF9FpzJrh8.jpg', 8.1, 'mgv68E_o6VM', array['1001']::text[], 368, null, 'segura', null),
(269, 'movie', 'Sin aliento', 'Al final de la escapada', 'À bout de souffle', 1960, 'Jean-Luc Godard', 'Un ladrón que mató a un policía se esconde en París con una estudiante norteamericana. La película que definió la Nouvelle Vague.', '/s5Ok06Q4M2cWAZGqtR5Au8o64YJ.jpg', '/4WGuyWf1f94CsEeVIIqDKGw5rmO.jpg', 7.5, 'UoICuMPOWrk', array['1001','clasicos']::text[], 370, null, 'probable', '[{"tmdb_id": 269, "titulo": "Al final de la escapada", "original": "À bout de souffle", "anio": 1960, "votos": 2112, "poster_path": "/s5Ok06Q4M2cWAZGqtR5Au8o64YJ.jpg", "sim": 0.294}]'::jsonb),
(665, 'movie', 'Ben-Hur', 'Ben-Hur', 'Ben-Hur', 1959, 'William Wyler', 'Antigua Roma, bajo el reinado de los emperadores Augusto y Tiberio (s. I d.C.). Judá Ben-Hur, hijo de una familia noble de Jerusalén, y Mesala, tribuno romano que dirige los ejércitos de ocupación, son dos antiguos amigos, pero un accidente involuntario los convierte en enemigos irreconciliables: Ben-Hur es acusado de atentar contra la vida del nuevo gobernador romano, y Mesala lo encarcela a él y a su familia. Mientras Ben-Hur es trasladado a galeras para cumplir su condena, un hombre llamado Jesús de Nazaret se apiada de él y le da de beber. En galeras conocerá al comandante de la nave y más tarde a un jeque árabe que participa con sus magníficos caballos en carreras de cuadrigas.', '/bG0yaRTC7N0bWhlaPXsyi3ZnbMo.jpg', '/nk5gq5rNLBJiHvNGMRT6I9VRQX7.jpg', 7.9, '0ic7XeN0LsA', array['1001']::text[], 371, null, 'segura', null),
(690, 'movie', 'Pickpocket', 'Pickpocket', 'Pickpocket', 1959, 'Robert Bresson', 'Michel es un carterista que no roba por necesidad como tampoco lo hace por vicio, no es cleptómano, roba para darse a sí mismo un valor, porque el robo es el medio de expresar sus sentimientos.', '/8fQelCr8NrGj0lQjTecm48tHaMc.jpg', '/5ApVROxPul7vu9NiB2DJWqlA3kE.jpg', 7.3, 'TyCTOHA4ejA', array['1001']::text[], 372, null, 'segura', null),
(5544, 'movie', 'Hiroshima mon amour', 'Hiroshima, mon amour', 'Hiroshima mon amour', 1959, 'Alain Resnais', 'Después de rodar una película en Hiroshima, una joven actriz francesa pasa su última noche en un hotel, en compañía de un japonés. Son dos desconocidos, pero lo que podría ser la fugaz aventura de una noche se convierte en un intenso idilio que hace que ella rememore un amor imposible vivido en Nevers (Francia) unos años antes. La relación amorosa se convierte entonces en un proceso introspectivo a través del cual la mujer reconstruye su pasado y revela sus sentimientos más íntimos a su compañero.', '/q2fmvMrBqNnniukiVRthGPrshUU.jpg', '/4fynFAYPPYCkyIdt0bsCwWn3Hxv.jpg', 7.7, 'VuP0IewJT50', array['1001']::text[], 374, null, 'segura', null),
(301, 'movie', 'Río Bravo', 'Río Bravo', 'Rio Bravo', 1959, 'Howard Hawks', 'El sheriff Chance encarcela por asesinato al hermano de un poderoso terrateniente cuyos hombres intentarán liberarlo. Para impedirlo, Chance cuenta con la colaboración de dos ayudantes: un alcohólico y un viejo tullido, a los que se une un joven y hábil pistolero llamado Colorado. Todos quedarán encerrados en la cárcel de la oficina del sheriff, roedados, incrementándose la tensión en el pueblo a la espera de que llegue la autoridad estatal para llevarse al detenido.', '/8lFSClr6GKKo7GAzLuyZL9bCXfD.jpg', '/38uM6QuI06znUCELfOSiVQy05CX.jpg', 7.8, 'VD55fwjvJlw', array['1001']::text[], 375, null, 'segura', null),
(29259, 'movie', 'La evasión', 'La evasión', 'Le Trou', 1960, 'Jacques Becker', 'Francia, 1947. Gaspard Claude ha sido acusado del intento de asesinato de su mujer, pero es inocente. Una vez en la cárcel, comparte celda con cuatro duros criminales que han decidido escapar de la prisión construyendo un laborioso túnel. A duras penas, convencen al joven para que se una al plan de fuga y participe en la construcción del túnel.', '/Al1F9o6fDkOBRngeG2FTJ0f9xTv.jpg', '/f72GEQF2lKsdmEULSI9bWCbQylH.jpg', 8.2, 'g2Sbo6JpDsY', array['1001']::text[], 376, null, 'segura', null),
(46918, 'movie', 'La hierba errante (Ukigusa)', 'La hierba errante', '浮草', 1959, 'Yasujirō Ozu', 'Remake de un film mudo dirigido por el propio Ozu en el año 1934. Narra la historia de un grupo de actores ambulantes que van a parar a una pequeña población de provincias. Allí el actor principal se reencuentra con una antigua amante y con un hijo ilegítimo.', '/tLuoMd7AvxCUBSsgLO91qT9xzEe.jpg', '/o7l1P351p4gh9dTlcQy1xB8NL8H.jpg', 7.5, 'bHpVeD9kJEI', array['1001']::text[], 377, null, 'segura', null),
(8422, 'movie', 'Rocco y sus hermanos', 'Rocco y sus hermanos', 'Rocco e i suoi fratelli', 1960, 'Luchino Visconti', 'Rosaria y sus cuatro hijos (Simone, Rocco, Ciro y Luca) abandonan su tierra natal, Lucania (la actual Basilicata), para emigrar a Milán en busca de trabajo y oportunidades que les permitan mejorar sus condiciones de vida. Allí encuentran a Vincenzo, el hermano mayor, que trabaja de albañil pero que está relacionado con el mundo del boxeo.', '/vwgfYkKflAsEvxC11zaPFPWWIfa.jpg', '/26LKQHOk5v7XjUFxm4Pv05nYgln.jpg', 8.0, '54IuJ8ivZl0', array['1001']::text[], 377, null, 'segura', null),
(439, 'movie', 'La dolce vita', 'La dolce vita', 'La dolce vita', 1960, 'Federico Fellini', 'Un periodista de chimentos recorre la noche romana entre fiestas, celebridades y vacío existencial.', '/zjtrLL2cFlBWnAL1z4qrokRU0ZT.jpg', '/eN2NdMeJLNzLYzWIEEoaGzZAsiD.jpg', 8.0, 'YJV6g9bz6tI', array['1001','clasicos']::text[], 378, null, 'segura', null),
(37230, 'movie', 'Sábado noche, domingo mañana', 'Sábado noche, domingo mañana', 'Saturday Night and Sunday Morning', 1960, 'Karel Reisz', 'Arthur Seaton es un joven inglés de carácter agrio y rebelde que trabaja en una fábrica. Trata de huir de su rutinaria y aburrida vida bebiendo y divirtiéndose cuanto puede los fines de semana. Ésa es la única meta de su vida: pasarlo lo mejor posible. Al mismo tiempo, mantiene una relación con la mujer de un compañero, y todo se complica cuando se queda embarazada. Mientras tanto, se enamora de una joven de estrictos principios morales que le exige un compromiso serio.', '/ifhjfo8lZoJ9dvDQiWcnc3GeFK4.jpg', '/3FCisYSoJXlW2UdJwJq2tEtUP5Y.jpg', 7.0, 'P9Ms04cAkws', array['1001']::text[], 380, null, 'segura', null),
(1818, 'movie', 'Tirad sobre el pianista', 'Tirad sobre el pianista', 'Tirez sur le pianiste', 1960, 'François Truffaut', 'Charlie Kohler, antiguamente un gran concertista de piano, trabaja ahora como pianista en un popular cabaret de una ciudad. Charlie se las ha arreglado para ocultar a todos y mantener en secreto su misterioso pasado, pero, inesperadamente, aparece uno de sus hermanos pidiéndole ayuda.', '/6Pf6qWwlIo8x5X4YjYbv1ddynAT.jpg', '/kgAZX0WXLuK6YYQ6lKN2UdF1Tho.jpg', 7.2, 'wCq3Q2jUg20', array['1001']::text[], 381, null, 'segura', null),
(5165, 'movie', 'La aventura', 'La aventura', 'L''avventura', 1960, 'Michelangelo Antonioni', 'Anna, una rica joven romana, su novio y Claudia, su mejor amiga, se embarcan en un crucero veraniego entre las escarpadas islas sicilianas...', '/oRmjYWt71G3APM56rfrfEoYO6Aj.jpg', '/kF5AeKG5XIZkAXY0kRgm57qEbJI.jpg', 7.5, 'N6ShLDfjnzw', array['1001']::text[], 382, null, 'segura', null),
(59239, 'movie', 'Estrella nublada (Meghe dhaka tara)', 'Estrella nublada', 'মেঘে ঢাকা তারা', 1960, 'Ritwik Kumar Ghatak', 'Nita es una bonita joven que vive con su familia, refugiados del este de Pakistán, en los suburbios de Calcuta. Shankar, su hermano mayor, aspira ser cantante. Nita aplaza su matrimonio con el científico Sanat para ayudar a su familia, que necesita dinero para pagar los estudios de los hermanos más jóvenes. Cuando su padre y su hermano menor sufren un accidente, ella se convierte en el único sostén de la familia, pero la enfermedad que padece no deja de empeorar.', '/8oAUqItOxkI1LmCWsnUfiAXxSZI.jpg', '/oAox7z3d94YqwRHTrQOyEZooK94.jpg', 7.2, 'ZAAv6fBh8q8', array['1001']::text[], 384, null, 'segura', null),
(35030, 'movie', 'La joven', 'La joven', 'La joven', 1960, 'Luis Buñuel', 'Miller es un guardabosques que vive en una desierta isla cerca de la costa americana. El otro habitante de la isla es Ewie, una huérfana inocente e ingenua de 13 años, hacía quien Miller se siente irresistiblemente atraido al descubrir que se está convertiendo en mujer. Cuando llega Traver, un inocente músico negro huyendo de un intento de linchamiento por una falsa acusación de violación, Miller quiere delatarle para deshacerse de él.', '/dr909VAfyAIS0a5LqLdyRpBesX8.jpg', '/bBK5j3FUk2qy5KtHXMJDLdKH7Ba.jpg', 7.0, null, array['1001']::text[], 384, null, 'segura', null),
(42506, 'movie', 'La doncella (Hayno)', 'La criada', '하녀', 1960, '김기영', 'Cuenta la historia de un triángulo amoroso entre un profesor de piano puritano y conservador, su esposa aparentemente ideal y la taciturna sirvienta de la casa. En 2010, el director surcoreano Lim Sang-soo realizó un remake con Jeon Do-yeon y Lee Jeong-jae en los papeles principales.', '/6H32qADeQLjAposMKSRaXZMoYHW.jpg', '/5NfLEeakUxT0JcU9Q830niu2w8e.jpg', 7.1, 'WsShIXZrJvA', array['1001']::text[], 385, null, 'probable', '[{"tmdb_id": 11656, "titulo": "El manantial de la doncella", "original": "Jungfrukällan", "anio": 1960, "votos": 697, "poster_path": "/32tSnaB94OEt85QtMWjO7vaugUH.jpg", "sim": 0.5}, {"tmdb_id": 42506, "titulo": "La criada", "original": "하녀", "anio": 1960, "votos": 203, "poster_path": "/6H32qADeQLjAposMKSRaXZMoYHW.jpg", "sim": 0.286}, {"tmdb_id": 185546, "titulo": "Las pícaras doncellas", "original": "Upstairs and Downstairs", "anio": 1959, "votos": 9, "poster_path": "/jyO9HLxyTviN2SnuwqxpmSIGsRp.jpg", "sim": 0.64}]'::jsonb),
(539, 'movie', 'Psicosis', 'Psicosis', 'Psycho', 1960, 'Alfred Hitchcock', 'Una secretaria que huye con dinero robado se refugia en un motel apartado, atendido por un joven tímido que vive con su madre.', '/xFbnc2QPG5H5gYWsGbZT4q8Akya.jpg', '/mufF1aYvwdpKerhq5R1YrVcbJLY.jpg', 8.4, 'mC2gOyWuSEY', array['1001','clasicos']::text[], 386, null, 'segura', null),
(27632, 'movie', 'La máscara del demonio', 'La máscara del demonio', 'La maschera del demonio', 1960, 'Mario Bava', 'Durante la Edad Media, la Inquisición rusa condena a muerte a una pareja de amantes que practican la brujería y los ejecuta poniéndoles una máscara con púas en su interior. Siglos después, sus ataúdes son encontrados y abiertos por dos viajeros. Al retirar las máscaras de los cadáveres, los brujos vuelven a la vida y siembran el pánico entre los habitantes del lugar.', '/fOY8Bvf2Xi3cAEJbBLL8u0MQWw6.jpg', '/wKzY5EGRweXc91eBs1jk9ZSXcp0.jpg', 7.4, 'N05Bm7kOZgg', array['1001']::text[], 388, null, 'segura', null),
(11167, 'movie', 'El fotógrafo del pánico', 'El fotógrafo del pánico', 'Peeping Tom', 1960, 'Michael Powell', 'Böhm interpreta a psicópata que fotografía a sus víctimas mientras mueren; es un hombre profundamente perturbado, cuyo desequilibrio hunde sus raíces en la infancia. Su padre, un científico obsesionado por estudiar las reacciones infantiles ante el miedo, destrozó su psique y lo convirtió en un adulto acomplejado y afectado por una demencia demoníaca. El personaje necesita registrar en imágenes el terror que sienten sus víctimas antes de morir. Por eso ejerce la profesión de fotógrafo, para encubrir sus intenciones y poder satisfacer sus morbosos impulsos sin levantar sospechas.', '/9IJuvJ5khuoZyB7k2fLw4cgs3L2.jpg', '/rLm66DbLwxHeRB34oJ1mhsu0urc.jpg', 7.4, '0pOdgj4zKKA', array['1001']::text[], 389, null, 'segura', null),
(284, 'movie', 'El apartamento', 'El apartamento', 'The Apartment', 1960, 'Billy Wilder', 'C.C. Baxter es un modesto pero ambicioso empleado de una compañía de seguros de Manhattan. Está soltero y vive solo en un discreto apartamento que presta ocasionalmente a sus superiores para sus citas amorosas. Tiene la esperanza de que estos favores le sirvan para mejorar su posición en la empresa. Pero la situación cambia cuando se enamora de una ascensorista que resulta ser la amante de uno de los jefes que usan su apartamento.', '/2kJMgHi8vNY8a0UJiBU3HEyiqOa.jpg', '/vRTKNKNWLZ22fAgPa5kY8wT2b1F.jpg', 8.2, 'ekDkUUPSWuY', array['1001']::text[], 390, null, 'segura', null),
(967, 'movie', 'Espartaco', 'Espartaco', 'Spartacus', 1960, 'Stanley Kubrick', 'Hacia el año 75 antes de Cristo, un esclavo llamado Espartaco es vendido a una escuela de gladiadores donde le adiestran para combatir en la arena de los circos romanos. Pronto, Espartaco lidera una rebelión por el maltrato sufrido.', '/azXoEA108BvWjeKxIW9tfYlxY2I.jpg', '/9caD0fGCrp96JTFFeGyI0CGNj7.jpg', 7.5, 'R8aWcZa18pc', array['1001']::text[], 392, null, 'segura', null),
(28569, 'movie', 'Esplendor en la hierba', 'Esplendor en la hierba', 'Splendor in the Grass', 1961, 'Elia Kazan', 'En una localidad rural de Kansas, dos jóvenes que pertenecen a ambientes sociales muy distintos se aman y deciden no separarse jamás; pero la desaprobación de sus familias y ciertos intereses ajenos a sus sentimientos acabarán decidiendo su suerte.', '/8z07rGiJz7DlihOSbXD3O6DFyS6.jpg', '/3I5Dsam910xWbTEk69o04i8lVkC.jpg', 7.5, 'dWDkdsZQq_c', array['1001']::text[], 392, null, 'segura', null),
(4024, 'movie', 'El año pasado en Marienbad', 'El año pasado en Marienbad', 'L''Année dernière à Marienbad', 1961, 'Alain Resnais', 'En un barroco hotel, un extraño, X, intenta persuadir a una mujer casada, A, de que abandone a su marido, M, y se fugue con él. Se basa en una promesa que ella le hizo cuando se conocieron el año anterior, en Marienbad, pero la mujer parece no recordar aquel encuentro.', '/wW5xOJxal1XrFgDrswWCPeA9xF1.jpg', '/h1ov8VcVCiZsnWRu4EjZ74R33GP.jpg', 7.4, 'p3Tvl1Fuxt8', array['1001']::text[], 393, null, 'segura', null),
(662, 'movie', 'La jetée', 'La jetée', 'La Jetée', 1962, 'Chris Marker', 'Un hombre se enfrenta a su pasado durante un experimento que intenta encontrar una solución a los problemas de un mundo postapocalíptico causados por una guerra mundial.', '/h8DykeLWkZtG1wKcIqBj82ffwoU.jpg', '/3Z2OhNVU0FhxGZJIq6Gn32UNoKu.jpg', 7.9, 'jO4W6TPkSD8', array['1001']::text[], 394, null, 'segura', null),
(18647, 'movie', 'El rostro impenetrable', 'El rostro impenetrable', 'One-Eyed Jacks', 1961, 'Marlon Brando', 'Tras el atraco a un banco fronterizo, Johnny Río es traicionado por Dad, su mejor amigo y compañero de correrías. Apresado por la policía mexicana, pasa cinco amargos años en la prision de Sonora, durante los cuales, vive obsesionado con la idea de vengarse del traidor. Tras ser puesto en libertad, visita a Dad, quese ha convertido en un hombre respetable y es el sheriff de Monterrey. Cuando Dad le presenta a su hijastra Louisa, Jonnhy queda prendado de su belleza y la seduce.', '/1NpeRKgoZ7MddmtUDua2Dgk9fSB.jpg', '/c34lzH24bX4SJJIZCRbIbYShM1K.jpg', 6.7, 'R41AHe59UiU', array['1001']::text[], 395, null, 'segura', null),
(164, 'movie', 'Desayuno con diamantes', 'Desayuno con diamantes', 'Breakfast at Tiffany''s', 1961, 'Blake Edwards', 'Holly Golightly es una bella joven de la alta sociedad neoyorquina que bajo su vida alegre esconde una gran tristeza. Holly tiene un comportamiento algo alocado, y alguna manía, como por ejemplo desayunar contemplando el escaparate de la lujosa joyería Tiffanys. Un día se muda a su mismo edificio Paul Varjak, un escritor en ciernes que mientras espera alcanzar un éxito que nunca llega vive de la relación con una mujer madura que le mantiene. Holly y Paul enseguida entablarán una bonita amistad.', '/aHFIHN7yenVYk1wkDWJ7hs1czh4.jpg', '/jXZ2tyJl44yKvh22I6ooQwU5rFM.jpg', 7.6, 'KlZ4fYqjGJI', array['1001']::text[], 396, null, 'segura', null),
(40641, 'movie', 'Lola', 'Lola', 'Lola', 1961, 'Jacques Demy', 'En Nantes, Lola (Anouk Aimée), una bailarina de cabaret, espera el regreso de su novio Michel (Jacques Harden), que es el padre de su hijo y hace siete años que emigró a América con la promesa de volver cuando se hiciese rico. Durante su ausencia, Lola es cortejada por Roland (Marc Michel), un amigo de la infancia, y por el marinero americano Frankie (Alan Scott).', '/cdHH3cn00f9pAxR9pFS4B0zsFLA.jpg', '/bX9WDVEdNftHE0BO3jsufoj7jKr.jpg', 7.1, 'd4oUnqkJipI', array['1001']::text[], 396, null, 'segura', null),
(41050, 'movie', 'La noche', 'La noche', 'La notte', 1961, 'Michelangelo Antonioni', 'Retrato de la vida cotidiana de un matrimonio burgués que atraviesa una crisis de pareja. En Milán, tras visitar a un amigo enfermo terminal en un hospital, el escritor Giovanni Pontano (Marcello Mastroianni) acude a una fiesta por la publicación de su último libro. Mientras, su mujer Lidia (Jeane Moreau) visita el lugar donde vivió muchos años atrás. Luego, durante la noche, ambos acuden a una fiesta en la mansión del Sr. Gherardini, donde ambos comienzan a flirtear; Giovanni con la hija del anfitrión, y Lidia con un playboy.', '/tisVoVpKpe9EynTgFLamBStGd9Z.jpg', '/5wATYRIHIBhE9kelbGxYm0i7cNs.jpg', 7.9, '75SO1lc_TZU', array['1001']::text[], 397, null, 'segura', null),
(1628, 'movie', 'Jules et Jim', 'Jules y Jim', 'Jules et Jim', 1962, 'François Truffaut', 'Desde que se conocieron en 1912, Jules (Oskar Werner) y Jim (Henri Serre) se convirtieron en dos inseparables amigos que un día se enamoran de la misma mujer, Catherine (Jeanne Moreau). Uno de ellos finalmente se casa con ella. Obra capital del cine francés de los sesenta, un hermoso canto al amor y la pasión.', '/s9Po80JEx6LsvoRK98n9XgeQwBH.jpg', '/o3GSSYr7AzrdcukNpQrqFEJNOjk.jpg', 7.5, 'X9OzdWczCfQ', array['1001']::text[], 398, null, 'segura', null),
(28333, 'movie', 'El terror de las chicas', 'El terror de las chicas', 'The Ladies Man', 1961, 'Jerry Lewis', 'Tras ser plantado por su chica, un deprimido Herbert H. Herbert (Jerry Lewis) reniega de las relaciones románticas, y está decidido a vivir toda su vida como un soltero redomado. Entonces, encuentra trabajo en una residencia para señoritas en Hollywood, ¡y las residentes se vuelven locas con el nuevo ayudante! Es entonces cuando el desventurado Herbert pasa de ser un simple manitas a convertirse en...¡"El terror de las chicas"!', '/qBY5c3fDEMxtZyhMwu5o2srGxIt.jpg', '/vH5yM2yod8DZqCk713zyWQWcKjc.jpg', 6.3, 'rjVuoaHbfzQ', array['1001']::text[], 399, null, 'segura', null),
(4497, 'movie', 'Viridiana', 'Viridiana', 'Viridiana', 1962, 'Luis Buñuel', 'Don Jaime, un viejo hidalgo español, vive retirado y solitario en su hacienda desde la muerte de su esposa, ocurrida el mismo día de la boda. Un día recibe la visita de su sobrina Viridiana, novicia en un convento, que tiene un gran parecido con su mujer.', '/dcXpg8ELDUZMb8MikPReiwH3lYY.jpg', '/2QGuTuyxwCCER9iwSeONW8BAxce.jpg', 7.7, 'ScqpbxCjZIw', array['1001']::text[], 399, null, 'segura', null),
(11602, 'movie', 'Como en un espejo', 'Como en un espejo', 'Såsom i en spegel', 1961, 'Ingmar Bergman', 'Durante un hermoso verano, un escritor, siempre demasiado ocupado y de temperamento frío y distante, va a pasar unos días con sus hijos, un adolescente y una joven con problemas mentales, que está casada con un médico que la cuida con gran ternura. Su estancia en la isla donde viven sus hijos desencadena una crisis que los afecta a todos, pero especialmente a él, porque toma conciencia de su incapacidad para darle a su familia lo que espera de él.', '/sUiZBbLMHmB70eYK9VRHNjZWsHp.jpg', '/xUvE2qim7mBzdUomoYDP9YC8gsZ.jpg', 7.8, '6AmG2Dq5OGM', array['1001']::text[], 400, null, 'segura', null),
(84972, 'movie', 'Chronique d''un été', 'Crónica de un verano', 'Chronique d''un été (Paris 1960)', 1961, 'Jean Rouch, Edgar Morin', 'París, verano de 1960. El antropólogo y cineasta Jean Rouch y el sociólogo y crítico de cine Edgar Morin deambulan por las calles abarrotadas preguntando a los transeúntes cómo afrontan las desgracias de la vida.', '/hmv7xszKlYqFzjmIlXhOHNrQIBT.jpg', '/bolMHmAoPcY9CQ9IMpJPLSr4azQ.jpg', 7.2, 'S0dOLHemSgs', array['1001']::text[], 401, null, 'segura', null),
(990, 'movie', 'El buscavidas', 'El buscavidas', 'The Hustler', 1961, 'Robert Rossen', 'Eddie Felson es un joven arrogante y amoral que frecuenta con éxito las salas de billar. Decidido a ser proclamado el mejor, busca al Gordo de Minnesota, un legendario campeón de billar. Cuando, por fin, consigue enfrentarse con él, su falta de seguridad le hace fracasar. El amor de una solitaria mujer podría ayudarlo a abandonar esa clase de vida, pero Eddie no descansará hasta vencer al campeón sin importarle el precio que tenga que pagar por ello.', '/6jicxcrfFZpXIBgQidj3uouwsiP.jpg', '/tGOfacXHjOSjsFCOcGN7IwdeipF.jpg', 7.7, 'n7aFFqz2bXU', array['1001']::text[], 402, null, 'segura', null),
(1725, 'movie', 'West Side Story', 'West Side Story (Amor sin barreras)', 'West Side Story', 1961, 'Jerome Robbins, Robert Wise', 'En el barrio West Side de Nueva York, un barrio marginal, se disputan la hegemonía dos bandas callejeras: los Sharks portorriqueños y los Jets de europeos. El jefe de los primeros es Bernardo, que vive con su hermana María, quien acaba de llegar a Nueva York. Una noche, en un baile, coinciden los dos grupos y se desencadena una violenta pelea.', '/AejrmDDmafBvaOLXWNct9fbJnZt.jpg', '/swYJtp5GISfsCMZ46y2WNBBwJsq.jpg', 7.2, 'HpKbrpPiExA', array['1001']::text[], 402, null, 'segura', null),
(32688, 'movie', 'Este perro mundo', 'Este perro mundo', 'Mondo Cane', 1962, 'Paolo Cavara, Gualtiero Jacopetti, Franco Prosperi', 'Primera entrega de la trilogía de Jacopetti que muestra, utilizando el género documental, extrañas culturas humanas, donde el folklore y las tradiciones se mezclan con la excentricidad, el sadismo y salvajismo expuestos con toda crudeza y autenticidad. Narrada por Stefano Sibaldi.', '/sp2SRySQ4ikmeVyW5Vi5gMKWoqd.jpg', '/mSnbknxnpgnWu50yspMdVc23xLM.jpg', 6.2, '3XBg6BgOSgs', array['1001']::text[], 403, null, 'segura', null),
(499, 'movie', 'Cleo de 5 a 7', 'Cleo de 5 a 7', 'Cléo de 5 à 7', 1962, 'Agnès Varda', 'Cleo, una joven cantante, espera impaciente los resultados de un examen médico. Cuando una adivina que lee las cartas le revela que tiene cáncer y que puede morir, su inquietud aumenta. Tratando de ocupar su tiempo a la espera de los resultados, Cleo conoce a un joven soldado, a punto de partir para hacer el servicio militar en Argelia, al que confía su temor a la muerte.', '/k5dXkYYgjRcWFfgm8dSdYr9abAc.jpg', '/oyatchDPpS4I9jpIIezFJGrmXcR.jpg', 7.7, 'sRR0_VJFqwg', array['1001']::text[], 404, null, 'segura', null),
(420240, 'movie', 'Dog Star Man', 'Dog Star Man', 'Dog Star Man', 1965, 'Stan Brakhage', 'Described as a "cosmological epic" and "creation myth", Dog Star Man illustrates the odyssey of a bearded woodsman climbing through a snow-covered mountain with his dog to chop down a tree. While doing so, he witnesses various mystical visions with various recurring imagery such as a woman, child, nature, and the cosmos while making his ascent.', '/oZbENblOS67gRW3s0LJBj00m1CL.jpg', '/pfqrbIBCjqqI8DX4xp9BAfQdj3s.jpg', 6.4, null, array['1001']::text[], 404, null, 'segura', null),
(21135, 'movie', 'El eclipse', 'El eclipse', 'L''eclisse', 1962, 'Michelangelo Antonioni', 'Vittoria (Monica Vitti), tras una acalorada discusión, decide romper con su novio Riccardo (Francisco Rabal). Mientras disfruta de su libertad en compañía de su madre, conoce a Piero (Alain Delon), un joven y atractivo corredor de bolsa, un seductor arrogante con el que mantiene un apasionado romance.', '/7WLmSe1IlM1Zuk00JODAjjJh92m.jpg', '/n6hmnEqU9W4jcVxCU00S4XJ5ecw.jpg', 7.6, 'SHUapLYEi4s', array['1001']::text[], 405, null, 'segura', null),
(50759, 'movie', 'El sabor del sake (Sanma no aji)', 'El sabor del sake', '秋刀魚の味', 1962, 'Yasujirō Ozu', 'Shubei Hirayama es un viudo que vive con su hija de veinticuatro años. Sintiéndose viejo y acabado, el hombre se da cuenta de que ella debería vivir su vida y no tener la obligación de cuidarle permanentemente, así que decide casarla. Aunque su hija se resiste a abandonar a su progenitor, finalmente acabará haciéndolo. Shubei buscará en el licor del sake el refugio de la soledad, el consuelo de la angustia.', '/c41bRzbloKjPdQfwEyMB8et0M98.jpg', '/hl3ZJljnYIfjhDRgahVXsUKyVnH.jpg', 7.9, null, array['1001']::text[], 405, null, 'segura', null),
(947, 'movie', 'Lawrence de Arabia', 'Lawrence de Arabia', 'Lawrence of Arabia', 1962, 'David Lean', 'Un oficial británico excéntrico se une a las tribus árabes en su rebelión contra el Imperio Otomano durante la Primera Guerra Mundial.', '/UmgjvObk7ugIDLLcwJsqNF1TIC.jpg', '/eULrEMwgXnWmzdowUfegaw2YYgD.jpg', 8.0, 'KR1yTI8zFJk', array['1001','clasicos']::text[], 406, null, 'segura', null),
(595, 'movie', 'Matar un ruiseñor', 'Matar a un ruiseñor', 'To Kill a Mockingbird', 1962, 'Robert Mulligan', 'En la época de la Gran Depresión, en una población sureña, Atticus Finch es un abogado que defiende a un hombre negro acusado de haber violado a una mujer blanca. Aunque la inocencia del hombre resulta evidente, el veredicto del jurado es tan previsible que ningún abogado aceptaría el caso, excepto Atticus Finch, el ciudadano más respetable de la ciudad. Su compasiva y valiente defensa de un inocente le granjea enemistades, pero le otorga el respeto y la admiración de sus dos hijos, huérfanos de madre.  Adaptación cinematográfica de la novela homónima de Harper Lee.', '/elLuuNim93XReUc6vvpC9B6IBGJ.jpg', '/wYRpVySPCC7wA28p54yAaoMT478.jpg', 8.0, '4-CrrtYjrbM', array['1001']::text[], 408, null, 'segura', null),
(802, 'movie', 'Lolita', 'Lolita', 'Lolita', 1962, 'Stanley Kubrick', 'Humbert Humbert, un profesor cuarentón, acaba de instalarse en Ramsdale, New Hampshire. Allí se enamora perdidamente de una niña de once años, tanto que concibe un plan maestro: se casará con su madre, Charlotte Haze, para poder estar siempre cerca del objeto de sus afectos: la alegre adolescente, la irresistible nínfula de nombre encantador, lírico y melodioso: Lolita.', '/3VVvm1EhGWAxRX0SjizQvNWobcH.jpg', '/40JNQ4FOekM1LDgUC5mDcM8bZyl.jpg', 7.3, 'KOgioT6OTGc', array['1001']::text[], 409, null, 'segura', null),
(982, 'movie', 'Mensajero del miedo', 'El mensajero del miedo', 'The Manchurian Candidate', 1962, 'John Frankenheimer', 'Un grupo de soldados, bajo el mando del sargento Raymond Shaw y el comandante Benett Marco, sufre una emboscada durante la guerra de Corea y es capturado por el ejército enemigo. Meses después, Shaw recibe una medalla al honor por el gobierno de los Estados Unidos. Por entonces, Marco comienza a sufrir terribles pesadillas relacionadas con el lavado de cerebro al que fueron sometidos durante el cautiverio en Corea.', '/kfH2NHYOUovD2Gz6cdbhunsahAW.jpg', '/cNOWw8hP9fIfKE4Lo1tAYt4zQ0L.jpg', 7.5, 'tgCyowLRfvA', array['1001']::text[], 409, null, 'segura', null),
(11697, 'movie', 'El hombre que mató a Liberty Valance', 'El hombre que mató a Liberty Valance', 'The Man Who Shot Liberty Valance', 1962, 'John Ford', 'Un anciano senador del Congreso de los Estados Unidos, Ransom Stoddard, relata a un periodista la verdadera historia de por qué ha viajado junto a su mujer Hallie para acudir al funeral de un viejo amigo, Tom Doniphon. Todo comenzó muchos años atrás, cuando Ransom era un joven abogado del este que llegó en diligencia a Shinbone, un pequeño pueblo del Oeste, para ejercer la abogacía e imponer la ley. Poco antes de llegar a su destino, es atracado y golpeado brutalmente por el temido pistolero Liberty Valance.', '/cVoQULxaEW2jO55c02RCUXEic8l.jpg', '/f6gTJLQ950dPHfFRnxQdaA6OlXJ.jpg', 7.8, 'uQBkL3GzpSE', array['1001']::text[], 410, null, 'segura', null),
(59990, 'movie', 'O Pagador de promesas', 'El pagador de promesas', 'O Pagador de Promessas', 1962, 'Anselmo Duarte', 'Zé es un pobre hombre que vive en una región rural de Brasil y que únicamente tiene a su burro. Cuando éste enferma, Zé reza por su recuperación y promete a Dios que irá a la capital del estado si se recupera.', '/3lOrYyD6N4cNY9WcXGYiOqWtVLt.jpg', '/k13mFZr51lcOxvLrHHCk9Llevcf.jpg', 8.1, 'VO1F_WDMNCo', array['1001']::text[], 410, null, 'segura', null),
(10242, 'movie', '¿Qué fue de Baby Jane?', '¿Qué fue de Baby Jane?', 'What Ever Happened to Baby Jane?', 1962, 'Robert Aldrich', 'Baby Jane fue una niña estrella en su juventud, años despues su carrera fracasa mientras su hermana Blanche triunfa como actriz. En el presente ambas hermanas, ya de avanzada edad, viven juntas. Blanche, que está paralítica por un extraño accidente que sucedió en el pasado, vive prácticamente secuestrada y maltratada por Jane, que sufre grandes transtornos psicológicos.', '/hNvM9dKmWlbLTXR92D3ASpQsm8K.jpg', '/gkXL5ka6ciU4A4KYSvLIAXtvh7k.jpg', 7.9, '3qFYjkFCxiE', array['1001']::text[], 411, null, 'segura', null),
(85428, 'movie', 'Heaven and Earth Magic', 'Heaven and Earth Magic', 'Heaven and Earth Magic', 1962, 'Harry Smith', 'The first part depicts the heroine''s toothache consequent to the loss of a very valuable watermelon, her dentistry and transportation to heaven. Next follows an elaborate exposition of the heavenly land, in terms of Israel and Montreal. The second part depicts the return to Earth from being eaten by Max Müller on the day Edward VII dedicated the Great Sewer of London.', '/iRmNclmohml4V4pSPhVcw2ki0y1.jpg', '/rzZjkVbHjx3w8YTATOb4hKyYBMM.jpg', 5.6, '1Ne6dXa2Y3k', array['1001']::text[], 412, null, 'segura', null),
(1626, 'movie', 'Vivir su vida', 'Vivir su vida', 'Vivre sa vie: film en douze tableaux', 1962, 'Jean-Luc Godard', 'Nana (Anna Karina) es una joven veinteañera de provincias que abandona a su marido y a su hijo para intentar iniciar una carrera como actriz en París. Sin dinero, para financiar su nueva vida comienza a trabajar en una tienda de discos en la que no gana mucho dinero. Al no poder pagar el alquiler, su casera la echa de casa, motivo por el que Nana decide ejercer la prostitución.', '/bAvPie07SWrBWHpbP9uTL71EYyK.jpg', '/68NGFE8zD2gaQVH6MqJeKzojFJM.jpg', 7.7, 'dfZQpLSuxKE', array['1001']::text[], 412, null, 'segura', null),
(571, 'movie', 'Los pájaros', 'Los pájaros', 'The Birds', 1963, 'Alfred Hitchcock', 'Melanie, una joven rica y snob de la alta sociedad de San Francisco, conoce casualmente en una pajarería al abogado Mitch Brenner, que ha ido a comprar un regalo de cumpleaños para Kathy, su hermana pequeña. Mitch, que conoce por la prensa la alocada vida de Melanie, la trata despectivamente y se va de la tienda dejándola bastante irritada. Ella, que no está acostumbrada a que la traten así, encarga unos periquitos y los lleva a casa del abogado, pero Mitch se ha ido a pasar el fin de semana a casa de su madre. Entonces, Melanie decide ir a Bodega Bay y presentarse en casa de los Brenner con el pretexto de regalar los periquitos a Kathy. En cuanto ella llega, los pájaros, enloquecidos, empiezan a atacar salvajemente a los habitantes del lugar. La situación se agrava a medida que avanzan las horas.', '/aqMiK53QEC5UyGePN5KmgL7DLNg.jpg', '/98qofsLB8HwPsmlq0HczQTt8BcS.jpg', 7.5, 'lCxR7dlavwg', array['1001']::text[], 413, null, 'segura', null),
(18331, 'movie', 'El profesor chiflado', 'El profesor chiflado', 'The Nutty Professor', 1963, 'Jerry Lewis', 'Un profesor universitario de química no muy agraciado y con poco éxito en sus contactos sociales, Julius Kelp, inventa una fórmula que le convierte en otra persona muy diferente, arrogante y bien parecido, Buddy Love.', '/emO5eQK7szRVPlUZwf7dda9U0jc.jpg', '/kTgPUrv6jICp5CDDq5vS40zvVKX.jpg', 6.5, '1DUkGjWVOlc', array['1001']::text[], 414, null, 'segura', null),
(85479, 'movie', 'Blonde Cobra', 'Blonde Cobra', 'Blonde Cobra', 1963, 'Ken Jacobs', 'Un hombre toquetea objetos, se mira en el espejo, se viste con distintas ropas, hace muecas a la cámara. Mientras, su voz narra momentos de desesperación, cita sentencias filosóficas y canciones infantiles y cuenta las historias de un niño solitario y una mujer que desea abandonarse a la perversión.', '/dJh3umPoz6awku3qFcoZ7RViGCH.jpg', '/sXl8RlRIlGDrvWB8wVnF9gezyhi.jpg', 3.0, null, array['1001']::text[], 415, null, 'segura', null),
(85521, 'movie', 'The Cool World', 'The Cool World', 'The Cool World', 1964, 'Shirley Clarke', 'El adolescente Duke vive en un ghetto de Harlem donde la única manera de mostrar su hombría es comprando una pistola y ser el líder de una pandilla que regrese la tradición del bopping (peleas entre pandillas) a las calles de su barrio. The cool world es la primera película que retrata la vida de los barrios negros, alejandose de los estereotipos; un largometraje producido por el maestro de la tradición documental Frederick Wiseman.', '/w6kQstQo9mbX5tiufrEk1u8uq15.jpg', '/a10izvD6rEdVb0A4Zh45W8d4Qqy.jpg', 5.5, null, array['1001']::text[], 415, null, 'segura', null),
(422, 'movie', 'Fellini, ocho y medio', 'Fellini 8½', '8½', 1963, 'Federico Fellini', 'Después de obtener un éxito rotundo, un director de cine atraviesa una crisis de creatividad e intenta inútilmente hacer una nueva película. En esta situación, empieza a pasar revista a los hechos más importantes de su vida y a recordar a todas las mujeres a las que ha amado.', '/nCbEu0JLfCIXLnFAxuTs5i5AYN9.jpg', '/y2FNZLHynsevBnVTocGW6c3pQpr.jpg', 8.1, 'tL2AR4XivvQ', array['1001']::text[], 416, null, 'probable', '[{"tmdb_id": 422, "titulo": "Fellini 8½", "original": "8½", "anio": 1963, "votos": 2619, "poster_path": "/nCbEu0JLfCIXLnFAxuTs5i5AYN9.jpg", "sim": 0.516}]'::jsonb),
(266, 'movie', 'El desprecio', 'El desprecio', 'Le Mépris', 1963, 'Jean-Luc Godard', 'Paul Javal (Michel Piccoli), un autor dramático francés, acepta reescribir algunas escenas para "La Odisea", una película que se va a rodar en Capri bajo la dirección del renombrado director alemán Fritz Lang (Fritz Lang). En un primer encuentro con el productor, el arrogante norteamericano Prokosch (Jack Palance), el escritor deja que su mujer, la bella Camille (Brigitte Bardot), se vaya en el coche con el productor a la finca de éste, lo cual da lugar a un grave mal entendido entre el escritor y su esposa, que cree que la ha ofrecido como moneda de cambio para obtener un mejor pago. Como consecuencia de esta situación, el escritor se verá inmerso en una dolorosa crisis matrimonial.', '/1sEmVmmQhPfFFdoZWZaMDehCZZ5.jpg', '/afxEiYxANGG88xXVYpNtAHFzTIV.jpg', 7.0, 'y-zc8r3F_QY', array['1001']::text[], 418, null, 'segura', null),
(25939, 'movie', 'La pasajera', 'La pasajera', 'Pasażerka', 1963, 'Andrzej Munk, Witold Lesiewicz', 'Terminada la Segunda Guerra Mundial, Liza huyó de Europa. Hasta entonces había sido vigilante en el campo de concentración de Auschwitz. Cuando años después regresa, durante la travesía en barco reconoce un rostro que no ha podido olvidar...', '/7x6WN7uQUqj2dxlgid6UUll2B1n.jpg', '/bRIbTIJHwyqQg1ijGU3qbl7YLMC.jpg', 7.3, null, array['1001']::text[], 418, null, 'segura', null),
(24748, 'movie', 'Hud', 'Hud, el más salvaje entre mil', 'Hud', 1963, 'Martin Ritt', 'Homer Bannon, un viejo ganadero del Oeste, no quiere saber nada de la nueva industria petrolera que poco a poco ha ido cambiando el rostro de la región y ha supuesto una enorme riqueza para todos, y mantiene serias discusiones con su hijo Hud. El joven es un irresponsable que necesita mucho dinero para poder mantener su lujoso tren de vida, dinero que no produce la cría de ganado. Entre padre e hijo se interpone el nieto del primero, sobrino del segundo, que siente un gran cariño por su abuelo y una gran admiración por su tío. En medio de este choque de intereses, algo comienza a suceder al ganado', '/9aUEgxq8ynBPv589IRprw0dZMZO.jpg', '/dlmROevxOVYtZXRUzt6DGJzl9BL.jpg', 7.3, '9uSurLxEiRc', array['1001']::text[], 419, null, 'segura', null),
(29455, 'movie', 'Los comulgantes', 'Los comulgantes', 'Nattvardsgästerna', 1963, 'Ingmar Bergman', 'Thomas es un pastor protestante que celebra los oficios religiosos con la iglesia casi vacía. Es un hombre solitario que sufre una profunda crisis espiritual y cuya vida carece de sentido. Incluso el amor que le profesa la maestra Marta se ha vuelto para él una carga insoportable. Su situación se agrava al verse incapaz de ofrecer ayuda alguna a una pareja de campesinos que acuden a él para pedirle consejo. Cuando, poco después, el campesino se suicida, Thomas se encuentra al borde del abismo y ya nada podrá llenar su vacío interior.', '/sZjZIEp3ilHMR6wH63m6QxwbfzO.jpg', '/tis6nrWakUsuG6Jwdm4yESfTU0o.jpg', 7.9, 'S_ihGR6Wung', array['1001']::text[], 419, null, 'segura', null),
(47122, 'movie', 'Flaming Creatures', 'Flaming Creatures', 'Flaming Creatures', 1963, 'Jack Smith', 'Polémico filme rodado en blanco y negro, tildado de obsceno en su época, cuyo tema principal es la ambigüedad sexual y que reúne a un grupo de andróginos, travestis y drag queens en una orgía. "Flaming Creatures", referencia indiscutible del cine experimental de los años 60, es la única película que nos ha quedado de Jack Smith, autor de varios cortos y considerado precursor del cine de Andy Warhol.', '/6WGiHbL7BGoieVwBzcn8ivaxOFM.jpg', '/bscqiQRZJqRpnX5aD79H0MNLro6.jpg', 4.8, '1i3IJmZEKlQ', array['1001']::text[], 420, null, 'segura', null),
(25504, 'movie', 'Corredor sin retorno', 'Corredor sin retorno', 'Shock Corridor', 1963, 'Samuel Fuller', 'Con la ayuda de su novia Cathy y del doctor Fong, un psiquiatra, el ambicioso periodista Johnny Barrett se hace pasar por loco con el propósito de ser ingresado en una institución mental donde se ha cometido un cruento asesinato.', '/nbkwUJUl8cDtm1wBDISmkY94L0i.jpg', '/5JfXNdjitnpFoWxfARzD9IDYnyA.jpg', 7.0, '5vn4WcUkHoA', array['1001']::text[], 421, null, 'segura', null),
(5925, 'movie', 'La gran evasión', 'La gran evasión', 'The Great Escape', 1963, 'John Sturges', 'En 1943 los nazis, exasperados por el número de fugas de sus prisiones por un número relativamente pequeño de prisioneros aliados, deciden trasladarlos a todos a una prisión de alta seguridad "a prueba de fugas" durante el resto de la guerra. Los presos no tardan en trazar el plan de uno de los intentos de fuga más ambiciosos de la Segunda Guerra Mundial. Basado en una historia real.', '/zyXTt4nDNBbS0oULtDuiFpzhA4x.jpg', '/zlg0d4pnq1xDOU4cQxqGG8bX5l0.jpg', 7.9, '8No6XGbvr0w', array['1001']::text[], 421, null, 'segura', null),
(1040, 'movie', 'El gatopardo', 'El gatopardo', 'Il gattopardo', 1963, 'Luchino Visconti', 'Película basada en la novela homónima de Giuseppe Tomasi di Lampedusa (1958). Es la época de la unificación de Italia en torno al Piamonte, cuyo artífice fue Cavour. La acción se desarrolla en Palermo y los protagonistas son Don Fabrizio, Príncipe de Salina, y su familia, cuya vida se ve alterada tras la invasión de Sicilia por las tropas de Garibaldi (1860). Para alejarse de los disturbios, la familia se refugia en la casa de campo que posee en Donnafugata. Hasta el lugar se desplazan, además de la mujer del Príncipe y sus tres hijos, el joven Tancredi, el sobrino predilecto de Don Fabrizio, que parece simpatizar con el movimiento liberal de unificación', '/wMahDs1uQ8nC5EeqJ9hXDAaXsDb.jpg', '/myikoqu8Z2gtE7TaBgk9r6fB9MF.jpg', 7.7, '06f7f24lpUI', array['1001']::text[], 422, null, 'segura', null),
(836, 'movie', 'Vidas secas', 'Vidas Secas', 'Vidas Secas', 1963, 'Nelson Pereira dos Santos', 'Vidas secas narra la historia de una familia Fabiano, su mujer, la sinhá Vitória, y sus dos hijos en el sertao de los años cuarenta. Realizado en una época de gran agitación política y social, en vísperas del golpe de estado que iba a instaurar la dictadura militar en Brasil, es uno de los títulos mayores del cine latinoamericano. (FILMAFFINITY)', '/Ag7TYDyQ1IoHzaegGr0cooiy8Xu.jpg', '/3KBuZG9keFgKAbIRnMMn4MoOzo7.jpg', 7.4, 'AfULhmjFuZk', array['1001']::text[], 424, null, 'segura', null),
(44065, 'movie', 'La casa negra (Khaneh siah ast)', 'La casa es negra', 'خانه سیاه است', 1963, 'Forugh Farrokhzad', 'Documental Iraní que relata de forma cruda y poética la vida y sufrimiento en una colonia de leprosos.', '/eFIpxjYOMLoN5BBjy4McT7rBKmr.jpg', '/aQNXzRCtwO2iMcIIGrT80cmUhxr.jpg', 7.5, '-oOCObHFx28', array['1001']::text[], 425, null, 'segura', null),
(85834, 'movie', 'Méditerranée', 'Méditerranée', 'Méditerranée', 1963, 'Jean-Daniel Pollet', '[Here] Pollet made a work that is the very definition of what French critics like to call an ovni or ufo (as in ‘unidentified filmic object’). [It] has been described as being ‘like a comet in the sky of French cinema,’ an ‘unknown masterpiece,’ and an ‘unprecedented’ work that refuses interpretation even as it has provoked reams of critical writing. Its rhythmic collage of images – a girl on a gurney, a fisherman, Greek ruins, a Sicilian garden, a Spanish corrida – is accompanied by an abstract commentary written by Sollers, and only the somber lyricism of Antoine Duhamel’s score holds the film’s elements together. At first viewing, you fear that [it] might fly apart into incoherent fragments. Instead, over the course of its 45 minutes it invents its own rules, and you realize you’re watching something like the filmic channeling of an ancient ritual.', '/2Rvd3U289UUnnAOcnhupnUPqCHD.jpg', '/123bRGZNuDDuHrRZiIpMEJOuSVk.jpg', 5.8, '7qbJDxbmuHc', array['1001']::text[], 425, null, 'segura', null),
(11772, 'movie', 'La mansión encantada', 'La mansión encantada', 'The Haunting', 1963, 'Robert Wise', 'Acompañado de un grupo de personas, un científico se instala en una vieja mansión donde han se han cometido terribles y misteriosos crímenes. Su objetivo es comprobar si siguen produciéndose en el lugar fenómenos extraños. Una de las invitadas es la insegura Eleanor, cuyas habilidades psíquicas le hacen sospechar que de algún modo está conectada con los espíritus que todavía habitan la vieja mansión.', '/60Uh5xipzwwMejn6V1b6TJ2hLbu.jpg', '/9CVUzIPyBMnHsDDighQNgkDYsP9.jpg', 7.1, 'sMNldkdsVhw', array['1001']::text[], 426, null, 'segura', null),
(42987, 'movie', 'El sirviente', 'El sirviente', 'The Servant', 1963, 'Joseph Losey', 'Un intrigante y manipulador mayordomo consigue, gradualmente, dominar la vida del señor al que sirve, aprovechándose de sus debilidades sexuales. Un tenso y adulto drama psicológico que obtuvo excelentes críticas.', '/7aqzvi7mRfQAzSdWKSZcm7haoix.jpg', '/a5NNxs0HA6CEEtCNCUDvOZiQqIK.jpg', 7.6, 'naaFmYU2_I8', array['1001']::text[], 428, null, 'segura', null),
(27197, 'movie', 'La venganza de un actor (Yukinojo henge)', 'La venganza de un actor', '雪之丞変化', 1963, '市川崑', 'Mientras representa una obra de kabuki haciendo un tour con su compañía teatral, un actor descubre a los tres hombres que empujaron al suicidio a sus padres veinte años atrás. Planeará una tranquila venganza.', '/xmXcyNWO1YMj7apboo01lrMPOfO.jpg', '/sd7UGHu2DasJz1mKVI0YTpQK1qo.jpg', 6.6, 'ZpWmkGdfgWA', array['1001']::text[], 428, null, 'segura', null),
(658, 'movie', 'James Bond contra Goldfinger', 'James Bond contra Goldfinger', 'Goldfinger', 1964, 'Guy Hamilton', 'Un malvado magnate, Auric Goldfinger, quiere hacer estallar una bomba atómica en Fort Knox, donde está toda la reserva federal de oro de los Estados Unidos, para poder así incrementar enormemente el precio del metal dorado.', '/tA0AqFwuFvQCzLdBzEnIlK4RayX.jpg', '/mM4WeXqJd2tu1gCF5GYyAZf2Npl.jpg', 7.4, 'Ha94ny648TQ', array['1001']::text[], 429, null, 'segura', null),
(46787, 'movie', 'Scorpio Rising', 'Scorpio Rising', 'Scorpio Rising', 1964, 'Kenneth Anger', 'Este mediometraje narra las prácticas sádicas de un grupo de motoqueros nazis homosexuales. Uno de los films claves del cine independiente norteamericano. Se le considera uno de los primeros films posmodernos y una gran influencia en directores como Martin Scorsese o David Lynch.', '/fs9QDvOzOpZCaa2rv1U57jAFfYU.jpg', '/ew4ogBGU2TkervI02yKt1r4mV0v.jpg', 6.6, 'YB0nLIWwxvY', array['1001']::text[], 430, null, 'segura', null),
(5967, 'movie', 'Los paraguas de Cherburgo', 'Los paraguas de Cherburgo', 'Les Parapluies de Cherbourg', 1964, 'Jacques Demy', 'Geneviève es una joven que vive con su madre y le ayuda en la tienda de paraguas que tienen en Cherburgo. Está enamorada de Guy, un joven mecánico, con el que piensa casarse a pesar de la oposición de su madre, que considera a Geneviève demasiado joven y a Guy demasiado pobre. Para pagar una deuda, la madre se ve obligada a vender un collar a un rico joyero que se enamora de Geneviève desde el primer momento. Mientras tanto, Guy tendrá que ausentarse dos años para ir a Argelia a hacer el servicio militar.', '/q29ZeN0RGtY5PWQPK37exqdGUvI.jpg', '/m1Gei9O5GfLoJHQjBaxWBSkXX2y.jpg', 7.4, '7H-fl3njp5s', array['1001']::text[], 431, null, 'segura', null),
(506, 'movie', 'Marnie, la ladrona', 'Marnie la ladrona', 'Marnie', 1964, 'Alfred Hitchcock', 'Marnie es una embustera y una ladrona compulsiva que se sirve de su trabajo como secretaria para robar. Cuando Mark Rutland la contrata, no sólo no abandona sus delictivos hábitos, sino que, además, se comporta de manera absolutamente desquiciada. A pesar de todo, Mark, cediendo a un impulso inexplicable, decide casarse con ella y averiguar las razones de su obsesivo comportamiento. Cuando un terrible accidente lleva a Marnie a una situación límite, Mark la obliga a enfrentarse a sus terrores cuyas raíces se hunden en el pasado.', '/zeT1khBPdXrLhBktqH4wfNzQsQs.jpg', '/dmznYjPfNpNMJZtmnlgSutIDot2.jpg', 7.1, 'zdErt_teseo', array['1001']::text[], 432, null, 'segura', null),
(16672, 'movie', 'La mujer de arena (Suna no onna)', 'La mujer de la arena', '砂の女', 1964, '勅使河原宏', 'Un entomólogo en busca de insectos en un desierto de arena se ve de repente atrapado conviviendo con una mujer que vive sola en una vieja casa, y con la que establecerá una extraña relación.', '/8HXTSiDquKF9g88rSK5XHCcC1TJ.jpg', '/dxfFh9pTKDaYH2B6PwcR6ohCM1L.jpg', 8.2, 'UFbJ9iDeZgg', array['1001']::text[], 433, null, 'segura', null),
(11113, 'movie', 'My Fair Lady', 'My Fair Lady (Mi bella dama)', 'My Fair Lady', 1964, 'George Cukor', 'En una lluviosa noche de 1912, el excéntrico y snob lingüista Henry Higgins conoce a Eliza Doolittle, una harapienta y ordinaria vendedora de violetas. El vulgar lenguaje de la florista despierta tanto su interés que hace una arriesgada apuesta con su amigo, el coronel Pickering: se compromete a enseñarle a hablar correctamente el inglés y a hacerla pasar por una dama de la alta sociedad en un plazo de seis meses.', '/e9iY66L0QbSrfLtmFACvTrNVsZN.jpg', '/xMoQjqa3JUc2unO4nF9PmM1JTQu.jpg', 7.5, 'ZJBM6qs22sE', array['1001']::text[], 433, null, 'segura', null),
(935, 'movie', 'Teléfono rojo. ¿Volamos hacia Moscú?', '¿Teléfono rojo? Volamos hacia Moscú', 'Dr. Strangelove or: How I Learned to Stop Worrying and Love the Bomb', 1964, 'Stanley Kubrick', 'Convencido de que los comunistas están contaminando los Estados Unidos, un general ordena, en un acceso de locura, un ataque aéreo nuclear sorpresa contra la Unión Soviética. Su ayudante, el capitán Mandrake, trata de encontrar la fórmula para impedir el bombardeo. Por su parte, el presidente de los EE.UU. se pone en contacto con Moscú para convencer al gobierno soviético de que el ataque no es más que un estúpido error. Mientras tanto, el asesor estadounidense, un antiguo científico nazi, el doctor Strangelove, confirma la existencia de la «Máquina del Juicio Final», un dispositivo de represalia soviético capaz de acabar con la humanidad para siempre.', '/snsOoRb1d4WD6q62PRfBuGLJ8xr.jpg', '/7i0L2ee4Iy0aXV6vR5u1ZmblOrx.jpg', 8.1, 'IE9CmX15PYA', array['1001']::text[], 434, null, 'segura', null),
(704, 'movie', '¡Qué noche la de aquel día!', '¡Qué noche la de aquel día!', 'A Hard Day''s Night', 1964, 'Richard Lester', 'Por primera vez los Beatles han decidido romper todas las reglas: saltarse el programa, ignorar sus obligaciones y saborear la libertad. Pero, para ello, tendrán que dar esquinazo a sus admiradores, esquivar a los periodistas y desobedecer a sus mánagers.', '/zWR73zszWGtIUcSstzi8JHomB1Y.jpg', '/9hWiNbvLR3nPDanTdEWOc4EeBGp.jpg', 7.3, 'TWbiVqlSMgc', array['1001']::text[], 436, null, 'segura', null),
(26638, 'movie', 'Desierto rojo', 'El desierto rojo', 'Il deserto rosso', 1964, 'Michelangelo Antonioni', 'Después de sufrir un grave accidente de coche, una mujer comienza a percibir la ciudad en que vive, Rávena, como un desierto tanto en el plano físico como en el de las relaciones personales. Las secuelas psicológicas le impiden llevar una vida normal y relacionarse con la gente que la rodea.', '/mQK9IgNEkG6yMCCqCS1shrbCiGu.jpg', '/xe43LKesFXjQgP4W1s2juf7Tb4t.jpg', 7.3, 'SY_MEkvIRuo', array['1001']::text[], 437, null, 'segura', null),
(26782, 'movie', 'Sombras de antepasados olvidados (Tini zabutykh predkiv)', 'Los corceles de fuego', 'Тіні забутих предків', 1965, 'სერგო ფარაჯანოვი', 'Desde su más tierna infancia, Ivan y Marichka viven un apasionado y romántico amor a pesar de la enemistad que acaba enfrentando a sus familias. Incluso cuando se ven obligados a separarse, hay en el cielo una estrella que permite que se acuerden el uno del otro.', '/znV2lj6cbJGO7LZCAafXoDtvt2w.jpg', '/9UQoFWYiNU1NIz7pQlg5Wnub9In.jpg', 7.5, 'YUjYKxO-JRQ', array['1001']::text[], 437, null, 'probable', '[{"tmdb_id": 26782, "titulo": "Shadows of Forgotten Ancestors", "original": "Тіні забутих предків", "anio": 1965, "votos": 198, "poster_path": "/9oSZTeejmx80tIBVSqYzJpFhjkI.jpg", "sim": 0.235}]'::jsonb),
(42788, 'movie', 'Antes de la revolución', 'Antes de la revolución', 'Prima della rivoluzione', 1964, 'Bernardo Bertolucci', 'A la edad de 22 años, Bertolucci dirige este drama político que relata la historia de un joven que se acerca al comunismo mientras mantiene una relación incestuosa con su tía.', '/2yQEVuhjtvmy2FESs5wW4dChfwr.jpg', '/br2P3BpVJHbtGWRiWiaPNSbTjlB.jpg', 7.0, 'Zh2KM4Y4bA8', array['1001']::text[], 438, null, 'segura', null),
(25319, 'movie', 'La máscara de la muerte roja', 'La máscara de la muerte roja', 'The Masque of the Red Death', 1964, 'Roger Corman', 'Edad Media, siglo XII. Inspirada en el relato homónimo de Edgar Allan Poe (1809-1849). Mientras una plaga devastadora -conocida como la Muerte Roja- diezma la población de una pequeña provincia italiana, el sádico y excéntrico príncipe Próspero se encierra con sus amigos en una de sus propiedades fortificadas para evitar el contagio. Para evadirse de la tragedia, decide organizar una fiesta de máscaras, en la que somete a los invitados a todo tipo de juegos depravados, de los que sólo podrán salir indemnes dos inocentes.', '/sSYceyGZrWskWDsn3MHtipJ1wFM.jpg', '/oHVfPPSlii66NTQpOrRurivfrDW.jpg', 6.7, 'clT8P-v9uso', array['1001']::text[], 438, null, 'segura', null),
(34181, 'movie', 'Gertrud', 'Gertrud', 'Gertrud', 1964, 'Carl Theodor Dreyer', 'Gertrud es una mujer madura e idealista que busca el amor absoluto, con mayúsculas, pero sus experiencias sentimentales se ven siempre abocadas al fracaso. Decide separarse de su marido, un eminente político, porque él antepone el trabajo al amor. Se enamora de un joven músico que empieza a cosechar sus primeros éxitos, pero para él, que sólo piensa en sí mismo, Gertrud no es más que una aventura pasajera. Por otra parte, un antiguo novio poeta reaparece en su vida con la pretensión de que reanuden su antigua relación.', '/cmrIKdZWygU7VoSepx3mKBk1M3V.jpg', '/9g3D4uqDYeukbSGckW8khR4G93C.jpg', 7.3, 'ofoj3YEER0A', array['1001']::text[], 439, null, 'segura', null),
(24192, 'movie', 'El evangelio según San Mateo', 'El evangelio según San Mateo', 'Il vangelo secondo Matteo', 1965, 'Pier Paolo Pasolini', 'En clave neorrealista, pero sin apartarse del texto bíblico, el polémico Pasolini realiza un cercano retrato de Jesús de Nazaret.', '/dRGbPx5f8CdpMUD54YyfKzLeJLB.jpg', '/iz7xP1INmMTAfRKaToWVmXrrE1P.jpg', 7.4, '1fzJCjZ8X34', array['1001']::text[], 440, null, 'segura', null),
(67612, 'movie', 'Dios y el diablo en la tierra del sol', 'Dios y el diablo en la tierra del sol', 'Deus e o Diabo na Terra do Sol', 1964, 'Glauber Rocha', 'Dios y el diablo en la tierra del sol (Deus e o diabo na terra do Sol), el segundo largometraje de Rocha, pertenece a este movimiento renovador del cine brasilero que influirá por años en otros autores latinoamericanos. Inspirado en la "Estética de la violencia", apela al signo que, según Rocha, caracteriza a su pueblo, el hambre, que a la vez es su originalidad, pues el hambre convoca a una violencia transformadora que se convierte en  acto revolucionario, donde el colonizador llega a tomar conciencia de la existencia del colonizado.', '/lAM5RnCNXUKngIz0ITS3D3xpzkU.jpg', '/sDKHdt84JGzfxAJp2vqLdVzPj0Y.jpg', 7.1, '06lr4b9vA60', array['1001']::text[], 441, null, 'segura', null),
(3763, 'movie', 'El demonio (Onibaba)', 'Onibaba', '鬼婆', 1964, 'Kaneto Shindō', 'Mientras su hijo, Kichi, está en guerra, una mujer y su nuera sobreviven matando a samuráis que se pierden en su pantano y luego vendiendo los objetos de valor que encuentran. Ambos quedan devastados cuando se enteran de que Kichi ha muerto, pero su esposa pronto comienza una aventura con un vecino que sobrevivió a la guerra, Hachi. La madre lo desaprueba y, cuando no puede robarse a Hachi, intenta asustar a su nuera con una misteriosa máscara de un samurái muerto.', '/ptk0GHF7xwVxFinfsG31UGUlcl6.jpg', '/AcAMkNfQ21cL7EJzs5eVx24k3H4.jpg', 7.7, 'sknsvtX68yw', array['1001']::text[], 442, null, 'probable', '[{"tmdb_id": 3763, "titulo": "Onibaba", "original": "鬼婆", "anio": 1964, "votos": 510, "poster_path": "/ptk0GHF7xwVxFinfsG31UGUlcl6.jpg", "sim": 1.0}, {"tmdb_id": 2786, "titulo": "Pierrot el loco", "original": "Pierrot le fou", "anio": 1965, "votos": 979, "poster_path": "/suOAqdXi7mEiTLEHmAZlwfqYTzM.jpg", "sim": 0.286}, {"tmdb_id": 12602, "titulo": "El tormento de las trece doncellas", "original": "Die Schlangengrube und das Pendel", "anio": 1967, "votos": 88, "poster_path": "/yLHhBD83gIKScTUc5DQBErXEg9s.jpg", "sim": 0.211}, {"tmdb_id": 42998, "titulo": "El horrible secreto del doctor Hichcock", "original": "L''orribile segreto del Dr. Hichcock", "anio": 1962, "votos": 73, "poster_path": "/zbcgJKLess4qZVLmGunRIWo1t64.jpg", "sim": 0.233}]'::jsonb),
(85871, 'movie', 'Vinyl', 'Vinyl', 'Vinyl', 1965, 'Andy Warhol', 'La original representación que hace Warhol del libro "La Naranja Mecánica", de Anthony Burgess.', '/eb2OD1I6u6AaMx8ze5qSKhuLpkz.jpg', '/y9htC5WfjvH4ByG1GPOsv07rypD.jpg', 4.6, 'nlh0tR-HPMc', array['1001']::text[], 442, null, 'segura', null),
(25905, 'movie', 'La tienda en la calle mayor', 'La tienda en la calle Mayor', 'Obchod na korze', 1965, 'Ján Kadár, Elmar Klos', 'Anton Brtko es un humilde carpintero que trata de vivir con placidez en una pequeña ciudad eslovaca durante la Segunda Guerra Mundial. Aunque observa con ironía y desprecio a los seguidores nazis que tratan de imponer su disciplina sobre la comunidad, la presión de su esposa Evelyn y su cuñado Markus, un caudillo fascista local, no deja de poner trabas a su tranquilidad. Cuando Markus le ofrece hacerse cargo, en calidad de ario, de la mercería de la anciana Sra. Lautmann, su vida queda trastocada. Mientras Evelyn se ilusiona con la idea de enriquecerse, Tono intenta hacer entender a la Sra. Lautmann que queda relegada del negocio por ser judía, pero no sólo le resulta imposible a causa de la sordera de la mujer, sino que además entre ambos surge una relación de ternura y comprensión mutua. Las situaciones cómicas en la tienda se suceden mientras la fiebre antisemita se va intensificando en el exterior.', '/oOEOES7oqfND32lqCdaIugJ8TMl.jpg', '/dpa5PiYGIvkjeMTcBG9VD4bQOjg.jpg', 7.1, 'gvZE9Yuxkyg', array['1001']::text[], 443, null, 'segura', null),
(907, 'movie', 'Doctor Zhivago', 'Doctor Zhivago', 'Doctor Zhivago', 1965, 'David Lean', 'Rusia, revolución bolchevique (1917). La guerra produce una convulsión general en un país dividido. En medio del conflicto, asistimos al drama íntimo de un hombre que lucha por sobrevivir. Este hombre es Zhivago, poeta y cirujano, marido y amante, cuya vida trastornada por la guerra afecta a las vidas de otros, incluida Tonya, su mujer, y Lara, la mujer de la que se enamora.', '/ewV2RlSlMs5jRKVlFNHZ9u8t6Ms.jpg', '/wUaDgHfW7fViru7IubWa6Nronq9.jpg', 7.6, 'M1iQ5hQTR5s', array['1001']::text[], 444, null, 'segura', null),
(26508, 'movie', 'El juego de la guerra', 'El juego de la guerra', 'The War Game', 1966, 'Peter Watkins', 'Filmada como un falso documental, la película retrata el hipotético bombardeo nuclear en la ciudad inglesa de Rochester, el caos provocado por la evacuación forzada de la ciudad en medio del desconocimiento de las consecuencias de una guerra de esas características, y la lucha posterior de los escasos sobrevivientes para adaptarse a la nueva situación en el entorno radioactivo, y un mundo afectado en sus estructuras arquitectónicas y sociales. (FILMAFFINITY)', '/puJGNnrAPOv3BUMI9mKlCJp3UrQ.jpg', '/soIpQdRz2HzTyRl8zZemGgeaH8h.jpg', 7.7, 'vR3ySErpgBQ', array['1001']::text[], 445, null, 'segura', null),
(43618, 'movie', 'Olimpíada de Tokyo', 'Las olimpiadas de Tokio', '東京オリンピック', 1965, '市川崑', 'Aclamado documental dedicado a los Juegos Olímpicos que Japón hospedó en 1964. (FILMAFFINITY)', '/hhdbYn3Yp8JbbXLOpJ8z4qDl6TK.jpg', '/xi7frd8JRME37yCsSEf6orYiQ0K.jpg', 7.7, 'WHt0eAdCCns', array['1001']::text[], 445, null, 'segura', null),
(17295, 'movie', 'La batalla de Argel', 'La batalla de Argel', 'La battaglia di Algeri', 1966, 'Gillo Pontecorvo', 'Octubre de 1957. Los paracaidistas del coronel Mathieu rodean el refugio Ali-La-Pointe, responsable de la guerra de guerrillas urbana. Durante sus horas de reclusión forzada, Ali revive el viaje que lo llevó de la condición de delincuente a la de líder guerrillero del F.L.N. Noviembre de 1954, la organización terrorista inicia su actividad en Argelia; Fueron los primeros atentados con bombas en bares, estaciones de tren y cines de la “ciudad europea”. Ali se convierte en uno de los líderes de la organización, bajo la dirección de Ben M''Hidi, mientras los paracaidistas llegan a Argel recibidos por la población europea. El coronel Mathieu, aprovechando una huelga, entra en el barrio árabe y realiza las primeras detenciones...', '/tw3GaZhFDxtVJdibJwbnE3FSthl.jpg', '/ze7GsNSv418o7pzqc9fb00LWWDk.jpg', 7.9, 'vhhoS3zOskE', array['1001']::text[], 446, null, 'segura', null),
(8785, 'movie', 'Manuscrito encontrado en Zaragoza', 'El manuscrito encontrado en Zaragoza', 'Rękopis znaleziony w Saragossie', 1966, 'Wojciech Jerzy Has', 'Durante el asedio a Zaragoza, un general francés descubre un extraño manuscrito que, al ser leído, le transporta a una España surrealista en la que los espíritus de unos bandidos ahorcados, bajo la apariencia de hermosas huríes, se dedican a seducir y atrapar en los laberintos del tiempo a todo viajero extraviado que ose adentrarse en sus dominios.', '/7FbveRzxtdn7zbZyjjZnT0FsxKI.jpg', '/rtWQw7yZEbFZrjfuHdUGZ6f7KkP.jpg', 7.7, 'knA_-a-bhKg', array['1001']::text[], 447, null, 'segura', null),
(15121, 'movie', 'Sonrisas y lágrimas', 'Sonrisas y lágrimas', 'The Sound of Music', 1965, 'Robert Wise', 'Austria, 1938. Maria es una alegre novicia que abandona la abadía de Salzburgo para convertirse en la institutriz de los siete hijos de un militar retirado, el capitán Von Trapp, viudo desde hace poco tiempo. La casa de los Von Trapp funciona como un cuartel, pero Maria consigue devolver la alegría a los niños y ganarse su respeto y cariño.', '/3mYxH1mwSmNoyZF4xvDvcEpH18F.jpg', '/ioQYjcRnU54ir5ltgyS7k53zw5x.jpg', 7.7, 'Q7wZClqWm_o', array['1001']::text[], 447, null, 'segura', null),
(8072, 'movie', 'Lemmy contra Alphaville', 'Alphaville', 'Alphaville, une étrange aventure de Lemmy Caution', 1965, 'Jean-Luc Godard', 'A Alphaville, una ciudad futurista situada en otro planeta, llega el periodista Ivan Johnson, siguiendo la pista del profesor Von Braun. Los otros agentes que le han precedido, Dick Tracy y Flash Gordon, han muerto. Von Braun, apodado Nosferatu, es el creador de Alpha 60, la máquina que comanda la vida mental de los habitantes de la ciudad.', '/ymE2nnxd1XH9yMaHG1EWVHOZ1b1.jpg', '/iOUhnp01rP9Xr5QG66LMAKSDkYv.jpg', 6.9, 'CzaATgGHmy0', array['1001']::text[], 448, null, 'probable', null),
(986, 'movie', 'Campanadas a medianoche', 'Campanadas a medianoche', 'Campanadas a medianoche', 1965, 'Orson Welles', 'Guerra de los Cien Años (ss. XIV y XV). Enrique IV, primer monarca de la dinastía de los Lancaster, usurpó el trono, en 1399, arrebatándoselo a su primo Ricardo II. A su muerte, le sucede, con el nombre de Enrique V, el príncipe Hal, que reniega de Falstaff, su viejo compañero de juergas, y lo condena al exilio.', '/8IGDi8C23poyj7DBJ0JXHmMX990.jpg', '/83aNchGigrkj6uDiknje6OwY6sl.jpg', 7.2, 'z6_yO1HqP_w', array['1001']::text[], 449, null, 'segura', null),
(11481, 'movie', 'Repulsión', 'Repulsión', 'Repulsion', 1965, 'Roman Polanski', 'Carol Ledoux es una bella y reprimida joven belga que vive con su hermana Helen en un apartamento de Londres. Carol experimenta sentimientos simultáneos y contradictorios de atracción y repulsión hacia los hombres; por eso para ella resulta tan incómoda la relación que mantiene su hermana con un hombre casado. Cuando la pareja se marcha de vacaciones, Carol comienza a tener alucinaciones y su mente se desquicia.', '/4GQ8F7Dd9oV493LvtdhgmukXl1I.jpg', '/5rbPwIdEZTyLTkpAgvGdacgCr7T.jpg', 7.4, 'BYZzJC_DqBI', array['1001']::text[], 450, null, 'segura', null),
(19120, 'movie', 'Giulietta de los espíritus', 'Giulietta de los espiritus', 'Giulietta degli spiriti', 1965, 'Federico Fellini', 'Giulietta, que duda de la fidelidad y del amor de su marido, acude a reuniones espiritistas buscando un consejo, una verdad, una señal que le haga ver que su marido aún siente cariño por ella y que puede recuperarlo. Por casualidad, conoce a Susy, perniciosa mujer que sólo vive para el amor y que está a punto de dar al traste con las ilusiones de Giulietta', '/4owvSGVUtF1CQaOMHLgZ39CiNWN.jpg', '/9VeXz4mj4QaOfTNSLy0owJHkWEo.jpg', 7.2, 'RcPiyeQRVy0', array['1001']::text[], 451, null, 'segura', null),
(2786, 'movie', 'Pierrot el loco', 'Pierrot el loco', 'Pierrot le fou', 1965, 'Jean-Luc Godard', 'Ferdinand Griffon, alias ''Pierrot'', huye de París con Marianne, la niñera que ha contratado su esposa. La pareja se dirige al sur de Francia, pero el viaje se torna muy peligroso cuando una banda de gángsters con los que Marianne está implicada, les va pisando los talones.', '/suOAqdXi7mEiTLEHmAZlwfqYTzM.jpg', '/4zJ9w3lZcZI3mBXcNiq6s8bqpDO.jpg', 7.3, 'TVvhJrrgfs0', array['1001']::text[], 452, null, 'segura', null),
(315, 'movie', 'Faster Pussycat! Kill! Kill!', 'Faster, Pussycat! Kill! Kill!', 'Faster, Pussycat! Kill! Kill!', 1965, 'Russ Meyer', 'Las bailarinas gogó son tres chicas a las que, tras una dura noche de trabajo, les gusta montarse en sus coches, pisar a fondo, y buscarse problemas. Así, cuando en medio del desierto encuentran a una joven pareja los retan a una carrera: él acaba matándose y a ella la secuestran. A continuación, en una gasolinera, el encargado les cuenta que en medio del desierto vive con sus dos hijos un viejo que esconde una enorme fortuna. Sin dudarlo, las chicas se dirigen a la casa para averiguar dónde está el dinero. (FILMAFFINITY)', '/mIQCAM3ciDWcW9i5RmDCUPfgYvx.jpg', '/xsR0iqyWuEwlbl1gkpOyh1dAusy.jpg', 6.4, 'gLTnzo-nd8Q', array['1001']::text[], 453, null, 'segura', null),
(86303, 'movie', 'Río de oro (Subarnarekha)', 'সুবর্ণরেখা', 'সুবর্ণরেখা', 1965, 'Ritwik Kumar Ghatak', 'After an old college friend offers him a job at an iron foundry, the upright and honest Ishwar leaves a shanty town on the outskirts of Calcutta where he lives with a group of refugees from East Bengal. With plans to forge a solid living for himself, sister Sita and Abhiram, an orphaned boy he offers a home to, Ishwar is accused of selling out and deserting his people.', '/sPCOcTSagm3muSyvoaT6rza2eqp.jpg', '/2ZWfSMeOxDQGji53pTOukgqmf2S.jpg', 6.5, 'tYRX96yT7ig', array['1001']::text[], 454, null, 'probable', '[{"tmdb_id": 86303, "titulo": "The Golden Thread", "original": "সুবর্ণরেখা", "anio": 1965, "votos": 43, "poster_path": "/3le6UjPH0E8ZNgdBwPysDSag5jE.jpg", "sim": 0.32}]'::jsonb),
(86482, 'movie', 'El hombre del cráneo rasurado', 'El hombre del cráneo rasurado', 'De man die zijn haar kort liet knippen', 1966, 'André Delvaux', 'Un profesor de peluquería se enamora obsesivamente de la enigmática belleza de una alumna. Al ser rechazado por la muchacha, sufre una crisis de enajenación mental: decide raparse la cabeza al cero y evitar todo contacto con el mundo que lo rodea. Su cerebro trastornado tiene una percepción distorsionada de la realidad; vive en un estado de confusión que no le permite distinguir los sueños de la vigilia, la vida de la muerte, el alma del cuerpo.', '/gAnv3uIp6XMUUcrFtVSE34oQkMJ.jpg', '/eYMhYS5QrQ1wKZCtCrE1aOniP4Z.jpg', 6.7, null, array['1001']::text[], 455, null, 'segura', null),
(86811, 'movie', 'Hold Me While I''m Naked', 'Hold Me While I''m Naked', 'Hold Me While I''m Naked', 1966, 'George Kuchar', 'Presented as loosely autobiographical, Hold Me While I’m Naked centres on the tribulations of an independent filmmaker, frustrated at every turn as he tries to make a film that pretends to artistic merit.', '/80DDYIRdPKNrmsTPAyJrzeGsGkP.jpg', '/aM5OsHMg1GnNCBNsqugKbzGvbvD.jpg', 4.7, null, array['1001']::text[], 455, null, 'segura', null),
(1052, 'movie', 'Blowup. Deseo de una mañana de verano', 'Blow-Up', 'Blow-Up', 1966, 'Michelangelo Antonioni', 'Un fotógrafo realiza unas tomas en un parque londinense y descubre al revelarlas una forma irreconocible que resulta ser un cadáver.', '/bwlz1BnokYtsol8chqVgjG1ICB6.jpg', '/rWtRkNGkg05rET8taCA96c7heLb.jpg', 7.3, 'PRENEOHlcbw', array['1001']::text[], 456, null, 'probable', '[{"tmdb_id": 1052, "titulo": "Blow-Up", "original": "Blow-Up", "anio": 1966, "votos": 1439, "poster_path": "/bwlz1BnokYtsol8chqVgjG1ICB6.jpg", "sim": 0.279}]'::jsonb),
(429, 'movie', 'El bueno, el malo y el feo', 'El bueno, el feo y el malo', 'Il buono, il brutto, il cattivo', 1966, 'Sergio Leone', 'Tres pistoleros buscan un tesoro de oro confederado escondido en un cementerio, en plena Guerra de Secesión.', '/71HKV5F9bfm05ZZnjGmRuFpUVCo.jpg', '/x4biAVdPVCghBlsVIzB6NmbghIz.jpg', 8.5, '9gEiRcNc2Rs', array['1001','clasicos']::text[], 458, null, 'segura', null),
(46919, 'movie', 'Las margaritas', 'Las margaritas', 'Sedmikrásky', 1966, 'Věra Chytilová', 'Dos chicas jóvenes concluyen, mientras toman el sol en bikini, que "si en este mundo todo está corrompido, estaremos corrompidas nosotras también". Así se activa el mecanismo que pone en marcha la película: una tras otra, se irán produciendo escenas inconexas en las cuáles las dos protagonistas juegan a ser malas con su entorno. Engañan a hombres maduros para comer gratuitamente, escriben y dibujan en las paredes de su casa, improvisan un baile en un cabaret para boicotear el número que está en escena, engullen y despedazan los manjares de un banquete preparado para otros. Rompiendo toda linealidad narrativa y empleando la técnica collage tanto a nivel visual como auditivo.', '/n9iwlcq3C2fYRZwXWTQA80kwRen.jpg', '/A1Ajyl9qdUvK94ABteqEelk6M1Q.jpg', 7.3, '9vBGo95SJz4', array['1001']::text[], 460, null, 'segura', null),
(26259, 'movie', 'Ven a beber conmigo (Da zui xia)', 'Bebe conmigo', '大醉俠', 1966, '胡金銓', 'Una banda de salteadores atacan a un convoy del gobierno y secuestran al oficial al mando con la intención de intercambiarlo por su Jefe detenido. La Dorada Golondrina, un agente de la corte, es enviada por el gobernador para salvar al funcionario.', '/4L7tkjbUdwUmH5HzpW0S60yAUNv.jpg', '/kV73hJI6YUidib2OFKPUaKKwt4m.jpg', 6.7, '01Xl296CxQE', array['1001']::text[], 460, null, 'probable', '[{"tmdb_id": 26259, "titulo": "Come Drink with Me", "original": "大醉俠", "anio": 1966, "votos": 169, "poster_path": "/bVQhrpCfMZy8YoiAmbze1qWIoho.jpg", "sim": 0.286}]'::jsonb),
(10633, 'movie', 'En el calor de la noche', 'En el calor de la noche', 'In the Heat of the Night', 1967, 'Norman Jewison', 'En una pequeña población de Mississippi, el policía Sam Wood descubre el cadáver de un industrial. Poco después, detiene en la estación a un hombre negro que, tras ser interrogado por el jefe de la policía local, Billl Gillespie, resulta ser un inspector de la policía de Filadelfia llamado Virgil Tibbs. Ambos policías deciden colaborar para investigar el asesinato.', '/lRkD04pmGpVSYsObL4LZctxiCt9.jpg', '/xY5sgU09cOsvEAgJZaYo2aOZEFi.jpg', 7.7, 'd15DhX_ltls', array['1001']::text[], 461, null, 'segura', null),
(3092, 'movie', 'Plan siniestro', 'Plan siniestro', 'Seance on a Wet Afternoon', 1964, 'Bryan Forbes', 'Una mujer londinense, obsesionada por la muerte prematura de su hijo, está convencida de poseer los dones de una "medium". Para ganar prestigio y atraer clientela, le propone a su marido secuestrar a un niño y, después, ir proporcionando las pistas necesarias para localizarlo.', '/jXGqjc1Gi4HSLOXmibzLbIM4xLm.jpg', '/bGXaffbdbYqwV4mkVUA4y6F6qdf.jpg', 7.3, 'oLrtv6YfyVE', array['1001']::text[], 461, null, 'segura', null),
(396, 'movie', '¿Quién teme a Virginia Woolf?', '¿Quién teme a Virginia Woolf?', 'Who''s Afraid of Virginia Woolf?', 1966, 'Mike Nichols', 'George y Martha son un matrimonio que se profesa un odio salvaje. Ambos tienen personalidades autodestructivas, conocen perfectamente las debilidades del otro y saben cómo exasperarlo. George es un profesor de historia alcohólico. Martha, la hija del director de la universidad donde George da clases, es una mujer frustrada y vulnerable. Un sábado por la noche, después de una fiesta, invitan a su casa a un nuevo profesor y a su esposa. La presencia de esta pareja no evita que Martha y George se humillen y maltraten como de costumbre. A través de este cruel juego sale a relucir la verdad tanto sobre los anfitriones como sobre los invitados.', '/o8pH2izWv39EMVJkTVojYpKAR7.jpg', '/sZxPKiNCK8piKBtXAbm3Ucj6RQk.jpg', 7.7, 'ppeMfoKdbAY', array['1001']::text[], 462, null, 'segura', null),
(797, 'movie', 'Persona', 'Persona', 'Persona', 1966, 'Ingmar Bergman', 'Elisabeth, una célebre actriz teatral, es hospitalizada tras perder la voz durante una representación de ''Electra''. Una doctora la somete a toda una serie de pruebas, y afirma que está sana y bien, pero ella sigue sin hablar y permanece en el pabellón. Alma, la enfermara encargada de cuidarla, intenta establecer una relación con ella y se dedica a hablarle todo el tiempo.', '/pnJMAumh0gaZC02r9t5YmN9HR74.jpg', '/amr72SENYz7AM4Hq5WBXxFBJEY6.jpg', 8.1, '8ZO01M8k1mg', array['1001']::text[], 464, null, 'segura', null),
(20108, 'movie', 'Al azar de Baltasar', 'Al azar, Baltasar', 'Au hasard Balthazar', 1966, 'Robert Bresson', 'Baltasar es un burro que vive sus primeros años rodeado de la alegría y los juegos de los niños hasta llegar a la edad adulta, en que es utilizado como una bestia de carga y maltratado por sus diferentes amos.', '/nYKaxsYt4TPfttu1cXB6D1soPS5.jpg', '/7LPz7NEYtLXcV44j0kRLLkZ54yH.jpg', 7.5, 'RN9H8ze3hXI', array['1001']::text[], 466, null, 'segura', null),
(4710, 'movie', 'Masculin, féminin', 'Masculino, femenino', 'Masculin féminin', 1966, 'Jean-Luc Godard', 'Paul es un joven idealista que acaba de terminar el servicio militar. Conoce a Madeleine, una joven atractiva que aspira a ser cantante pop, y trata de conquistarla. Ambos salen juntos y terminan juntos en la cama, aunque con dos amigas de Madeleine, Elisabeth y Catherine.', '/qJHD9j8mnXcYbsoNumUfP0R1LhL.jpg', '/83AMHdZU71x7U4aZ7QFGBRtdyxo.jpg', 7.2, '53KROTcwf-Y', array['1001']::text[], 466, null, 'segura', null),
(37247, 'movie', 'El graduado', 'El graduado', 'The Graduate', 1967, 'Mike Nichols', 'Un recién graduado sin rumbo vuelve a la casa de sus padres y empieza un romance con la esposa del socio de su padre.', '/z8QQ9T38rNEoCHlqHMgcJfwbZRd.jpg', '/lIY8ZTp6OJTAMfiorDGsPsJ5LT.jpg', 7.6, 'KVNFaxJspMQ', array['1001','clasicos']::text[], 468, null, 'segura', null),
(10227, 'movie', 'Playtime', 'Playtime', 'PlayTime', 1967, 'Jacques Tati', 'Un grupo de turistas americanas hace un viaje por Europa, que prevé la visita de una capital por día. Al llegar a París, se dan cuenta de que el aeropuerto es exactamente igual al de Roma, de que las carreteras son idénticas a las de Hamburgo y que las farolas guardan un curioso parecido con las de Nueva York. En resumidas cuentas, el escenario no cambia de una ciudad a otra. Y ya que no pueden conocer París, se conformarán con pasar veinticuatro horas con parisinos de verdad, entre ellos Monsieur Hulot.', '/cVTaZoFmws0jRSXykK4ayrYTkij.jpg', '/pKX8G6IN8ZCRvKeHh6ctqoHZl0K.jpg', 7.7, 'zrYB8hgyq4s', array['1001']::text[], 470, null, 'segura', null),
(87981, 'movie', 'Report', 'Report', 'Report', 1967, 'Bruce Conner', 'Bruce Conner’s most celebrated film for a reason: it takes historical moments that were replayed over and over on television—chilling repetition of Kennedy assassination coverage—and repurposes them into a meditation on how the media tries to exert authority and apply a sense of order to the anarchic. And though it may sound perverse to say so, the film is also—not incidentally—a thrill to watch. -- The A.V. Club', '/qma9BkU6i8HTSOvT5Ot7RzFax8y.jpg', '/bUQo8H4qx7UtnXqaJR44FWlus7O.jpg', 6.1, null, array['1001']::text[], 471, null, 'segura', null),
(27945, 'movie', 'Un hombre', 'Un hombre', 'Hombre', 1967, 'Martin Ritt', 'John Russell, desdeñado por sus "respetables" compañeros de viaje en diligencia, ya que fue criado por los indios, se convierte en su única esperanza de supervivencia cuando son atacados por bandidos.', '/uizk3iWkukzfWgPXKf20XWJu1zc.jpg', '/wNwE1HpHSTNZE4uIzOZ2AmYkOB1.jpg', 7.1, '24ZKMRSutuM', array['1001']::text[], 471, null, 'segura', null),
(649, 'movie', 'Bella de día', 'Bella de día', 'Belle de jour', 1967, 'Luis Buñuel', 'Sévérine, una joven casada con un atractivo cirujano, descubre la existencia de la prostitución diurna. Impulsada por la curiosidad, ingresa en la casa de citas de Anaïs y termina acostumbrándose a llevar una doble vida. La aparición de Marcel, un delincuente que se enamora de ella, complicará la situación de la protagonista. En 2006 contó con una secuela, "Belle Toujours", dirigida por Manoel de Oliveira.', '/6LBPUWNYYtC4R4tTxLSsVG4qKPG.jpg', '/9fJPLvrUV32MzpfDwXk7cOnj8hM.jpg', 7.3, 'gC1lO7lqMuw', array['1001']::text[], 472, null, 'segura', null),
(2433, 'movie', 'Las señoritas de Rochefort', 'Las señoritas de Rochefort', 'Les Demoiselles de Rochefort', 1967, 'Jacques Demy', 'Dos hermanas, ambas profesoras de música ( Deneuve y Dorléac), viven en la pequeña población de Rochefort y sueñan con encontrar un gran amor. Homenaje a los grandes musicales de la época dorada de Hollywood.', '/3hwBLy24duQxwW9DeWy51bDtDgR.jpg', '/8m7qOKlsdnxt4335vpFzpffuIVu.jpg', 7.7, 'vZFK8svwtxA', array['1001']::text[], 474, null, 'segura', null),
(8075, 'movie', 'Weekend', 'Week-End', 'Week End', 1967, 'Jean-Luc Godard', 'Particular visión del cataclismo de la burguesía a cargo del polémico y genial director francés. Una fábula apocalíptica, desencantada y satírica, definida como un nuevo viaje de Gulliver a través del colapso de la sociedad de consumo representada en una joven pareja de burgueses.', '/3GG9qrNe3W9BVCsmQyL88dO7c8U.jpg', '/beRcdPSD4cYcmMilMpsdrChpNGt.jpg', 6.9, 'dFJLuhVvBPM', array['1001']::text[], 474, null, 'segura', null),
(5511, 'movie', 'El silencio de un hombre', 'El silencio de un hombre', 'Le Samouraï', 1967, 'Jean Pierre Melville', 'La historia de un hermético y frío asesino a sueldo, interpretado por Alain Delon, es una de las obras más notables del cine negro francés.', '/rjA2UW47qTIeuL6aNHTbUu6yTP6.jpg', '/znLq5iyuMVvHwDdgZf6HyVUNjWB.jpg', 7.8, 'PTFV07ah4fY', array['1001']::text[], 475, null, 'segura', null),
(903, 'movie', 'La leyenda del indomable', 'La leyenda del indomable', 'Cool Hand Luke', 1967, 'Stuart Rosenberg', 'El impulsivo Luke Jackson ha sido condenado a dos años de trabajos forzados. Su delito fue romper en plena borrachera un poste de aparcamiento. La vida en el penal es durísima: tiene que convivir con presos condenados por delitos muy graves y, además, la violencia tanto de los presos como de los carceleros se ha convertido en un hábito imposible de erradicar. Luke, es un veterano de guerra que no está dispuesto a ceder, pero tendrá que pagar un alto precio por seguir siendo quien es.', '/pFMISXcKgTS27ZYgM5tIGIpzPJo.jpg', '/9TDi0FPOSAePfVLZXAUgFZhiMLf.jpg', 7.7, 'cxKUupk0kbY', array['1001']::text[], 476, null, 'segura', null),
(26039, 'movie', 'A quemarropa', 'A quemarropa', 'Point Blank', 1967, 'John Boorman', 'Después de haber dado un golpe muy lucrativo, un hombre es traicionado por su esposa y por su mejor amigo. Ambos lo abandonan, dándolo por muerto, en una celda de la abandonada prisión de Alcatraz. Años después, intentará vengarse y recobrar su parte del botín.', '/B8vJOHZJgPpeaZq9BSbObpaiMf.jpg', '/sousyLLi3l14qho6gATKYX7pEyR.jpg', 7.1, 'Z3CCNj_zMco', array['1001']::text[], 478, null, 'segura', null),
(88421, 'movie', 'Wavelength', 'Wavelength', 'Wavelength', 1967, 'Michael Snow', 'Wavelength" ("Longitud de onda"), es un viaje a través de una habitación con ventanales, un deslizamiento a través del tiempo cinematográfico (distintos tiempos, luces, texturas), un viaje que incluye una muerte y finaliza en una imagen inmóvil: una foto del mar. El deslizamiento es físico (óptico) y metafísico, y la nave es aquí un zoom virtual hacia delante (en realidad es fragmentario y no exacto) y un sonido progresivamente agudo, hasta el silencio final del mar quieto.', '/EJrUlzZ7kTrCP3czxqtb5dfS5i.jpg', '/sqb6J9GohKpqoeTLsG0pgP7AXg7.jpg', 5.4, null, array['1001']::text[], 479, null, 'segura', null),
(475, 'movie', 'Bonnie y Clyde', 'Bonnie y Clyde', 'Bonnie and Clyde', 1967, 'Arthur Penn', 'Durante la década de 1930, en plena Gran Depresión estadounidense, Bonnie Parker y Clyde Burrows, una joven pareja de bandidos, recorren Estados Unidos desafiando a las autoridades y atracando bancos.  La historia de las andanzas de dos de los más famosos atracadores de bancos de Estados Unidos de los años 30. Bonnie y Clyde fueron dos personajes muy peligrosos, tremendamente aficionados a apretar el gatillo y responsables de numerosas muertes entre los agentes de la ley. Sin embargo, la película da una visión mucho más amable de ellos.', '/jtDgrTlHkGlO3ZRWQfzErafv8ei.jpg', '/vmMC9rC2Z3iptDj2K5AiK0wlVAF.jpg', 7.5, 'hZpm1zj9510', array['1001']::text[], 480, null, 'segura', null),
(52885, 'movie', 'El rojo y el blanco (Csillagosok, katonák)', 'Los rojos y los blancos', 'Csillagosok, Katonák', 1967, 'Miklós Jancsó', 'Año 1917, en la frontera rusa durante la Primera Guerra Mundial. Los Blancos zaristas se enfrentan a los Rojos bolcheviques, que son apoyados por voluntarios húngaros. En la inmensa planicie se produce la caza del hombre, la ejecución de prisioneros, los caballos en desbandada... (FILMAFFINITY).', '/g7Gjcmw73XtGV8AYPhCDqucuLQd.jpg', '/tX46PTo0xv4XlxtUpMTujcUPOg4.jpg', 7.0, '2DzCL4kKb0Q', array['1001']::text[], 482, null, 'segura', null),
(9325, 'movie', 'El libro de la selva', 'El libro de la selva', 'The Jungle Book', 1967, 'Wolfgang Reitherman', 'Tras la muerte de sus padres, Mowgli, un niño de apenas dos años, queda abandonado en la selva y es recogido por una manada de lobos. En el seno de la manada, Mowgli es criado como un lobo más hasta que crece y empieza a desenvolverse por sí mismo en la selva.', '/1w8wk8htVPW5cdCYnRU4bt5y5Fw.jpg', '/3sbmRuIpYEH5dMvec4z4JxKQHoj.jpg', 7.3, 'kLJhKCfxecw', array['1001']::text[], 483, null, 'segura', null),
(25904, 'movie', 'Marketa Lazarová', 'Marketa Lazarová', 'Marketa Lazarová', 1967, 'František Vláčil', 'Historia ambientada en el Reino Checo durante la Edad Media que trata sobre la rivalidad entre dos clanes familiares de hidalgos pobres. Basada en la novela homónima de Vladislav Vancura, escritor checo del siglo XX.', '/iAD1q8GOO1q1h6hRCXgslAxDHBY.jpg', '/1Vbd0TVNZXlzTlyLkYnOMzpq1eH.jpg', 7.8, 'YF8uWhXtkJg', array['1001']::text[], 483, null, 'segura', null),
(38442, 'movie', 'El baile de los bomberos (Hoří, má panenko)', 'Al fuego, bomberos', 'Hoří, má panenko', 1967, 'Miloš Forman', 'El prestigioso director Milos Forman rueda esta historia sobre la fiesta de cumpleaños de un veterano bombero.', '/vJWevnJfqBQscGY1ROBUv1pzk08.jpg', '/7ncgCjyUgL9EsRfbHVjl25jDHQa.jpg', 7.1, 'GfJI4LzLBUw', array['1001']::text[], 484, null, 'segura', null),
(67062, 'movie', 'Tierra en trance', 'Tierra en trance', 'Terra em Transe', 1967, 'Glauber Rocha', 'Eldorado es un país ficticio latinoamericano donde vive el idealista, poeta anarquista y periodista Paulo Martins. Dos políticos, el populista Felipe Vieira y el conservador Porfirio Díaz, luchan por el poder en esta compleja realidad tropical donde nada es lo que parece.', '/fd1vSYOOkyiQzzVBtlJg5hUqk2Z.jpg', '/xCSzJsUmgd61nXjxoslbWOgOlbY.jpg', 7.2, null, array['1001']::text[], 485, null, 'segura', null),
(789, 'movie', 'Trenes rigurosamente vigilados', 'Trenes rigurosamente vigilados', 'Ostře sledované vlaky', 1966, 'Jiří Menzel', 'Ambientada durante la ocupación Nazi de Checoslovaquia, relata la vida de Milos, un joven funcionario de los ferrocarriles checos que carga con el karma de una genealogía de perdedores y desgraciados que han escapado heroicamente al modelo de vida de un hombre responsable a base de trampas y otras artimañas. El colaboracionista director de los ferrocarriles del pueblo les encarga la misión de proteger ciertos trenes estratégicos, indispensables para los planes de dominación del Führer en Europa central. Milos verá ahí la oportunidad de escapar a la maldición de los varones de su familia que no han sido nunca verdaderos hombres. Pero nuestro protagonista tiene un gran problema: no puede satisfacer los deseos de su novia Masa. De este modo, no se puede concentrar en la misión que le han encargado, ni podrá convencer al mundo de un valor desconocido hasta el momento en su familia.', '/iYNeJvHDokAYoryc3k2JZWgPuMV.jpg', '/pe2APM7NsJXfNRfq2cUWdc0dRbQ.jpg', 7.2, 'Igc0Jp62kEg', array['1001']::text[], 486, null, 'segura', null),
(43984, 'movie', 'Gaav (La vaca)', 'گاو', 'گاو', 1969, 'داریوش مهرجویی', 'An old villager deeply in love with his cow goes to the capital for a while. While he''s there, the cow dies and now the villagers are afraid of his possible reaction to it when he returns.', '/4EljZZUhZ9VcswtfO8hQ7SCJBDe.jpg', '/732Q6M5iyCljGQjymNmGLkPXA3d.jpg', 7.7, null, array['1001']::text[], 488, null, 'probable', '[{"tmdb_id": 43984, "titulo": "The Cow", "original": "گاو", "anio": 1969, "votos": 88, "poster_path": "/9MVUDF3o1ihrWSgGSvkF7IPesF9.jpg", "sim": 0.286}, {"tmdb_id": 7506, "titulo": "A lo loco", "original": "Harum Scarum", "anio": 1965, "votos": 35, "poster_path": "/ioRi937cX4ZQ0sIND9Rk7PjSgNG.jpg", "sim": 0.375}, {"tmdb_id": 138273, "titulo": "La Vacanza", "original": "La Vacanza", "anio": 1971, "votos": 15, "poster_path": "/48k9wtY94avn0vRQY1KI06DNBRG.jpg", "sim": 0.727}, {"tmdb_id": 197868, "titulo": "Vacaciones en la Costa Esmeralda", "original": "Vacanze sulla Costa Smeralda", "anio": 1968, "votos": 2, "poster_path": "/cn773tDI7Lm78aqLkdVXhTPbO7U.jpg", "sim": 0.25}]'::jsonb),
(57230, 'movie', 'Vij', 'El Viyi', 'Вий', 1967, 'Георгий Кропачёв, Константин Ершов', 'Khoma, un estudiante en un monasterio en Kiev, se pierde en el bosque mientras viaja a casa al final del trimestre con dos compañeros seminaristas. Al caer la noche encuentran alojamiento en la casa de una anciana. Khoma se mete en el establo y se acuesta a dormir, pero su descanso se ve perturbado por la anciana, que a la primera oportunidad, salta sobre su espalda y las dos salen volando con una escobapor el cielo nocturno. Al darse cuenta de que ha sido atrapado por una bruja, Khoma lucha por liberarse y golpea a la anciana en el suelo con un palo. Ante sus ojos, la bruja moribunda se transforma en una hermosa joven y Khoma huye de la escena. De regreso al monasterio, una delegación llega exigiendo que Khoma los acompañe de vuelta a su aldea para rezar por el cadáver de una joven durante tres noches. Al llegar a la aldea, el estudiante pronto descubre que debe pasar las noches encerrado solo en la iglesia con el cuerpo de la bruja que había dejado por muerta...', '/vm3M3T3qR77QFOhK5VAq906htuG.jpg', '/sNjRnpuMVSmavDnyWUiuTn6cY7T.jpg', 6.9, 'keuYSRXwcVg', array['1001']::text[], 488, null, 'probable', '[{"tmdb_id": 57230, "titulo": "Viy", "original": "Вий", "anio": 1967, "votos": 298, "poster_path": "/rgkp4X9C1NNobH8bq55zcMTQFCl.jpg", "sim": 0.667}, {"tmdb_id": 130620, "titulo": "De vijanden", "original": "De vijanden", "anio": 1968, "votos": 9, "poster_path": "/inZ3LEoAENU1GUuU6FEmQvHzcSE.jpg", "sim": 0.429}, {"tmdb_id": 109751, "titulo": "Bama Vijayam", "original": "பாமா விஜயம்", "anio": 1967, "votos": 3, "poster_path": "/yeT5lHcr3LJrPLOJTue8GLGvUaC.jpg", "sim": 0.4}, {"tmdb_id": 302139, "titulo": "Bhama Vijayam", "original": "భామ విజయం", "anio": 1967, "votos": 1, "poster_path": "/wyL56MC2nWXArbsR3ShJPjqkhsz.jpg", "sim": 0.375}]'::jsonb),
(335, 'movie', 'Hasta que llegó su hora', 'Hasta que llegó su hora', 'C''era una volta il West', 1968, 'Sergio Leone', 'Mientras los constructores del ferrocarril avanzan imparables por el desierto de Arizona en su camino hacia el mar, Jill llega al pequeño pueblo de Flagstone con la intención de empezar una nueva vida.', '/upiek8u4rHTrOJW9B0woXe4A4h7.jpg', '/u5IhDThM1SClL4pkCUp8hOmsDQJ.jpg', 8.3, 'm69ro53XbjU', array['1001']::text[], 489, null, 'segura', null),
(871, 'movie', 'El planeta de los simios', 'El planeta de los simios', 'Planet of the Apes', 1968, 'Franklin J. Schaffner', 'George Taylor forma parte de una tripulación de astronautas a bordo de una nave espacial -en una misión de larga duración- que se estrella en un planeta desconocido y aparentemente carente de vida inteligente. Sin embargo, pronto se da cuenta de que el lugar está gobernado por una raza de simios inteligentes que esclavizan a los seres humanos, que carecen de la facultad del habla. Cuando su líder, el doctor Zaius, descubre con horror la facultad de hablar de Taylor, decide que lo mejor es exterminarlo.', '/pMLpuzyeXFsttiW0dHzJLH5FXyK.jpg', '/5t6ImiTApy90YJ2QgYOCkjeav58.jpg', 7.7, 'R4csizZgJzs', array['1001']::text[], 490, null, 'segura', null),
(753, 'movie', 'Faces', 'Rostros', 'Faces', 1968, 'John Cassavetes', 'Richard Forst, un hombre de negocios de mediana edad y casado, tiene una aventura con una joven llamada Jeannie Rapp, y acto seguido le pide el divorcio a su mujer, María. Después de que Richard se haya ido de casa para irse con Jeannie, María conoce a un tipo en un bar y pasa la noche con él. A la mañana siguiente, Richard vuelve a su casa...', '/jWxJaFkn2qUblUKniC0yUqIzvso.jpg', '/wVpZAFqzcXKlHw3Dx85EpnG9vvW.jpg', 7.1, 'l_53iJ6JF68', array['1001']::text[], 491, null, 'segura', null),
(805, 'movie', 'La semilla del diablo', 'La semilla del diablo', 'Rosemary''s Baby', 1968, 'Roman Polanski', 'Una joven pareja, Rosemary y Guy, se muda a un infame edificio de apartamentos de Nueva York, conocido por aterradoras leyendas y misteriosos sucesos, con el propósito de formar una familia.', '/1PbbUmtP8SnGRCTvTzqfj5aj0xK.jpg', '/qszuXKhzYR24oRpsmh7eZaPbvL8.jpg', 7.8, 'pwLKIcB0zDw', array['1001']::text[], 492, null, 'segura', null),
(14794, 'movie', 'If....', 'If...', 'if....', 1968, 'Lindsay Anderson', 'En un análisis de la British Boys School, seguimos a Mick y sus amigos, en su mayoría más jóvenes, a través de una serie de indignidades y, en ocasiones, abusos a medida que se destruye cualquier sentimiento de cariño hacia estas escuelas. Cuando Mick y sus amigos se rebelan violentamente, el eslogan "De qué lado estarías" se vuelve bastante claro.', '/oqlpAGq4aXhc6ODtxBcGM1SEoIp.jpg', '/b5OqjAne0vAV08V43QvXpmlfvSg.jpg', 7.0, 'X_68miSOU78', array['1001']::text[], 494, null, 'segura', null),
(47576, 'movie', 'Memorias del subdesarrollo', 'Memorias del subdesarrollo', 'Memorias del subdesarrollo', 1968, 'Tomás Gutiérrez Alea', 'Que las contradicciones del burgués pueden reflejar como en un espejo las de la sociedad donde la burguesía ha llevado la voz cantante, lo demuestra esta historia de razonamiento e ironía. Una historia personal que hubiera sido intrascendente de no ocurrir en los vertiginosos días de la revolución, cuando todas las contradicciones se pusieron al rojo vivo. La película entrega un monólogo interior con mirada a la calle, como es la novela homónima de Edmundo Desnoes', '/xViL8NUM9E9PXA71cr5BXBlXOfs.jpg', '/mE58wQKaXb09zjrGrCVjWrkp7Xn.jpg', 7.2, 'FGcBNmiCdxw', array['1001']::text[], 495, null, 'segura', null),
(85535, 'movie', 'David Holzman''s Diary', 'David Holzman''s Diary', 'David Holzman''s Diary', 1967, 'Jim McBride', 'A young filmmaker decides to make a movie about his day-to-day activities in an attempt to understand himself and get his life back in order. A precursor to reality television and vlogs.', '/6CeyRNT2jkVlpzTtQ4SJEicjobL.jpg', '/a3UT5vKGoCmOTukXXK4ImolOr5K.jpg', 6.4, 'vPI1UDBZGS4', array['1001']::text[], 496, null, 'segura', null),
(30197, 'movie', 'Los productores', 'Los productores', 'The Producers', 1968, 'Mel Brooks', 'Un productor de Broadway, que está en la ruina, y un contable organizan un plan que consiste en estafar a varias ancianas con el fin de recaudar fondos para financiar una pésima obra musical. El inevitable fracaso de la obra les permitiría quedarse con todo el dinero', '/aDQbEv2f3obMNv1JGA355yB9r4i.jpg', '/hQPDNRs6Zvt1pwss7DSu5Cihtim.jpg', 7.1, 'Lt19Wna_sG4', array['1001']::text[], 496, null, 'segura', null),
(26372, 'movie', 'La vergüenza', 'La vergüenza', 'Skammen', 1968, 'Ingmar Bergman', 'Huyendo de la guerra civil que asola su país, Jan y Eva Rosenberg, dos músicos, se van a vivir a una isla, completamente apartados del mundo. Llevan una vida sencilla y apacible, preocupados únicamente por la música. Hasta que un día llegan unos soldados y todo cambia radicalmente. La pareja es arrestada bajo la acusación de colaborar con las fuerzas rebeldes. Al frente de la unidad militar que tiene la misión de defender la isla está el coronel Jacobi, un antiguo amigo de Jan y Eva. Pero esto no hará más que empeorar la situación. Con ciega brutalidad, la guerra sigue su curso con su cortejo de incendios de napalm, de sumarias ejecuciones, de redadas, de torturas.', '/nKiBFmkyN5xOIbHZ1tObeZtWXsp.jpg', '/mq8Vguqv4GjHfpSVIWFkIsOS6YK.jpg', 7.5, 'aTUIajGQLD8', array['1001']::text[], 497, null, 'segura', null),
(62, 'movie', '2001: Odisea del espacio', '2001. Una odisea del espacio', '2001: A Space Odyssey', 1968, 'Stanley Kubrick', 'De los primeros homínidos a una misión a Júpiter, un monolito misterioso marca los saltos de la humanidad. A bordo de la nave, la computadora HAL empieza a comportarse de forma extraña.', '/pGabanxaE2YvN4jhZuSN3oXO0mi.jpg', '/w5IDXtifKntw0ajv2co7jFlTQDM.jpg', 8.0, 'Z2UWOeBcsJI', array['1001','clasicos']::text[], 498, null, 'segura', null),
(18333, 'movie', 'La hora del lobo', 'La hora del lobo', 'Vargtimmen', 1968, 'Ingmar Bergman', 'En una isla viven los Borg: Johan, que es pintor, y su mujer Alma. Sus vecinos, los siniestros Von Merken, poseen un círculo de amistades tan escalofriante que Johan comienza a obsesionarse con la idea de que los demonios lo acechan...', '/a43K9rRarCXdTkK2f5smXiA80oT.jpg', '/pEHxojfy6EGOZ3e7TU9lREpWvNN.jpg', 7.4, 'DXk6VXs6jh4', array['1001']::text[], 500, null, 'segura', null),
(19383, 'movie', 'El héroe anda suelto', 'El héroe anda suelto', 'Targets', 1968, 'Peter Bogdanovich', 'Cuando el viejo actor Byron Orlock comprueba que la vida real supera con creces la violencia de sus películas de terror, decide abandonar el cine. Sin embargo, el joven y ambicioso director Sammy Michaels lo convence para interpretar un último papel, muy distinto a los habituales. Mientras tanto, un veterano del Vietnam, que había sido siempre un hombre amable y cordial, empieza a sentir una enfermiza fascinación por las armas. En un arrebato de locura dispara y mata a su mujer, a su madre y a todo el que se cruza en su camino. Acosado por la policía, se refugia en el cine donde se estrena la última película de Orlock, que se encuentra allí para despedirse definitivamente del público. El monstruo cinematográfico tendrá que enfrentarse al monstruo real.', '/y30Lv7pZU5OzZ8I69k1kUhBX4aZ.jpg', '/4BWKgipcFzDOZQPDZtmKGZVhEoU.jpg', 7.1, '2ZY0ZC9d6Tc', array['1001']::text[], 501, null, 'segura', null),
(10331, 'movie', 'La noche de los muertos vivientes', 'La noche de los muertos vivientes', 'Night of the Living Dead', 1968, 'George A. Romero', 'Las radiaciones procedentes de un satélite provocan un fenómeno terrorífico: los muertos salen de sus tumbas y atacan a los hombres para alimentarse. La acción comienza en un cementerio de Pennsylvania, donde Barbara, después de ser atacada por un muerto viviente, huye hacia una granja. Allí también se ha refugiado Ben. Ambos construirán barricadas para defenderse de una multitud de despiadados zombies que sólo pueden ser vencidos con un golpe en la cabeza.', '/5cjDlHqfb6CJV9gUcAcSp7jlEs4.jpg', '/5KtmBSqFtHY3I9t8lgH27Mc0bqY.jpg', 7.6, 'IJrGIN8UXXg', array['1001']::text[], 502, null, 'segura', null),
(88591, 'movie', 'Lucía', 'Lucía', 'Lucía', 1968, 'Humberto Solás', 'Lucía narra tres episodios diferentes de la historia cubana vistos a través de tres mujeres diferentes que coinciden en el nombre (Lucía), Los tres períodos históricos son: la guerra de Cuba por la Independencia de España, la década de 1930 y la década de 1960.', '/8P1upK1vmZeNdXPLm2gXZH6f2sr.jpg', '/bLgWv6cux1SUYB0HO676buFqRbE.jpg', 6.4, 'SZhsPBV2A1Y', array['1001']::text[], 504, null, 'segura', null),
(48831, 'movie', 'Mi noche con Maud', 'Mi noche con Maud', 'Ma nuit chez Maud', 1969, 'Éric Rohmer', 'Jean-Louis, un ingeniero católico de treinta años, descubre un día a la salida de misa a Françoise, una mujer rubia, y presiente que algún día se casará con ella, pero la pierde entre la multitud. Por otra parte, su viejo amigo Vidal, marxista convencido, lo lleva a casa de Maud, una bella divorciada.', '/nNGvvZqCgCdDmTocWiINQxx5SrC.jpg', '/zNMMKmyZ2W5viK2iqbsRfaQIa2u.jpg', 7.6, 'FD7ONauhqsg', array['1001']::text[], 504, null, 'segura', null),
(44154, 'movie', 'Un toque de Zen (Hsia nu)', 'A Touch of Zen', '俠女', 1970, '胡金銓', 'Un clásico del cine de artes marciales. El protagonista vive alegre y humildemente en un pequeño pueblo junto a su madre, componiendo poemas, escribiendo cartas y haciendo retratos. Un día, una joven se traslada a vivir al edificio que está junto al suyo, abandonado y que tiene fama de estar encantado. Aunque se siente atraído por ella, su llegada también supone el inicio de sus problemas, al verse involucrado en intrigas políticas.', '/lAYeZ2IJXwWbH02Z6Lx1bhpgqOv.jpg', '/8Owq1pLkjT7YiKahStSh8VIKU6C.jpg', 7.6, 'ccYoSiMHYUM', array['1001']::text[], 505, null, 'probable', '[{"tmdb_id": 44154, "titulo": "A Touch of Zen", "original": "俠女", "anio": 1970, "votos": 239, "poster_path": "/lAYeZ2IJXwWbH02Z6Lx1bhpgqOv.jpg", "sim": 0.615}]'::jsonb),
(642, 'movie', 'Dos hombres y un destino', 'Dos hombres y un destino', 'Butch Cassidy and the Sundance Kid', 1969, 'George Roy Hill', 'Un grupo de jóvenes pistoleros se dedica a asaltar los bancos del estado de Wyoming y el tren-correo de la Union Pacific. El jefe de la banda es el carismático Butch Cassidy, y Sundance Kid es su inseparable compañero. Un día, después de un atraco, el grupo se disuelve. Será entonces cuando Butch, Sundance y una joven maestra de Denver formen un trío de románticos forajidos que, huyendo de la ley, llegan hasta Bolivia.', '/2w6Ik8P1E20KOH5ykQlfTjawAIf.jpg', '/C6jcUqld8M6hZQmzBxgwHuQ4qT.jpg', 7.6, 'YdJW2UxvSFQ', array['1001']::text[], 506, null, 'segura', null),
(3116, 'movie', 'Cowboy de medianoche', 'Cowboy de medianoche', 'Midnight Cowboy', 1969, 'John Schlesinger', 'Soñando con una vida como cowboy de exhibición, el joven e ingenuo tejano Joe Buck se encamina hacia la ciudad de Nueva York para convertirse en un gigoló, pero pronto descubre que ese mundo no es como él se imaginaba. Sin dinero y sin amigos, conoce a Rico "Ratso" Rizzo, un timador que le quiere estafar.', '/czwhpcAa17QqUextesRPp9YFKLC.jpg', '/wY04PHkTBqdlaEbsDj6cchfRL98.jpg', 7.5, 'o29GST0Lj28', array['1001']::text[], 507, null, 'segura', null),
(11163, 'movie', 'Satyricon', 'Satiricón', 'Fellini – satyricon', 1969, 'Federico Fellini', 'En la Roma del siglo primero después de Cristo, dos estudiantes, Encolpio y Ascilto, discuten sobre su propiedad sobre el adolescente Gitone. El niño escoge a Ascilto. Sólo un terremoto salva a Encolpio del suicidio. A partir de entonces, Ascilto vivirá una serie de aventuras y desventuras para conocer nuevos amores.', '/mWAUPd3FRAAbmytfSplZ6a8b5oS.jpg', '/kPdvXDdXIbuKKAt9gEy13FNYgbm.jpg', 6.7, '8i9Z7r8dAFo', array['1001']::text[], 508, null, 'probable', '[{"tmdb_id": 11163, "titulo": "Satyricon", "original": "Fellini – satyricon", "anio": 1969, "votos": 373, "poster_path": "/83urUMl04GtwuuGIFpezqzi7n6m.jpg", "sim": 1.0}, {"tmdb_id": 281783, "titulo": "Satyricon", "original": "Satyricon", "anio": 1969, "votos": 31, "poster_path": "/6p9TWSnP1Ydx7UDHUPTTHpinQDR.jpg", "sim": 1.0}]'::jsonb),
(2721, 'movie', 'Z', 'Z', 'Z', 1969, 'Costa Gavras', 'En un país regido por una corrupta democracia, donde el gobierno utiliza a la Policía y al Ejército para erradicar cualquier amenaza izquierdista, un diputado de la oposición es asesinado en plena calle cuando acababa de presidir un mitin de carácter pacifista. De la investigación del caso se encarga un joven magistrado consciente de que se trata de un crimen político cometido por dos sicarios a sueldo. Al mismo tiempo, un ambicioso periodista se servirá de métodos poco ortodoxos para acumular pruebas que inculpen a varios militantes de un partido de extrema derecha, los cuales, a su vez, atribuyen la responsabilidad del atentado a altos cargos de la policía y del ejército.', '/ecsJAiMViUkFdeJ9sRzzxiCt7fa.jpg', '/ofSyquvDw78bpOmDAwisAfQoBYQ.jpg', 7.8, '7E3QUHUMe5I', array['1001']::text[], 510, null, 'segura', null),
(8416, 'movie', 'El conformista', 'El conformista', 'Il conformista', 1971, 'Bernardo Bertolucci', 'Cuando tenía trece años, Marcello Clerici le disparó a Lino, un adulto homosexual que intentó seducirlo. Años más tarde, Clerici es un ciudadano respetable, profesor de filosofía y va a casarse con Giulia. Pero ideológicamente Clerici es fascista, tiene contactos con el servicio secreto y se muestra dispuesto a combinar su luna de miel en París con un atentado contra un exiliado político italiano que había sido profesor suyo.', '/1fOtsLKzGAWJA41NmhRB9yNk0z1.jpg', '/xKhnjQA5wrAUaopEKegdKD3Yi26.jpg', 7.6, '04kMeEjVGIk', array['1001']::text[], 511, null, 'segura', null),
(624, 'movie', 'Buscando mi destino', 'Easy Rider (Buscando mi destino)', 'Easy Rider', 1969, 'Dennis Hopper', 'Dos jóvenes motoristas de Los Ángeles emprenden un viaje hacia Nueva Orleáns. Cruzan todo el país con la intención de descubrir América. Después de vender cocaína a un hombre de Los Ángeles, Billy y Wiatt (alias Capitán América) asisten a la fiesta del Mardî Gras. Pronto reanudan el viaje y se van encontrando con personajes de lo más estrafalario, entre ellos un ranchero y su familia, o un autoestopista de una comuna hippie, antes de ser arrestados en un pueblecito por parar sin un permiso. Su compañero de celda, un abogado borracho, les hace un gran favor sacándoles de la cárcel y luego decide unirse a ellos.', '/aj7TJr1A2QzlAjx5fBxM4NLSObE.jpg', '/qvTmYyYsv71qTq5syAq24k1kGk.jpg', 7.0, 'IlfpTppsR0U', array['1001']::text[], 512, null, 'segura', null),
(60315, 'movie', 'High School', 'High School', 'High School', 1969, 'Frederick Wiseman', 'El documentalista Frederick Wiseman nos lleva dentro de Northeast High School como una mosca en la pared para observar a los maestros y cómo interactúan con los estudiantes', '/d3R2ELJJJtsdC722O63BVLmcxSe.jpg', '/kqApyWGEEbO45HbOBMQN5T4K5aa.jpg', 7.2, 'H7CjJuEBats', array['1001']::text[], 514, null, 'segura', null),
(63951, 'movie', 'In the Year of the Pig', 'In the Year of the Pig', 'In the Year of the Pig', 1969, 'Emile de Antonio', 'Aclamado documental sobre la intervención norteamericana en Vietnam, producido en el pleno apogeo del conflicto bélico. Hace un análisis del conflicto, y cuenta con numerosas entrevistas a políticos, militares y periodistas. Fue nominado al Oscar al mejor documental.', '/iXAeDRmDguZAl2QxaHv1YQ7G1u6.jpg', '/xERm1ZTUJPzd07D01nh4UQciWaf.jpg', 7.1, null, array['1001']::text[], 515, null, 'segura', null),
(576, 'movie', 'Grupo salvaje', 'Grupo salvaje', 'The Wild Bunch', 1969, 'Sam Peckinpah', 'Un grupo de veteranos atracadores de bancos, desarraigados ladrones que viven al margen de la ley y que actúan en la frontera entre los Estados Unidos y México, se ven acorralados por unos cazadores de recompensas y el ejército mexicano.', '/8RLSKxIbW10kFKJirxVYDwwmDAl.jpg', '/nkgWcfOeQnVnxak5xCKvkRDLt5H.jpg', 7.6, 'kdy0t_8mQBw', array['1001']::text[], 516, null, 'segura', null),
(895, 'movie', 'Andrei Rublev', 'Andrei Rublev', 'Андрей Рублёв', 1966, 'Andréi Tarkovski', 'A comienzos del siglo XV, el monje pintor Andrei Rublev acude junto con sus compañeros a Moscú para pintar los frescos de la catedral de la Asunción del Kremlin. Fuera del aislamiento de su celda, Rublev comenzará a percatarse de las torturas, crímenes y matanzas que tienen aterrorizado al pueblo ruso… La biografía del pintor ruso Andrei Rublev, famoso por sus iconos, sirve de base para hacer un minucioso retrato de la vida social, política y artística en la Rusia de principios del siglo XV.', '/3aodTV8q8iIRtaw9dxeU8DuKlta.jpg', '/jqha8JCXm0aJ5SJ03Jd0JmGgWRs.jpg', 7.9, 't1d5FSyMEd8', array['1001']::text[], 518, null, 'dudosa', '[{"tmdb_id": 895, "titulo": "Andrei Rublev", "original": "Андрей Рублёв", "anio": 1966, "votos": 993, "poster_path": "/3aodTV8q8iIRtaw9dxeU8DuKlta.jpg", "sim": 1.0}, {"tmdb_id": 1691470, "titulo": "Inventing \"Andrei Rublev\"", "original": "Inventing \"Andrei Rublev\"", "anio": 2018, "votos": 0, "poster_path": null, "sim": 0.722}, {"tmdb_id": 553222, "titulo": "Tarkovsky''s Andrei Rublev: A Journey", "original": "Tarkovsky''s Andrei Rublev: A Journey", "anio": 2018, "votos": 0, "poster_path": "/2gbZVA5HX9wYnmxoYFzrIJO6gVb.jpg", "sim": 0.542}]'::jsonb),
(2912, 'movie', 'El carnicero', 'El carnicero', 'Le Boucher', 1970, 'Claude Chabrol', 'La extraña amistad entre un carnicero de clase baja y una profesora de escuela reprimida coincide con una serie de asesinatos espeluznantes en un pueblo francés', '/7GBunEbS4AbYVl2hyB3TLrfciHg.jpg', '/8cyxP51631Pfi2yMfYafkcg7y7u.jpg', 7.1, '0B-mGbuengI', array['1001']::text[], 519, null, 'segura', null),
(26302, 'movie', 'El color de las granadas (Sayat nova)', 'El color de la granada', 'Նռան գույնը', 1969, 'სერგო ფარაჯანოვი', 'Biografía del trovador y poeta armenio del siglo XVIII Sayat Nova. En lugar de hacer una narración lineal, el director se encarga de realizar una serie de cuadros vivientes que representan episodios importantes de la vida del poeta en clave simbólica: su infancia, su juventud, su entrada a un monasterio, o su enfrentamiento con el ángel de la muerte. Estos capítulos están desarrollados a partir de fragmentos de sus obras, los cuales aparecen en intertítulos o se escuchan mediante una voz en off.', '/aMIEEeLrCevG094Z2u82S0lxJPq.jpg', '/7ryDL1g6FNHMFdXmmmFGZZpEh0a.jpg', 7.3, 'RsrUqqnPA3Q', array['1001']::text[], 520, null, 'segura', null),
(13384, 'movie', 'Kes', 'Kes', 'Kes', 1970, 'Ken Loach', 'Billy Casper es un muchacho de aspecto triste que vive en un pequeño pueblo minero de condado de Yorkshire. No va bien en la escuela y comete pequeños hurtos que le reportan algo de dinero. Un buen día, encuentra un pequeño halcón y, lleno de entusiasmo, decide cuidarlo hasta que consiga volar.', '/2ZbMpeIwkPcMEoR7CxpTZcNgu9e.jpg', '/eWvxOS5g67B1b46Cff9TlYuJleY.jpg', 7.4, 'JTZwKbJgoDk', array['1001']::text[], 521, null, 'segura', null),
(35838, 'movie', 'Tristana', 'Tristana', 'Tristana', 1970, 'Luis Buñuel', 'Don Lope ha acogido a Tristana en su hogar para cumplir una promesa hecha a sus padres. Pero la joven es muy hermosa y se convierte en la obsesión del anciano, que a fuerza de tiempo y de paciencia consigue sus favores. Sin embargo, cuando ella conoce a un joven pintor que la enamora, decide cambiar radicalmente el rumbo de su vida', '/uziTHMqLARpnSEdi1QtdlX9hR8n.jpg', '/rAJEXUzsWRuM5zcmiWs2b10AZTC.jpg', 7.2, 'HJSRcBb8gb4', array['1001']::text[], 521, null, 'segura', null),
(26617, 'movie', 'Mi vida es mi vida', 'Mi vida es mi vida', 'Five Easy Pieces', 1970, 'Bob Rafelson', 'Robert Dupea, que fue un niño prodigio como pianista, trabaja en unas explotaciones petrolíferas. Cuando vuelve a ver a su hermana, convertida en una famosa pianista, decide volver a sus orígenes y al camino que abandonó.', '/gsEPayncbQETdSG3DPHivtATNhg.jpg', '/y7pnEmBotaowRY0o8V33r4JuRNS.jpg', 7.1, 'VkcXtLz-BaM', array['1001']::text[], 522, null, 'segura', null),
(13041, 'movie', 'El Topo', 'El Topo', 'El Topo', 1970, 'Alejandro Jodorowsky', 'En un Oeste imaginario, el pistolero Topo se enfrenta a una banda de fetichistas, dirigida por un coronel lascivo, que tiene atemorizada a una congregación franciscana. Singular y provocativa película de culto, mezcla de géneros y movimientos culturales. John Lennon dijo de ella que era una obra maestra.', '/aD88hcVUoTPcx6wGzb5jtm9mgTe.jpg', '/xkfXO0Zswvvlbs0FlxH3TA4qji3.jpg', 7.0, 'xjTlNTbv-xs', array['1001']::text[], 523, null, 'segura', null),
(9459, 'movie', 'Woodstock', 'Woodstock, 3 días de paz y música', 'Woodstock', 1970, 'Michael Wadleigh', 'Documental sobre el famoso festival de Woodstock que tuvo lugar en Bethel, NY. En agosto de 1969, 450.000 personas asistieron al mayor festival de música rock hasta la fecha. "Woodstock", ganadora del Oscar de la Academia, fue un acontecimiento que dio nombre a una generación y marcó a toda una época. "Woodstock, 3 días de paz y música: el montaje del director" (Woodstock - 3 Days of Peace &amp; Music: The Director''s Cut) de 225 minutos de duración, cuenta con imágenes restauradas y con sonido digital. Además, ofrece 40 minutos adicionales de imágenes nunca vistas en la película inicial, que fueron integradas en el film por el propio director Michael Wadleigh. Un joven Martin Scorsese fue asistente del director y ayudó en el montaje de este aclamado e histórico documental. (FILMAFFINITY)', '/AapH8Qx4kUZoO7F4aK5cUnHjtdg.jpg', '/50tOx2lJXuszVjwCjNYHEXnPMWx.jpg', 7.6, 'aGtRcLlfqN8', array['1001']::text[], 524, null, 'segura', null),
(59408, 'movie', 'Deep End', 'Deep end', 'Deep End', 1971, 'Jerzy Skolimowski', 'Londres, Inglaterra. Mike, un chico de quince años, consigue trabajo en una casa de baños, donde conoce a Susan, una atractiva joven que trabaja allí como encargada.', '/8pZxUJTgjerjxuifSU13B8pXAJB.jpg', '/zZ0bs8rPbd0FppyJq5ukaATh745.jpg', 7.0, 'I3qpEzHmZAA', array['1001']::text[], 526, null, 'segura', null),
(42595, 'movie', 'La estrategia de la araña', 'La estrategia de la araña', 'Strategia del ragno', 1970, 'Bernardo Bertolucci', 'Un joven regresa a la ciudad donde su padre fue asesinado antes de que él naciera. El muchacho trata de encontrar una explicación a la muerte de su padre a manos de un fascista en 1936. Pero la verdad se revela compleja como una tela de araña. (FILMAFFINITY)', '/qxg1zB70olHgLuZPemVGYKBfwu8.jpg', '/teD2odnlfZUyAoSgxtzkZrR4UXG.jpg', 7.1, null, array['1001']::text[], 526, null, 'segura', null),
(11040, 'movie', 'Pequeño gran hombre', 'Pequeño gran hombre', 'Little Big Man', 1970, 'Arthur Penn', 'Poco convencional western que relata de forma retrospectiva (flash-back), las múltiples aventuras y peripecias vividas en el salvaje Oeste por Jack Crabbe, un anciano de 121 años que sobrevivió al general Custer y a la época de las guerras contra los indios.', '/6JrDqq9qFHaDpBuaCipQS75rlux.jpg', '/7l4Z3umguBXqBeleGNhFJwCF2b4.jpg', 7.4, '-2DWY63CVlk', array['1001']::text[], 527, null, 'segura', null),
(1064567, 'movie', 'La oreja (Ucho)', 'Kým sa ucho neodbije', 'Kým sa ucho neodbije', 1972, 'Jaroslava Havettová', 'Art-naive gallery of craft guilds of Haban ceramics in Slovakia.', null, null, null, null, array['1001']::text[], 528, null, 'dudosa', '[{"tmdb_id": 1064567, "titulo": "Kým sa ucho neodbije", "original": "Kým sa ucho neodbije", "anio": 1972, "votos": 0, "poster_path": null, "sim": 0.333}]'::jsonb),
(651, 'movie', 'M*A*S*H', 'M.A.S.H.', 'M*A*S*H', 1970, 'Robert Altman', 'M.A.S.H. narra las aventuras de dos cirujanos del ejército destinados a una unidad móvil médica en Corea durante la guerra. Tanto ellos como su equipo de enfermeras se toman el trabajo muy en serio pero, en su tiempo libre, las bromas constantes y la ironía hacen más llevadera la situación.', '/xteeXKr4FpusQGzT9NUfhFqeEoI.jpg', '/3YWL6rZmvZxCQw2qEwxPGrqhYku.jpg', 6.9, 'NJ6quIFtbXs', array['1001']::text[], 530, null, 'segura', null),
(11202, 'movie', 'Patton', 'Patton', 'Patton', 1970, 'Franklin J. Schaffner', 'Biografía del general norteamericano George S. Patton, quien, tras vencer al mariscal alemán Rommel en el norte de África, condujo a sus tropas de manera imparable a través de Europa.', '/1jCaXkBMi9onVxeqqN9v7kovp3u.jpg', '/txXPooNu7fr4YhLwx7AlXkU0PnN.jpg', 7.4, 'bLXzqSmxGaM', array['1001']::text[], 530, null, 'segura', null),
(26606, 'movie', 'Performance', 'Performance.', 'Performance.', 1970, 'Nicolas Roeg, Donald Cammell', 'Debut de Roeg en un thriller ambientado en el mundo de la música pop. Chas es un performer de la mafia, un matón a sueldo que aplica curiosas y artísticas torturas a sus víctimas. Cuando surge un problema con su capo, se ve obligado a huir, y decide esconderse en el sótano de una antigua casa de un suburbio de Londres. El casero, una ex estrella de rock llamada Turner (interpretado por Mick Jagger), vive con dos mujeres con las que forma un trío, y se pasa el día comiendo setas alucinógenas e improvisando con la guitarra. Al principio, Chas y Turner chocan, pero poco a poco, en un viaje de conocimiento mutuo, se darán cuenta de que ambos son performers y que tan sólo una delgada línea les separa.', '/yKuqk84TtTpj0nYZS5m680JmprG.jpg', '/u6twkjIhNbNynmWWHrCZ5BZpfNI.jpg', 6.8, 'JyamwoLSqTI', array['1001']::text[], 531, null, 'segura', null),
(132, 'movie', 'Gimme Shelter', 'Gimme Shelter', 'Gimme Shelter', 1970, 'Albert Maysles, David Maysles, Charlotte Zwerin', 'Una detallada crónica de la famosa gira que el grupo de rock británico The Rolling Stones realizó por los Estados Unidos en 1969, que culminó con el desastroso y trágico concierto celebrado el 6 de diciembre en el Altamont Speedway Free Festival, un evento de trascendencia histórica, pues marcó el final de una era: la generación de la paz y el amor se convirtió de golpe en la generación del desengaño.', '/pOl3fD0eThtHXCK8OSwvsbh6lqO.jpg', '/c4Chm8w7AsekIkPb6KSxUxCzXq2.jpg', 7.4, 'x7UsBmavjsE', array['1001']::text[], 532, null, 'segura', null),
(20345, 'movie', 'El pájaro de las plumas de cristal', 'El pájaro de las plumas de cristal', 'L''uccello dalle piume di cristallo', 1970, 'Dario Argento', 'Sam Dalmas, un joven escritor americano, está a punto de marcharse de Roma para volver a Estados Unidos. La noche antes de su marcha asiste a la agresión de Monica Ranieri: alguien la apuñala y desaparece en la oscuridad. El comisario Morosini es encargado de la investigación e informa a Sam de la posible presencia de un asesino en serie en la ciudad: la misma persona que ya ha matado con arma blanca a tres chicas podría haber intentado apuñalar a Monica. Sam decide aplazar su marcha e investigar por su cuenta…', '/xSZdOoF2NSkjnW73DxbX50VBoZq.jpg', '/jCh4lxFGREOf3JHDxxnlbWv2xWq.jpg', 7.1, 'UztVF1nJTBo', array['1001']::text[], 533, null, 'segura', null),
(2998, 'movie', 'Zabriskie Point', 'Zabriskie Point', 'Zabriskie Point', 1970, 'Michelangelo Antonioni', 'Tras un enfrentamiento en un campus universitario entre estudiantes y policías, un joven de familia acomodada, que ha matado a un agente, tras robar una avioneta huye con un compañero al desierto de Arizona. Allí se encuentra casualmente con una muchacha que trabaja para un abogado, que dirige un importante proyecto inmobiliario.', '/vGjItrhj1ZEN6MmOpQYKxHpWHTL.jpg', '/nLb3TOTjgvvjmHnUmlkg4Rwq9jG.jpg', 7.0, 'rhZNXDOl_eM', array['1001']::text[], 533, null, 'segura', null),
(42529, 'movie', 'Los misterios del organismo', 'Los misterios del organismo', 'W.R. - Misterije organizma', 1971, 'Dušan Makavejev', 'En 1971, en plena resaca del Mayo del 68, el cineasta yugoslavo Dusan Makavejev se convierte en el artista escandaloso del momento con esta especie de falso documental sobre sexo y política, en el que se combinan noticiarios, entrevistas, ficción y ocurrencias surrealistas varias. El guión, apenas esbozado, gira en torno a la vida y obra del psiquiatra austriaco Wilhelm Reich, descubridor de la energía orgásmica, y a las peripecias de dos jovencitas comunistas con muchas ganas de experimentar con sus respectivos y pimpantes cuerpos. Todo ello mezclado con imágenes manipuladas de Stalin, escenas de sexo explícito e incluso una sesión de electroshock real. (FILMAFFINITY)', '/aNK9tib62Pq92tdsldO0lLNZxeb.jpg', '/r2Xx2cCOjB2aRnyQCfYKgWuJ8pl.jpg', 6.2, 'ZpFR2uYeMDA', array['1001']::text[], 534, null, 'segura', null),
(80560, 'movie', 'Wanda', 'Wanda', 'Wanda', 1970, 'Barbara Loden', 'En la zona obrera de los suburbios de Pennsylvania, Wanda Goronski, una mujer con problemas, abandona a su familia y acaba sumergida en un mundo de perdición.', '/izuJ7cUhcihFnTpfsdSnkMCHsRQ.jpg', '/bL1etbhvRGhHhpjbwzHZbXNwM5R.jpg', 6.8, 'KF32MBvdy70', array['1001']::text[], 534, null, 'segura', null),
(4789, 'movie', 'El jardín de los Finzi-Contini', 'El jardín de los Finzi Contini', 'Il giardino dei Finzi Contini', 1970, 'Vittorio De Sica', 'Finales de los años treinta, Italia. Los Finzi Contini son una de las familias más influyentes de Ferrara: ricos, aristocráticos y judíos. Sus hijos, ya adultos, Micol y Alberto, tratan de crear un restringido círculo de amistades para poder jugar al tenis y celebrar fiestas, pero viven ajenos al mundo que los rodea. En ese círculo entra Giorgio, un judío de clase media que se enamora de Micol. Ella parece divertirse a su costa; incluso hace el amor con uno de sus amigos cuando sabe que Giorgio los está espiando. Al mismo tiempo que tienen lugar estos juegos sentimentales, el fascismo aprueba leyes que afectarán dramáticamente a los Finzi Contini. Drama basado en la novela homónima de Giorgio Bassani. (FILMAFFINITY)', '/KkutxbUQmBYiJ1KeYGnkmu6aap.jpg', '/bMTBDpipkszdWcY9U9lRTVy4zh9.jpg', 7.0, null, array['1001']::text[], 535, null, 'segura', null),
(185, 'movie', 'La naranja mecánica', 'La naranja mecánica', 'A Clockwork Orange', 1971, 'Stanley Kubrick', 'Alex, líder de una banda violenta en una Inglaterra futurista, es encarcelado y sometido a un tratamiento experimental para ''curarlo'' de su agresividad.', '/p40pYh2EBPoyVyqw6qy2PAZkFVA.jpg', '/nLFxvLokHe3bQmrmAfljIfax2jQ.jpg', 8.2, '2meAsIclTzQ', array['1001','clasicos']::text[], 536, null, 'segura', null),
(1262519, 'movie', 'Le Chagrin et la pitié', '« Le Chagrin et la Pitié » : La France de Vichy dynamitée', '« Le Chagrin et la Pitié » : La France de Vichy dynamitée', 2024, 'Joseph Beauregard', 'The story of the documentary The Sorrow and the Pity (1971), directed by Marcel Ophüls, which caused a scandal in a France still traumatized by the German occupation during World War II, because it shattered the myth, cultivated by the followers of President Charles de Gaulle (1890-1970), of a united France that had supposedly stood firm in the face of the ruthless invaders.', '/7p40g2cAoOkZGRearlX7ImTUKHx.jpg', '/lLzJ2tNrHViyQl9WCPlFIp41SD4.jpg', 8.0, null, array['1001']::text[], 538, null, 'dudosa', '[{"tmdb_id": 1262519, "titulo": "« Le Chagrin et la Pitié » : La France de Vichy dynamitée", "original": "« Le Chagrin et la Pitié » : La France de Vichy dynamitée", "anio": 2024, "votos": 5, "poster_path": "/7p40g2cAoOkZGRearlX7ImTUKHx.jpg", "sim": 0.567}]'::jsonb),
(252, 'movie', 'Un mundo de fantasía', 'Un mundo de fantasía', 'Willy Wonka & the Chocolate Factory', 1971, 'Mel Stuart', 'Willy Wonka es el excéntrico dueño de una gran fábrica de chocolate. Un día decide ofrecer a cinco niños una entrada dorada que les permitirá recorrer la dulce fábrica. Uno de los ganadores es Charlie Bucket, un niño pobre de buen corazón que espera un futuro mejor para él, para su madre y sus cuatro abuelos. Los otros ganadores resultan ser cuatro insoportables niños.', '/liuz3OF2Vu2C3u2xPKlArlVkLzX.jpg', '/ko7hMSCtXoJFfpYAIbrowwgH0eq.jpg', 7.5, '2WKPKnggJqk', array['1001']::text[], 538, null, 'segura', null),
(29005, 'movie', 'Los vividores', 'Los vividores', 'McCabe & Mrs. Miller', 1971, 'Robert Altman', 'A principios del siglo XX, John McCabe, un hombre con un misterioso pasado, llega a Presbyterian Church, frío y solitario pueblo del Noroeste de Estados Unidos. Allí monta el primer prostíbulo de la ciudad, que consiste en una serie de viejas tiendas de campaña. Tiempo después, Constance Miller, madame del burdel, una inteligente mujer con mucho mundo, transforma el negocio de McCabe, en uno de los más famosos y prósperos de toda la región...', '/pSBoPqIWaUNZB98JEWnCutyy0QR.jpg', '/zaZVjkAwPsaBTsoyJMPWqnsPOM5.jpg', 7.2, 'Xkr5p0XCaUQ', array['1001']::text[], 539, null, 'segura', null),
(36040, 'movie', 'Walkabout', 'Walkabout', 'Walkabout', 1971, 'Nicolas Roeg', 'Dos niños vagan por el desierto australiano, abandonados a su suerte, tras haberse suicidado su padre. Allí conocerán a un aborigen.', '/24vooYt5StgtgcQObVr1GHuM5gy.jpg', '/uA5GfPzRU1vRVY7pDfqXQmjRTPI.jpg', 7.3, 'Fdqwbs8uKwQ', array['1001']::text[], 540, null, 'segura', null),
(466, 'movie', 'Klute', 'Klute', 'Klute', 1971, 'Alan J. Pakula', 'En Nueva York, un hombre ha desaparecido sin dejar rastro. Klute (Donald Sutherland), un policía íntimo amigo suyo, encuentra una pista en las cartas que aquél le escribía a una prostituta llamada Bree (Jane Fonda). Va a verla para interrogarla y surge entre ellos una apasionada relación amorosa. Mientras Klute prosigue sus investigaciones en los bajos fondos, empiezan a aparecer prostitutas asesinadas; entonces le asalta la sospecha de que Bree pueda ser la próxima víctima.', '/zjy0vxp3YMU6rFRxZxEuZbxLeyX.jpg', '/bxh7ybql4p24u9WsX1GI9v9PDLg.jpg', 6.8, '3S4rxnjwFDg', array['1001']::text[], 541, null, 'segura', null),
(343, 'movie', 'Harold y Maude', 'Harold y Maude', 'Harold and Maude', 1971, 'Hal Ashby', 'Comedia negra que relata la historia de un joven de buena familia obsesionado con la muerte, hasta el punto de que su pasatiempo favorito es probar diferentes métodos de suicidio. Obtuvo excelentes críticas.', '/tEXdC1RB0xWU9t5TffvHs7SctnZ.jpg', '/jKgfnnCATAg4fxMfS0LZThmqOZB.jpg', 7.6, 'u-cOukYeGVM', array['1001']::text[], 542, null, 'segura', null),
(1485, 'movie', 'Asesino implacable', 'Asesino implacable', 'Get Carter', 1971, 'Mike Hodges', 'Cuando a Jack Carter le comunican la muerte de su hermano, se niega a aceptar la versión de la policía y decide investigar por su cuenta y vengar la muerte de su hermano.', '/d41oM8IPJjakqEmqcG3pXAQ11Hy.jpg', '/q7WBYbZ1DiirFGx1Ex11N7jKMyT.jpg', 6.9, '0NtstlDW0Zo', array['1001']::text[], 544, null, 'segura', null),
(86732, 'movie', 'Salmo rojo', 'Salmo rojo', 'Még kér a nép', 1972, 'Miklós Jancsó', 'La rebelión de los campesinos húngaros de fines del siglo XIX contra los terratenientes que los explotan, es narrada por Miklós Jancsó con un ritmo musical, que da a la obra la impronta de un ritual. Las primeras tentativas de la revuelta fallan, pero el espíritu revolucionario pronto volverá a estallar... (FILMAFFINITY)', '/zPnUnJDC26brcSpDCEit1OeSx6s.jpg', '/5f3YTZZSuIzrLja2rw2xB1pzZxM.jpg', 6.3, 'g6SysGRC7L4', array['1001']::text[], 544, null, 'segura', null),
(1051, 'movie', 'Contra el imperio de la droga', 'French Connection. Contra el imperio de la droga', 'The French Connection', 1971, 'William Friedkin', 'Jimmy Doyle y Buddy Rosso son dos policías neoyorquinos que siguen la pista de una red de traficantes de drogas. El primero, que confía en su olfato, sospecha que una confitería de Brooklyn está implicada y convence a su jefe para intervenir la línea telefónica. Poco después, Doyle y sus hombres siguen al dueño de la confitería, que los conduce hasta Nicoly y Charnier, dos franceses que acaban de llegar a Estados Unidos.', '/aLtuKxMwNksQp8v09rWOBwIHDsL.jpg', '/AsaW2VwcArvQmYjf2wsDjqWEn6f.jpg', 7.5, 'jNLH00BX1Hw', array['1001']::text[], 545, null, 'segura', null),
(482, 'movie', 'Las noches rojas de Harlem', 'Las noches rojas de Harlem (Shaft)', 'Shaft', 1971, 'Gordon Parks', 'El detective privado John Shaft recibe la visita de un policía que le pide información sobre un mafioso de Harlem llamado Bumpy. Poco después, será el mafioso quien solicita ayuda al detective para rescatar a su hija, que ha sido secuestrada por una banda rival. Shaft y un viejo amigo deciden investigar el asunto y se infiltran en el mundo del hampa para encontrar a la chica. Pero Shaft acaba averiguando que el gángster lo está utilizando.', '/nU34jJN7PqweqiE6XCZLJzycynf.jpg', '/bKHTti0HkETmAr24eUVkPWdI5kj.jpg', 6.4, 'hwrLNTN7-Fs', array['1001']::text[], 546, null, 'segura', null),
(42501, 'movie', 'El soplo en el corazón', 'Un soplo en el corazón', 'Le Souffle au cœur', 1971, 'Louis Malle', 'Francia, años 50. Laurent Chevalier es un chico de catorce años que comienza a descubrir la vida. Su padre lo ignora, su madre lo venera y sus hermanos combinan gestos de cariño con el abuso propio de los mayores. En poco tiempo, Laurent pasa de ser virgen a tener una experiencia frustrada con una prostituta y a sufrir los intentos de seducción de un cura. Cuando se le detecta un soplo al corazón, Laurent, acompañado de su madre, irá a un balneario, en el que la vida social es digna de una gran ciudad.', '/jQtcmwXLPzhX0AIW9hraZHfASBh.jpg', '/d3u97tjDhvPJjeyYMTIEfodtk9j.jpg', 7.0, null, array['1001']::text[], 547, null, 'segura', null),
(984, 'movie', 'Harry el sucio', 'Harry el sucio', 'Dirty Harry', 1971, 'Don Siegel', 'Harry Callahan es un duro policía que se ha criado en la calle. Sus compañeros le llaman Harry el Sucio por sus particulares métodos de lucha contra el crimen y porque siempre se encarga de los trabajos más desagradables. En San Francisco, un francotirador ha matado ya a dos personas. Harry será el encargado de resolver el caso.', '/gJ3VDY75PGksnba8aTOueb5Gtm4.jpg', '/mJjOZSaTTqG3an5MkkOX3x18lYX.jpg', 7.5, 'K6Vi1VurN9s', array['1001']::text[], 547, null, 'segura', null),
(5822, 'movie', 'Sweet Sweetback''s Baadasssss Song', 'Sweet Sweetback''s Baadasssss Song', 'Sweet Sweetback''s Baadasssss Song', 1971, 'Melvin Van Peebles', 'After saving a Black Panther from some racist cops, a black male prostitute goes on the run from "the man" with the help of the ghetto community and some disillusioned Hells Angels.', '/ykGkbDp1QxQTM3UUrUvowtXLI0i.jpg', '/w3HmBVzzawXuLmZzbs2jEh5TdVE.jpg', 5.1, 'aen5aQ7w4PE', array['1001']::text[], 548, null, 'segura', null),
(25188, 'movie', 'La última película', 'La última película', 'The Last Picture Show', 1971, 'Peter Bogdanovich', 'En la década de los 50, en una pequeña ciudad de Texas, un grupo de jóvenes afronta el paso de la adolescencia a la madurez dentro de una sociedad represora y cambiante en la que el cine y todo lo que representa muere en manos de la televisión.', '/gVexULn5yuHV5dfPGyjkc5VySzB.jpg', '/fhzwleXGmiqBuQdWxmEwpkydhm4.jpg', 7.6, 'NufO2KXHbKQ', array['1001']::text[], 549, null, 'segura', null),
(994, 'movie', 'Perros de paja', 'Perros de paja', 'Straw Dogs', 1971, 'Sam Peckinpah', 'El astrofísico americano David Sumner (Hoffman) se traslada a vivir al pueblo de su mujer, en Gran Bretaña. Es un hombre reservado y tímido que vive absorto en sus investigaciones y procura evitar cualquier disputa. Sin embargo, la violencia de ciertos individuos del pueblo llega a tal extremo que Sumner, situado entre la espada y la pared, reacciona con las mismas armas que sus agresores para defender a su mujer y su hogar... Obra clave en la filmografía de Peckinpah, "Perros de paja" es un estudio sobre la violencia del ser humano basado en la novela "The Siege of Trencher''s Farm", de Gordon M. Williams.', '/eUdwFTI5imeQCKEYyHfuQgYNXfn.jpg', '/8Mngxf4aE99eyDHCvGo8sfyQd9C.jpg', 7.1, '_SPJza7ZUjo', array['1001']::text[], 550, null, 'segura', null),
(27236, 'movie', 'Carretera asfaltada en dos direcciones', 'Carretera asfaltada en dos direcciones', 'Two-Lane Blacktop', 1971, 'Monte Hellman', 'Dos chicos recorren las carreteras de Estados Unidos en un polvoriento Chevrolet del 55 y compiten en carreras ilegales. Eso es lo único que les importa, ni hablan ni se divierten. Un día se cruza en su camino GTO, un peculiar conductor que los desafía. Fue un fracaso comercial, pero se convirtió en película de culto como otras road-movies de la época (“Easy Ryder”, por ejemplo).', '/8GSjw941Maq4oDvbYqbyc6UM8WH.jpg', '/tdNMIUmeCSJcLN672JNIxNFp1Zi.jpg', 7.0, 'J5sxfIBCTY0', array['1001']::text[], 551, null, 'segura', null),
(40687, 'movie', 'El rompecorazones', 'El rompecorazones', 'The Heartbreak Kid', 1972, 'Elaine May', 'Al tercer día de su luna de miel en Miami, Lenny, un judío neoyorquino, conoce a Kelly, una rubia espectacular. Se da cuenta entonces de que ha cometido un grave error al casarse, pues lo único que desea es estar con Kelly.', '/utyz3zOw2drHOeitwuiNx8SbsMf.jpg', '/yk67t0Xl8LSW23XcjVXMlooyBlu.jpg', 6.7, '5ytlIXSl9GI', array['1001']::text[], 551, null, 'segura', null),
(2000, 'movie', 'Aguirre, la cólera de Dios', 'Aguirre, la cólera de Dios', 'Aguirre, der Zorn Gottes', 1972, 'Werner Herzog', 'En 1560, poco después de la destrucción del imperio inca, una expedición española parte de las montañas de Perú rumbo a las selvas del Amazonas, en busca de la legendaria tierra de El Dorado. A través del diario del fraile Diego Gaspar de Carvajal iremos conociendo detalles y circunstancias de aquella peligrosa aventura...', '/nNGXrwLQDHxaZM6heLIHZOM3Gfl.jpg', '/kfSZaOr9ApNR52gWKlpXHD0id0W.jpg', 7.4, 'eJDuicFyJPg', array['1001']::text[], 552, null, 'segura', null),
(10784, 'movie', 'Cabaret', 'Cabaret', 'Cabaret', 1972, 'Bob Fosse', 'Berlín, años 30, en plena República de Weimar y antes de la Segunda Guerra Mundial. A pesar de la crisis del momento, los berlineses prefieren vivir la magia que les ofrece cada noche un cabaret cuya estrella es Sally, una bailarina y cantante que se enamorará de dos hombres muy diferentes entre sí.', '/5l7V58hgBEPZDQGFw162oJV9d3q.jpg', '/yInvVRrCmEypIt5hm0WvXkjxsQX.jpg', 7.4, '6DZ2wtichOM', array['1001']::text[], 553, null, 'segura', null),
(1643, 'movie', 'El último tango en París', 'El último tango en París', 'Ultimo tango a Parigi', 1972, 'Bernardo Bertolucci', 'Una mañana de invierno un hombre y una muchacha se encuentran casualmente mientras visitan un piso de alquiler en París. La pasión se apodera de ellos y hacen el amor violentamente en el piso vacío. Cuando abandonan el edificio, se ponen de acuerdo para volver a encontrarse allí, en soledad, sin preguntarse ni siquiera sus nombres.', '/2G1j1RWBvmWc8f0HXjRZnn0ZlgD.jpg', '/hExTiLbfB93HwEwkeQxb3q4nHtQ.jpg', 6.9, '_0Vj-B6JVmQ', array['1001']::text[], 553, null, 'segura', null),
(11901, 'movie', 'Infierno de cobardes', 'Infierno de cobardes', 'High Plains Drifter', 1973, 'Clint Eastwood', 'En 1870 un Forastero pasa a caballo ante la tumba de un antiguo Sheriff, Jim Duncan, en la ciudad fronteriza de Lago en el Sudoeste de Estados Unidos. Los propietarios de la compañía minera de Lago, Dave Drake y Morgan Allen obtienen el apoyo de los vecinos de la pequeña ciudad para contratar al Forastero. Debe proteger a la comunidad contra tres pistoleros, cuya llegada se hace inminente al haber sido liberados tras cumplir condena por acusaciones falsas de la compañía minera Drake-Allen. El Forastero acepta el contrato a condición de llevarlo a cabo con los tres forajidos y, entre otras cosas, pide que pinten el pueblo entero de color rojo vivo y que le cambien el nombre y pasa a llamarse "Infierno".', '/wjDXOhds3c0is5gGkBpxy0EjuI6.jpg', '/gDrgpDJHi0ZwH69KfMIiuBMt0Ja.jpg', 7.3, 'be2mIVxDrr8', array['1001']::text[], 554, null, 'segura', null),
(993, 'movie', 'La huella', 'La huella', 'Sleuth', 1972, 'Joseph L. Mankiewicz', 'Andrew Wyke es un prestigioso escritor de novelas de intriga. Además, su pasión por los juegos de ingenio y las adivinanzas lo ha llevado a convertir su gran mansión en una especie de museo, donde se exponen los juguetes y mecanismos más extravagantes. Una tarde, invita a su casa a Milo Tindle, amante de su mujer y propietario de una cadena de salones de belleza, para proponerle un ingenioso plan del que ambos podrían salir beneficiados.', '/vGZrvkCm0FSKvjuPnu1svE3pNls.jpg', '/rVdKBzVyHTG1gv8bAAJnr5Eu6gl.jpg', 7.7, 'G4D8Iz5IS3g', array['1001']::text[], 554, null, 'segura', null),
(10669, 'movie', 'Defensa', 'Defensa', 'Deliverance', 1972, 'John Boorman', 'Cuatro amigos que viven en la ciudad deciden pasar un fin de semana en los Montes Apalaches. Quieren bajar en canoa un río que atraviesa un bosque que pronto será inundado para la construcción de una presa. Tras una jornada placentera, el encuentro con los indígenas de la zona, convierte la excursión en una angustiosa pesadilla.', '/e1bVo5ehfvRDBh4IulHzmVXfVCh.jpg', '/aaqbyTRo1bZB34ZdjeWyqnL0qz0.jpg', 7.3, 'iuOUF1-4P3c', array['1001']::text[], 555, null, 'segura', null),
(593, 'movie', 'Solaris', 'Solaris', 'Солярис', 1972, 'Andréi Tarkovski', 'Un científico es enviado a la estación espacial de un remoto planeta cubierto de agua para investigar la misteriosa muerte de un médico. Adaptación del clásico de ciencia-ficción del escritor polaco Stanislaw Lem.', '/69J6Hplvaw5o5lfCRqFRd4nmuH7.jpg', '/jZv1u7uzpOE5JOc2MmrvPUZWoyb.jpg', 7.8, 'BBYJH6UAAfw', array['1001']::text[], 556, null, 'segura', null),
(238, 'movie', 'El padrino', 'El padrino', 'The Godfather', 1972, 'Francis Ford Coppola', 'Vito Corleone, jefe de una familia mafiosa de Nueva York, debe pasarle el poder a uno de sus hijos. Michael, el que nunca quiso ser parte del negocio, termina siendo el elegido.', '/5HlLUsmsv60cZVTzVns9ICZD6zU.jpg', '/ejdD20cdHNFAYAN2DlqPToXKyzx.jpg', 8.7, 'v72XprPxy3E', array['1001','clasicos']::text[], 558, null, 'segura', null),
(10238, 'movie', 'Gritos y susurros', 'Gritos y susurros', 'Viskningar och rop', 1972, 'Ingmar Bergman', 'Ante la proximidad de la muerte de una de ellas, tres hermanas se reúnen en la vieja mansión familiar. Una vez en la casa, comienzan a recordar el pasado, y cuando la enferma entra en la agonía desvela la parte más oscura y tortuosa de su vida.', '/sr8qYAG8JP33goQC87Ym4d16njF.jpg', '/xmLgdb0yDBXa7Dlo3aCzjhjCkuE.jpg', 7.9, 'zc8f9ZlMnTU', array['1001']::text[], 559, null, 'segura', null),
(16993, 'movie', 'Ciudad dorada', 'Fat City, ciudad dorada', 'Fat City', 1972, 'John Huston', 'En Stockton, ciudad de California, un veterano púgil en decadencia (Stacy Keach), que sobrevive trabajando como jornalero agrícola, conoce a un muchacho que quiere ser boxeador (Jeff Bridges) y se lo recomienda a su antiguo mánager, otro perdedor. "Fat City" es una expresión de la jerga boxística que quiere decir "paraíso en la tierra".', '/7ag7BOMnAuDKwNyI0wc8jTeimRb.jpg', '/fHKyWtxGIDQ21JcL7Le6rmX36Q1.jpg', 7.1, 'sVXhoiS0BPA', array['1001']::text[], 560, null, 'segura', null),
(4593, 'movie', 'El discreto encanto de la burguesía', 'El discreto encanto de la burguesía', 'Le Charme discret de la bourgeoisie', 1972, 'Luis Buñuel', 'Don Rafael Costa, embajador de Miranda, y el matrimonio Thévenot están invitados a cenar en casa del matrimonio Sénechal, pero a causa de un malentendido tienen que ir a un restaurante. Cuando llegan, no pueden cenar porque el dueño del lugar ha muerto. A partir de ese momento, las reuniones de este selecto grupo de burgueses se verán siempre interrumpidas por las circunstancias más extrañas, algunas reales y otras fruto de su imaginación.', '/j9BVYh3zd7hG0Iycem9QOs2moot.jpg', '/z6NI6n5MvQZMZJbXKLiyFl1yDeA.jpg', 7.4, 'T7XNFYdQ8S8', array['1001']::text[], 560, null, 'segura', null),
(10310, 'movie', 'Las amargas lágrimas de Petra von Kant', 'Las amargas lágrimas de Petra von Kant', 'Die bitteren Tränen der Petra von Kant', 1972, 'Rainer Werner Fassbinder', 'Petra von Kant, una diseñadora de moda que acaba de separarse de su marido, vive con su secretaria-esclava Marlene (personaje simbólicamente mudo). Cuando su amiga y confidente Sidonie le presenta a Karin, una joven de origen humilde, se enamora locamente de ella y le promete que va a convertirla en una famosa modelo. Sin embargo, Karin la abandona poco tiempo después para irse con su marido que, después de un viaje, acaba de volver a Frankfurt. Petra cae entonces en una profunda depresión.', '/fQ2oi238sfJqbb7gJTotIQchoQJ.jpg', '/kyVtVCs493JAL3lxfSC8UrGbrwS.jpg', 7.4, 'eq0w_XsEAAU', array['1001']::text[], 561, null, 'segura', null),
(573, 'movie', 'Frenesí', 'Frenesí', 'Frenzy', 1972, 'Alfred Hitchcock', 'En el Támesis ha aparecido una mujer estrangulada con indicios de haber sido violada.  Días más tarde, aparece el cadáver de la señora Blaney, estrangulada también, que era dueña de una agencia matrimonial que contactaba parejas.  Todas las sospechas recaen sobre el señor Blaney como principal autor de los asesinatos hasta que aparece muerte una camarera amiga suya.', '/6K4ETSV7NRzJOVatqB1lQDxtsFX.jpg', '/feiECea2yhyiNRAfvqXzbQFgR1W.jpg', 7.1, 'As0nPLCMU7g', array['1001']::text[], 562, null, 'segura', null),
(692, 'movie', 'Pink Flamingos', 'Pink Flamingos', 'Pink Flamingos', 1972, 'John Waters', 'Babs Johnson (Divine), una guarra que vive con su gorda madre y su hijo en una caravana, acaba de ser nombrada la persona más inmunda del mundo por un periódico local. Pero los Marble, un matrimonio que, entre otras cosas, vende heroína en los colegios y venden bebés a lesbianas, no pueden consentir que Divine les supere en suciedad y depravacion, así que deciden tomar cartas en el asunto... Un filme no apto para mentes sensibles que contiene pornografía, canibalismo, escatología y zoofilia, entre otras cosas. (FILMAFFINITY)', '/10N8SvTQwUqyWgocPam1P18Jgr.jpg', '/uh1zf6Q0UcHaqWQXZXu1qOOSCRg.jpg', 6.1, 'vUd_6FF4AtM', array['1001']::text[], 563, null, 'segura', null),
(9277, 'movie', 'El golpe', 'El golpe', 'The Sting', 1973, 'George Roy Hill', 'En Illinois, en 1936, dos ladrones dan un golpe a un hombre de confianza de un gángster y se embolsan un montón de dinero. El gángster decide vengarse y mata a uno de los que dieron el golpe, mientras que el otro logra escapar y entra en contacto con un ex compinche. Los dos deciden intentar un gran timo que hará temblar las finanzas del jefe de la mafia.', '/cnCv2NhtymMwq5oWSzoz6tXcjQf.jpg', '/1r9lH3DaSWKGyvZaoo6BF5STOk5.jpg', 8.0, 'UZ4CuWPnfeM', array['1001']::text[], 564, null, 'segura', null),
(21968, 'movie', 'Superfly', 'Super Fly', 'Super Fly', 1972, 'Gordon Parks Jr.', 'Priest es un traficante de cocaína que disfruta de una vida lujosa en Harlem, pero sabiendo que tarde o temprano acabará muerto o en prisión, decide que quiere retirarse del negocio de la droga. Pero antes de hacerlo quiere dar su mayor golpe: vendiendo 30 kilos de cocaína a cambio de medio millón de dólares.', '/lCj4IZ9l8NfOEiM4zHq3BRF2LzX.jpg', '/468tPHO5kZY6V1ceWxMKXrGMQy4.jpg', 6.3, '4SqdLsCsjYw', array['1001']::text[], 564, null, 'segura', null),
(48693, 'movie', 'La maman et la putain', 'La mamá y la puta', 'La Maman et la Putain', 1973, 'Jean Eustache', 'Alexandre es un joven burgués cínico y egoísta que vive en París. Se encuentra en un fase nihilista de su existencia: no estudia, no trabaja y apenas se interesa por los libros o por la música. Lo único que le interesa son las mujeres y, además, vive a su costa. Poco a poco va formando con Marie y Veronique, a pesar de la inicial resistencia de ambas, un atípico ''menage à trois'', que, para él, es absolutamente satisfactorio porque representa un equilibrio entre lo sexual, lo maternal y lo material. Al mismo tiempo, es capaz de mantenerse al margen de los sentimientos de frustración o malestar que su conducta pueda provocar en sus amantes.', '/wDbguEVHet9w8yRGcl0vVk01UrB.jpg', '/d7f7Dq0I5SuevNHVqLwInQq3EBr.jpg', 7.3, '4taaEWrw-IY', array['1001']::text[], 565, null, 'segura', null),
(3133, 'movie', 'Malas tierras', 'Malas tierras', 'Badlands', 1973, 'Terrence Malick', 'Dakota del Sur, 1959. Cuando el joven Kit Carruthers (Martin Sheen) conoce a Holly (Sissy Spacek), decide dejar atrás su mediocre vida y alcanzar el triunfo sea como sea. Pero tras un trágico incidente, ambos jóvenes se convierten en fugitivos.', '/kzsNBEiSN9tciZCTNMeS91s2Gdv.jpg', '/5rp9Jydh9RxrvVBW2lr27B8NYiT.jpg', 7.4, 'qKykxE7CBbc', array['1001']::text[], 566, null, 'segura', null),
(838, 'movie', 'American Graffiti', 'American Graffiti', 'American Graffiti', 1973, 'George Lucas', 'Es la última noche del verano de 1962, y los jóvenes de Modesto, California, quieren divertirse antes de que lleguen sus resonsabilidades como adultos. Así, todos los adolescentes del pueblo salen esa noche para beber, ligar, pasearse con el coche, ir a la bolera o bailar un rato...', '/9rvox1lGhLtUj0djMtr44CuxYE1.jpg', '/xdofxnT2FADbSFOJflOTLnCoZe9.jpg', 7.1, 'hH0FXaU3e-A', array['1001']::text[], 568, null, 'segura', null),
(9461, 'movie', 'Operación Dragón', 'Operación Dragón', 'Enter the Dragon', 1973, 'Robert Clouse', 'Un joven, experto en artes marciales, es reclutado por el servicio de inteligencia inglés. Su misión es viajar a Hong Kong y desenmascarar las fraudulentas actividades de un hombre de negocios.', '/ssZnHf4cPRJGpQGv9unW8B76nrb.jpg', '/jakcWheJ40mXjSgZnoDZtJxLl0u.jpg', 7.4, 'CDUw0ruKzNY', array['1001']::text[], 569, null, 'segura', null),
(5924, 'movie', 'Papillon', 'Papillon', 'Papillon', 1973, 'Franklin J. Schaffner', '"Papillon", un hombre condenado por asesinato, es enviado a un penal de la Guayana francesa. Durante el viaje en barco, conoce a Luis Dega, falsificador de Bonos de la Defensa Nacional, un hombre débil, al que "Papillon" ofrece protección a cambio del dinero que necesita para huir de la cárcel.', '/vGlAIgHUk24aE4qD9LUVJXhtZXV.jpg', '/fmd17jnQxHanXC6wqqXRLocm60O.jpg', 7.8, 'uJ3BOD7bcRc', array['1001']::text[], 569, null, 'segura', null),
(203, 'movie', 'Malas calles', 'Malas calles', 'Mean Streets', 1973, 'Martin Scorsese', 'Nueva York, 1972. Charlie (Harvey Keitel) es un joven italoamericano de 27 años que trata de ascender en la mafia de Nueva York, pero dicho ascenso se ve obstaculizado por su sentimiento de responsabilidad hacia su imprudente amigo, Johnny Boy (Robert De Niro).', '/gSnb0P5xAXXeSqdXe2nPmkJOy5C.jpg', '/qdecDSIVoqctIoYoOhLH3TgSYLD.jpg', 7.0, 'g9xHpS10CZ0', array['1001']::text[], 570, null, 'segura', null),
(1847, 'movie', 'El largo adiós', 'Un largo adiós', 'The Long Goodbye', 1973, 'Robert Altman', 'Una noche de verano, Terry Lennox aterriza en el ático de su amigo Philip Marlowe y le pide que lo acompañe hasta la frontera mejicana para cambiar de aires. Marlowe acepta la propuesta, pero al regresar a su casa se encuentra con que la policía le pide explicaciones sobre ese viaje. Marlowe termina entre rejas acusado de complicidad en el asesinato de la mujer de Terry, que ha aparecido brutalmente apaleada', '/3qiEp9ElWRWI8vIdQDuDr9BGUqu.jpg', '/eXCKkX8LVo1vRK4GhVoo0bA8jHM.jpg', 7.4, 'XqLUx8RF0EQ', array['1001']::text[], 572, null, 'segura', null),
(16307, 'movie', 'The Wicker Man', 'El hombre de mimbre', 'The Wicker Man', 1973, 'Robin Hardy', 'Una carta que hace sospechar que una joven desaparecida ha sido asesinada lleva al sargento Howie de Scotland Yard hasta Summerisle, una isla en la costa de Inglaterra. Allí el inspector se entera de que hay una especie de culto pagano, y conoce a Lord Summerisle, el líder religioso de la isla.', '/qeNitlsX0CMxj4of9UM9cVuvUIN.jpg', '/qhPuXbHCIbE94doMxYsY2W3wMry.jpg', 7.3, 'MXq-NuS24fg', array['1001']::text[], 572, null, 'segura', null),
(1675, 'movie', 'La noche americana', 'La noche americana', 'La Nuit américaine', 1973, 'François Truffaut', 'El rodaje de una película tropieza con una serie de dificultades que afectan tanto a los miembros del equipo como a la propia película.', '/ngHxfiyt8JO3cCU5ljRxHu5tqj9.jpg', '/6MbFN88F27WvGC9WhAXq5KUIgTj.jpg', 7.8, 'GmSpeM5Hj2A', array['1001']::text[], 573, null, 'segura', null),
(931, 'movie', 'Amenaza en la sombra', 'Amenaza en la sombra', 'Don''t Look Now', 1973, 'Nicolas Roeg', 'Para intentar superar la reciente y trágica pérdida de su hija, el arquitecto John Baxter y su mujer Laura se trasladan a Venecia con el encargo de restaurar una vieja iglesia. Durante su estancia conocerán a un par de ancianas que dicen haber entrado en comunicación con su difunta hija y que les advierten de un peligro inminente.', '/iQF9xwvo5uNK7QTtge8TBlHySqk.jpg', '/8qi3gplNf48uLZnne09iiL4OvFG.jpg', 6.9, 'xXP8OaJGxrM', array['1001']::text[], 574, null, 'segura', null),
(11561, 'movie', 'El dormilón', 'El dormilón', 'Sleeper', 1973, 'Woody Allen', 'Tras permanecer 200 años en estado de hibernación, Miles Monroe, clarinetista y propietario de una tienda de comida sana, despierta en el año 2.174 en una América regida por un estado policial que vigila día y noche a todos los habitantes del país, es decir, a aquellos que habiendo sido ciudadanos han dejado de serlo para convertirse en súbditos, en autómatas.', '/zMRkYV675OhlLesmP8DyvqE8Zed.jpg', '/uVTEJPLof6fizkWvmhxEprut9oQ.jpg', 6.8, 'PcaXIWYDo-4', array['1001']::text[], 575, null, 'segura', null),
(9040, 'movie', 'Serpico', 'Serpico', 'Serpico', 1973, 'Sidney Lumet', 'Años 70. Relato biográfico sobre Frank Serpico, un policía íntegro, de principios incorruptibles que, a diferencia de sus colegas, nunca se dejó sobornar y, precisamente por ello, siempre tuvo problemas con sus compañeros de profesión y se vio expuesto a situaciones muy peligrosas.', '/wrtRPZcMPDdHyRMP8akf6QxRDPS.jpg', '/dXlO2Ri2RvVYWRtBsr6GsIVkleX.jpg', 7.5, 'eoP6bH2ymFo', array['1001']::text[], 575, null, 'segura', null),
(9552, 'movie', 'El exorcista', 'El exorcista', 'The Exorcist', 1973, 'William Friedkin', 'Regan es una niña de doce años víctima de fenómenos paranormales como la levitación o la manifestación de una fuerza sobrehumana. Su madre, aterrorizada, tras someter a su hija a múltiples análisis médicos que no ofrecen ningún resultado, acude a un sacerdote con estudios de psiquiatría. Éste está convencido de que el mal no es físico sino espiritual, es decir, que la niña es víctima de una posesión diabólica. Por eso, con la ayuda de otro sacerdote decide practicar un exorcismo.', '/hwJvgHQ4tf9eRQec1ouAgg33dPV.jpg', '/xcjJ5khg2yzOa282mza39Lbrm7j.jpg', 7.7, 'BU2eYAO31Cc', array['1001']::text[], 576, null, 'segura', null),
(21035, 'movie', 'Delicias turcas', 'Delicias turcas', 'Turks Fruit', 1973, 'Paul Verhoeven', 'Un escultor holandés (Rutger Hauer) mantiene un tormentoso y erótico romance con una hermosa muchacha. En otro tiempo, el artista era un libertino que coleccionaba en un álbum sus conquistas amorosas como si fueran trofeos.', '/7X7f4SPNeqVgV9FTh3H2ubV0mX4.jpg', '/2YtfWnpSGfy1vIskzpl24ZOzIBS.jpg', 6.9, 'D6of8iM3bw4', array['1001']::text[], 578, null, 'segura', null),
(4495, 'movie', 'El espíritu de la colmena', 'El espíritu de la colmena', 'El espíritu de la colmena', 1973, 'Víctor Erice', 'Ocurrió en un pueblo castellano a mediados de los años cuarenta, es decir, en plena postguerra. Un domingo, Isabel y Ana, dos hermanas de ocho y seis años respectivamente, vieron la película "El Doctor Frankenstein". A la pequeña le causó tal impresión que no dejaba de hacer preguntas sobre el monstruo a su hermana mayor. Cierto día, la familia se dio cuenta de que Ana había desaparecido de la casa. Y mientras todo el pueblo la buscaba, ella consiguió ver a Frankenstein reflejado en las aguas del río por la luz de la luna. Y desde entonces lo sigue invocando', '/ueefcFKn9qoAQqjSWY6H9xjjLU2.jpg', '/4vbL72K9uVaMLhnvmdg1So7kqex.jpg', 7.6, 'aqvpMJNlqxE', array['1001']::text[], 579, null, 'segura', null),
(16306, 'movie', 'El planeta salvaje', 'El planeta salvaje', 'La Planète sauvage', 1973, 'René Laloux', 'En el planeta Ygam, los Draags, humanoides azules extremadamente avanzados tecnológica y espiritualmente, consideran a los diminutos Oms, seres humanos descendientes de los habitantes de Terra, como animales ignorantes. Los que viven en la esclavitud son tratados como simples mascotas y utilizados para entretener a los niños Draag; los que viven escondidos en los hostiles desiertos del planeta son periódicamente cazados y masacrados sin piedad como si fueran alimañas.', '/skuBfcttPSVrnaOvdDRbIvHUIOI.jpg', '/AwrqoanoZVYoc0MRyE0RiHEKm71.jpg', 7.6, 'LE3AaxGKaEg', array['1001']::text[], 579, null, 'segura', null),
(7857, 'movie', 'Amarcord', 'Amarcord', 'Amarcord', 1973, 'Federico Fellini', 'Historia de un hombre que un día se da cuenta de que apenas reconoce a las personas con las que ha vivido durante años, hasta el punto de que su propia esposa e hijos le parecen extraños y todo lo que lo rodea le resulta opaco e indiferente. Se lanza entonces a la búsqueda desesperada de algún punto de referencia para recuperar su identidad y no hundirse en el caos. Emprende así, a través de las ilimitadas regiones de la memoria, un viaje que lo conduce a la infancia, a la época en que era un niño que vivía en un pequeño pueblo costero; a la Italia de los años treinta, cuando el fascismo había alcanzado el punto culminante de su apogeo.', '/i2BL91OVOONviajAE0VlbMAyOm9.jpg', '/iFQzlUmO5QmMPcSHHDdfd522x33.jpg', 7.9, 'BtG9ZM-ZHnY', array['1001']::text[], 580, null, 'segura', null),
(618162, 'movie', 'Más dura será la caída', 'Más dura será la caída', 'The Harder They Fall', 2021, 'Jeymes Samuel', 'El forajido Nat Love (Jonathan Majors) descubre que su enemigo, Rufus Buck (Idris Elba) ha salido de prisión, por lo que reúne a su banda para perseguir a Rufus y buscar venganza.', '/wN9CuMsgohrfud5Y9eP3WL0M5Tu.jpg', '/d0mpUFKzoPwF1KsdjHpkkaYSvKm.jpg', 6.6, 'T0V9TjyA890', array['1001']::text[], 582, null, 'dudosa', '[{"tmdb_id": 618162, "titulo": "Más dura será la caída", "original": "The Harder They Fall", "anio": 2021, "votos": 1266, "poster_path": "/wN9CuMsgohrfud5Y9eP3WL0M5Tu.jpg", "sim": 1.0}, {"tmdb_id": 28528, "titulo": "Más dura será la caída", "original": "The Harder They Fall", "anio": 1956, "votos": 162, "poster_path": "/2xQS5EPxpRHUsOYNVDRAV2onuFV.jpg", "sim": 1.0}, {"tmdb_id": 111178, "titulo": "Jane Doe: Más dura será la caída", "original": "Jane Doe: The Harder They Fall", "anio": 2006, "votos": 8, "poster_path": "/FDlLS4EwVcaq4dIsGqieRTwHpv.jpg", "sim": 0.83}]'::jsonb),
(11577, 'movie', 'Pat Garrett y Billy the Kid', 'Pat Garrett y Billy el Niño', 'Pat Garrett & Billy the Kid', 1973, 'Sam Peckinpah', 'La historia de Pat Garrett y Billy the Kid, los dos compañeros de fatigas y temidos forajidos que en el Viejo Oeste tomaron rumbos separados para uno de ellos, Pat, convertirse en sheriff y el otro, Billy, seguir viviendo sin horizontes, cansado y sin dirección.', '/eGfUVB3myNH4T8qa48SYkfw50RO.jpg', '/mEEJC1tHmxJZ49L0Gc7jsFlvQXJ.jpg', 7.2, 'RbGE0xx6w4A', array['1001']::text[], 582, null, 'segura', null),
(9764, 'movie', 'Dersu Uzala', 'Dersu Uzala (El cazador)', 'Дерсу Узала', 1975, 'Akira Kurosawa', 'Un explorador del ejército conoce a un hombre de la tribu Goldi en los bosques no mapeados de Rusia. Con el tiempo, se crea un vínculo duradero entre los dos hombres: uno civilizado en el sentido usual, y el otro que tiene por hogar los bosques glaciares de Siberia.', '/xYWPyzDfCmX6xK51wwGNkQNA9fv.jpg', '/33hRze5MIFzwV2MR3kF5QzPkgjR.jpg', 7.9, 'oXGB-dKchz8', array['1001']::text[], 583, null, 'segura', null),
(592, 'movie', 'La conversación', 'La conversación', 'The Conversation', 1974, 'Francis Ford Coppola', 'Harry Paul, un detective cuyo prestigio como especialista en vigilancia y en sistemas de seguridad es reconocido por sus colegas en todo el país, recibe el encargo por parte de un magnate de investigar a su joven esposa. Deberá escuchar sus conversaciones con un empleado del marido, del que ella parece estar enamorada. La misión, para un experto de su categoría, resulta a primera vista inexplicable, ya que la pareja no ofrece ningún interés fuera de lo corriente. Sin embargo, cuando Harry da por finalizado su trabajo, advierte que algo extraño se oculta tras la banalidad que ha estado investigando, ya que su cliente se niega a identificarse, utilizando siempre intermediarios.', '/g4bVCc10hpWEiYaSdhL4Jo6MetA.jpg', '/s7yfiwIshKQIT6M8ZcTnFKXHs8B.jpg', 7.5, '9XGovTqAF60', array['1001']::text[], 584, null, 'segura', null),
(30497, 'movie', 'La matanza de Texas', 'La matanza de Texas', 'The Texas Chain Saw Massacre', 1974, 'Tobe Hooper', 'Cinco adolescentes visitan la tumba, supuestamente profanada, del abuelo de uno de ellos. Cuando llegan al lugar, donde hay un siniestro matadero, toman una deliciosa carne en una gasolinera. A partir de ese momento, los jóvenes vivirán la peor pesadilla de toda su vida.', '/dDuWWq9VpBK0PFCDytlBpZhV6ca.jpg', '/wvBx1Q1FcQE1BPLfBbgA3y9aaS1.jpg', 7.3, 'iSxFeBdcqeE', array['1001']::text[], 585, null, 'segura', null),
(1396, 'movie', 'Zerkalo (El espejo)', 'El espejo', 'Зеркало', 1975, 'Andréi Tarkovski', 'Un hombre, Alekséi, habla con su esposa sobre su situación actual y los motivos por los que se han distanciado. La película es una evocación continua de recuerdos y sentimientos que viajan en diferentes tiempos sin orden aparente: la relación con su madre, su infancia,...que se mezclan con material fílmico de noticiario sobre la Guerra civil española, la Segunda guerra mundial y el enfrentamiento entre la URSS y China por la isla Damanski. En la película suenan poemas escritos y recitados por Arseni Tarkovski, padre del director. Retrata un pasado que es el suyo, pero también el de un país y el del acontecer mundial.', '/hLzhdirfOApuoXoS8SnGNotu1bf.jpg', '/9UAcMhSCDJ2OCo5QdPpSERjhMA1.jpg', 7.9, 'S2U9TXmYJ94', array['1001']::text[], 586, null, 'segura', null),
(3034, 'movie', 'El jovencito Frankenstein', 'El jovencito Frankenstein', 'Young Frankenstein', 1974, 'Mel Brooks', 'El nieto del legendario doctor Frankenstein se ha convertido en un reconocido neurocirujano que debe hacerse cargo del castillo de su abuelo. Ayudado por el jorobado Igor y una escultural asistente decide recrear el experimento de su ancestro.', '/ai5w3uAAwqeKdJhypxo9zZVCizC.jpg', '/rsI82F7DadIQcrZyPbuwmkhN5ty.jpg', 7.9, 'Y8v2YNOdwnM', array['1001']::text[], 587, null, 'segura', null),
(29845, 'movie', 'Una mujer bajo la influencia', 'Una mujer bajo la influencia', 'A Woman Under the Influence', 1974, 'John Cassavetes', 'Nick (Peter Falk), un hombre de la construcción, tiene que cargar con la responsabilidad de cuidar a su mujer (Gena Rowlands) que padece inestabilidad emocional. Continuamente lucha por mantener la normalidad ante su extraño comportamiento, hasta que éste afecta sus hijos y será necesario que tome medidas.', '/xX9xyqocEh4OvkhGip9m9JjXNTe.jpg', '/uOLcJJYZ3hbFSrKQPDaLhrYnjUv.jpg', 7.7, 'd5O7ujg3VQU', array['1001']::text[], 587, null, 'segura', null),
(829, 'movie', 'Chinatown', 'Chinatown', 'Chinatown', 1974, 'Roman Polanski', 'Los Ángeles, 1937. El detective Gittes, especializado en divorcios, recibe la visita de la esposa de Mulwray, el jefe del Servicio de Aguas de la ciudad, que sospecha que su marido la engaña. Al mismo tiempo, Gittes descubre que los agricultores acusan a Mulwray de corrupción por su negativa a construir un pantano que paliaría la sequía que sufren. Poco después, el escándalo salta a la prensa, pero la cosa se complica cuando una mujer se presenta en el despacho de Gittes con una sorprendente revelación.', '/1wO2OmUCWButQyVPGWQEZn5twca.jpg', '/pyvkujOZ5qvY2NlQVC71flfgVWE.jpg', 7.9, 'RKdXf-fiBcw', array['1001']::text[], 588, null, 'segura', null),
(27019, 'movie', 'Céline et Julie vont en bateau', 'Celine y Julie van en barco', 'Céline et Julie vont en bateau', 1974, 'Jacques Rivette', 'Muy cerca de la tradición de los cuentos infantiles, la película narra las relaciones entre la bibliotecaria Julie y Céline, y cómo ésta introduce a la primera en una historia, entre la realidad y la fantasía, que se desarrolla en una gran mansión aislada donde vive un viudo, su hija de 8 años y dos mujeres.', '/fkp4RV0UKUA3Yj4FpZ5xsZxEgQW.jpg', '/b5GLJlkFFv4gIVPHAoBUQij1JL1.jpg', 6.8, 'CcVuBjWpIEI', array['1001']::text[], 590, null, 'segura', null),
(11072, 'movie', 'Sillas de montar calientes', 'Sillas de montar calientes', 'Blazing Saddles', 1974, 'Mel Brooks', 'El avaricioso gobernador Lepetomane y su malvado ayudante Hedley Lamarr quieren que los habitantes de Rock Ridge abandonen la ciudad, para vender los terrenos a una compañía de ferrocarril. Para facilitar sus maquiavélicos planes, nombran sheriff a Bart, un negro condenado a la horca, para que fomente el desorden y la anarquía en la ciudad.', '/kDvMQxOR91G3kwF6jEYqmg31Bjx.jpg', '/syUzOlwPqM8pGRhUxPOnmrcGcHb.jpg', 7.2, 'tb2fYUKJdN8', array['1001']::text[], 591, null, 'segura', null),
(240, 'movie', 'El padrino II', 'El padrino II', 'The Godfather Part II', 1974, 'Francis Ford Coppola', 'Dos historias en paralelo: Michael consolidando el imperio familiar en los años 50 y la juventud de Vito Corleone, desde Sicilia hasta la Nueva York de principios de siglo.', '/mbry0W5PRylSUHsYzdiY2FSJwze.jpg', '/pGzqRKrYeK4LogoysNro0vG8d8N.jpg', 8.6, 'rMT8b3MJ-RI', array['1001','clasicos']::text[], 592, null, 'segura', null),
(216, 'movie', 'Todos nos llamamos Alí', 'Todos nos llamamos Alí', 'Angst essen Seele auf', 1974, 'Rainer Werner Fassbinder', 'En un café al que acuden los trabajadores inmigrantes, Emmi Kurowski, una viuda de unos sesenta años, conoce a Salem, un marroquí treintañero. Inducido por la dueña del bar, Salem invita a Emmi a bailar, hablan, la acompaña a casa y, al día siguiente, se queda a vivir con ella. Esta relación provoca un gran escándalo, y las vecinas visitan al propietario del edificio para denunciar a Emmi.', '/wXmccDfWRyCyV9vdQlJgzQnIIdu.jpg', '/ih2q5hoclUTICLxMzV31vxgpCzR.jpg', 7.7, 'KG12cB5xGCo', array['1001']::text[], 594, null, 'segura', null),
(11942, 'movie', 'Quiero la cabeza de Alfredo García', 'Quiero la cabeza de Alfredo García', 'Bring Me the Head of Alfredo Garcia', 1974, 'Sam Peckinpah', 'La acción gira en torno a la obsesión de un potentado terrateniente mejicano obsesionado por acabar con el hombre que ha dejado embarazada a su hija. No vacilará en ofrecer una generosa recompensa a quien le entregue la cabeza de quien ha mancillado el honor de su hija, cabeza que se convertirá en el centro de una amarga disputa a lo largo de toda la película.', '/zKrHI7IOqmjfzYMmTzttlyDEZPW.jpg', '/3U84leD4UV9HadHEHceZp9y2T6y.jpg', 7.1, 'ZSa7f_igHzc', array['1001']::text[], 595, null, 'segura', null),
(968, 'movie', 'Tarde de perros', 'Tarde de perros', 'Dog Day Afternoon', 1975, 'Sidney Lumet', 'Unos delincuentes de poca monta deciden atracar la sucursal de un banco de Brooklyn. Sin embargo, debido a su inexperiencia, el robo, que había sido planeado para ser ejecutado en apenas diez minutos, se convierte en una trampa para los atracadores y en un espectáculo para la televisión en directo.', '/ctcUXNlnddo9ndUK0w7w6CZQpig.jpg', '/ahqTRP5mPOm3fMO8WjXbHlaF4Mo.jpg', 7.9, '3STmwLDDBcI', array['1001']::text[], 595, null, 'segura', null),
(510, 'movie', 'Alguien voló sobre el nido del cuco', 'Alguien voló sobre el nido del cuco', 'One Flew Over the Cuckoo''s Nest', 1975, 'Miloš Forman', 'Randle McMurphy (Jack Nicholson), un violador de espíritu libre, que vive contracorriente, es recluido en un hospital psiquiátrico. La inflexible disciplina del centro acentúa su contagiosa tendencia al desorden, que acabará desencadenando una guerra entre los pacientes y el personal de la clínica con la fría y severa enfermera Ratched (Louise Fletcher) a la cabeza. La suerte de cada paciente del pabellón está en juego.', '/lBYmCynNEPt7HVaJvuXgfHvLhbJ.jpg', '/uA8eSNAUUUyfHNIrG4h0zHxzt9W.jpg', 8.4, 'F4da9uRIg8c', array['1001']::text[], 596, null, 'segura', null),
(44012, 'movie', 'Jeanne Dielman, 23 quai du Commerce, 1080 Bruxelles', 'Jeanne Dielman, 23 quai du Commerce, 1080 Bruxelles', 'Jeanne Dielman, 23, quai du Commerce, 1080 Bruxelles', 1976, 'Chantal Akerman', 'La vida de Jeanne Dielman, una joven viuda con un hijo, sigue un orden inmutable: mientras el muchacho está en la escuela, ella se ocupa de las tareas domésticas por la mañana y ejerce la prostitución por la tarde.', '/b5cey5yKfPXZBwj2gTRREALUvzA.jpg', '/2qL6rsvq29ueZ0ITh47Jj2F985R.jpg', 7.4, 'iuP1MN6RNJU', array['1001']::text[], 597, null, 'segura', null),
(36685, 'movie', 'The Rocky Horror Picture Show', 'The Rocky Horror Picture Show', 'The Rocky Horror Picture Show', 1975, 'Jim Sharman', 'Cuando una pareja regresa de la boda de unos amigos, estalla una violenta tormenta y el coche se les avería. Así las cosas, no tienen más remedio que refugiarse en un castillo, donde el doctor Frank-N-Furter vive entregado a la fabricación de una especie de Frankenstein.', '/6xJuXrwpXHCJW51d3EJHGj3ZbM2.jpg', '/54aVU7tnvDKkX6ibzFg6ke03BV.jpg', 7.4, '4plqh6obZW4', array['1001']::text[], 598, null, 'segura', null),
(22460, 'movie', 'Deewar (La pared)', 'दीवार', 'दीवार', 1975, 'Yash Chopra', 'Haunted by the past, Vijay turns to crime, while Ravi, his brother, becomes an honest police officer. Fate pits them against each other when Ravi is sent to nab Vijay.', '/alVHFaerbSgnuKhzSddJRNiCs8g.jpg', '/lx94BR9gILXSGptjaUSUPveBjJu.jpg', 7.2, 'DuJ_7UVyGIc', array['1001']::text[], 600, null, 'segura', null),
(762, 'movie', 'Los caballeros de la mesa cuadrada', 'Los caballeros de la mesa cuadrada y sus locos seguidores', 'Monty Python and the Holy Grail', 1975, 'Terry Jones, Terry Gilliam', 'El rey Arturo y sus caballeros reciben un encargo divino: partir en búsqueda del Santo Grial, para lo cual deberán luchar contra enemigos muy diversos: malignos caballeros rivales, bestias sanguinarias (que solo son visibles como dibujo animado), groseros caballeros franceses fortificando un castillo en Inglaterra, brujas, adivinos mefistofélicos, Scotland Yard, y hasta un conejo asesino y carnívoro (que muere destruido por una cómica reliquia traída de las Cruzadas: la "Santa Granada de Mano de Antioquia").', '/sbxnHlkHSeffxwzPhnfwd42ojqQ.jpg', '/1KgXxv6tHXOnakqYvMPvFwYKWiw.jpg', 7.8, '4b52A3sKz-I', array['1001']::text[], 601, null, 'segura', null),
(3175, 'movie', 'Barry Lyndon', 'Barry Lyndon', 'Barry Lyndon', 1975, 'Stanley Kubrick', 'Siglo XVIII. El joven Redmond Barry, huérfano de padre, se ha enamorado de su prima, a la que también pretende el Capitán John Quin. El asunto se resuelve por medio de un duelo, del que Redmond resulta vencedor. A continuación se va a Dublín y decide alistarse en el ejército inglés, donde empieza a desarrollar sus extraordinarias habilidades para sobrevivir. Estando en Alemania, se le presenta la posibilidad de desertar, pero es capturado por el Capitán Potzdorf, un oficial prusiano que le ofrece la posibilidad de unirse a sus tropas o ser colgado por desertor. Una vez en el ejército prusiano, tiene la fortuna de salvarle la vida a Potzdorf, lo que le abre las puertas del servicio secreto prusiano.', '/x28u4tvapVCPaVWHyvrEyLZWyk8.jpg', '/ef6SvWbSfCFlKodJZqpIaTvsRRP.jpg', 8.0, 'JH8j_1dUlUU', array['1001']::text[], 602, null, 'segura', null),
(42254, 'movie', 'La ley del más fuerte', 'La ley del más fuerte', 'Faustrecht der Freiheit', 1975, 'Rainer Werner Fassbinder', 'Franz Biberkopf es un joven homosexual, vulgar, ingenuo y bonachón que, después de trabajar como "Fox, la cabeza parlante" en una feria, gana medio millón de marcos en la lotería, lo que le permite frecuentar círculos gays más selectos. En este exquisito ambiente se enamora de Eugen, hijo de un empresario que posee una imprenta al borde de la bancarrota. Eugen, que ha dejado a su amante, inicia con Franz una relación interesada: en varias ocasiones le saca dinero para la empresa paterna, le hace comprar el piso y los muebles que compartirán, e intenta incluso corregirle sus toscos modales tan alejados de la educación burguesa. Además, programa un viaje a Marrakech.', '/7xKxykQeUDGTCp8Fv4mVjVHNCT7.jpg', '/shIMqYeRZArmAsUe3FYGhHgWAkM.jpg', 7.2, 'cVZ6_TZDo8Q', array['1001']::text[], 603, null, 'segura', null),
(85927, 'movie', 'India Song', 'India Song', 'India Song', 1975, 'Marguerite Duras', 'Recreación de la India de los años 30 a través de la historia de Anne-Marie, la esposa del vice-cónsul francés en el país. Harta del tedio cotidiano en que se ha convertido su vida, la mujer inicia una serie de aventuras amorosas que su marido conoce, pero pretende ignorar.', '/p9TcpsGmp0c0fg72uQK5X1QMYaq.jpg', '/fBh1T0i1ODGiD8BNcQ4VGfdfTeN.jpg', 6.3, 'KKyfTot69lc', array['1001']::text[], 604, null, 'segura', null),
(11020, 'movie', 'Picnic en Hanging Rock', 'Picnic en Hanging Rock', 'Picnic at Hanging Rock', 1975, 'Peter Weir', 'El día de San Valentín de 1900, las estudiantes de la Escuela Appleyard van de excursión a Hanging Rock, una región australiana montañosa. A lo largo del día se producen una serie de fenómenos sobrenaturales: el tiempo se detiene, estudiantes y maestras pierden el conocimiento y tres chicas y una profesora desaparecen.', '/eDi3vqzg7Ay8QNg1Zx4JpXmx9AK.jpg', '/41Mlaj6wfjlF4wQaVH0tjfDXvMi.jpg', 7.2, 'CFtQMzXZZQs', array['1001']::text[], 604, null, 'segura', null),
(70580, 'movie', 'Maynila: sa mga kuko ng liwanag', 'Manila en las garras de las tinieblas', 'Maynila sa mga Kuko ng Liwanag', 1975, 'Lino Brocka', 'Julio (Bembol Roco), un pescador, viaja a Manila en busca de su amor perdido, Ligaya (Hilda Koronel). Entra en una obra y descubre las injustas prácticas laborales, condiciones laborales peligrosas y distintas tendencias políticas entre sus compañeros. Se ve mezclado en una red de prostitución masculina, descubriendo que Ligaya trabaja en un burdel. Considerada la mejor película filipina de todos los tiempos.', '/AnzRRVXKXmVvh5Qu80bsDbJIs1w.jpg', '/nu5kvLgnLwhdG7l2tJu3Z6ahjCW.jpg', 7.4, '27qwaj9143Q', array['1001']::text[], 605, null, 'segura', null),
(5336, 'movie', 'Salò o los ciento veinte días de Sodoma', 'Saló, o los 120 días de Sodoma', 'Salò o le 120 giornate di Sodoma', 1976, 'Pier Paolo Pasolini', 'En una mansión, cuatro señores se reúnen con cuatro exprostitutas y con un grupo de jóvenes de ambos sexos, partisanos o hijos de partisanos, que han sido hechos prisioneros. Nadie en la casa puede eludir las reglas del juego establecidas por los señores; toda transgresión se castiga con la muerte. Además, ellos gozan de la facultad de disponer a su antojo de la vida de los cautivos.', '/8mYYvtlpyb0NbSzhzcx7PdjhpUY.jpg', '/wP1wgntZ6VIja8hprxV6UKdQugk.jpg', 6.3, 'EtXnuPa1qAA', array['1001']::text[], 606, null, 'probable', null);
